window.__CUBE = {"ソクラテス":[{"t":"核心","ic":"◈","v":"アテナイの街頭で人々に問答をしかけ、当たり前とされる「正義」「勇気」「善」の定義を吟味しつづけた。"},{"t":"本人の言葉","ic":"❝","v":"吟味を欠いた生は、人間にとって生きるに値しない。","by":"プラトン『ソクラテスの弁明』"},{"t":"転回","ic":"⟲","v":"最後の最後まで、彼は断定していません。死のほうが良いとも、生のほうが良いとも言わない。知らないことは知らない、と言ったまま死んだ。彼の一貫性は、そこにあります。"},{"t":"生の事実","ic":"✦","v":"彼は、逃げられた——紀元前399年、アテナイ。70歳の男が死刑判決を受け、獄につながれた。罪状は、国家の神々を認めず、若者を堕落させたこと。"},{"t":"最も強い反論","ic":"⚡","v":"彼の擁護者は、彼を「真理のために死んだ聖人」として語ります。だが同時代のアテナイ市民から見れば、彼は30年戦争に負けた直後の疲弊した街で、若者に権威への疑いを吹き込んでいた男でした。実際、彼の弟子から民主政を倒した独裁者が出ています。「問い続けること」は美徳ですが、問いを浴びせられた側にとっては破壊でもあった。この告発を、彼は完全には論破していません。"},{"t":"あなたへ","ic":"→","v":"あなたが今「当然そうすべきだ」と思って従っていることを、誰かに理由を三度続けて問われたら、答えられますか。答えられないものに、あなたは何年従ってきましたか。"}],"プラトン":[{"t":"核心","ic":"◈","v":"移ろう感覚世界の背後に、永遠で完全な「イデア」の世界があると説いた。"},{"t":"本人の言葉","ic":"❝","v":"哲学者が王となるか、王が真に哲学するかしないかぎり、国家の禍いはやまない。","by":"『国家』第5巻"},{"t":"転回","ic":"⟲","v":"人々は信じません。目が慣れずによろけている彼を笑い、外へ出ると目が壊れるのだと言い合う。そしてプラトンは冷たく書き加えます——もし彼が鎖を解こうとするなら、彼らは彼を殺すだろう、と。ソクラテスの話をしていることは、当時の読者にも明白でした。"},{"t":"生の事実","ic":"✦","v":"彼は、師が殺されるのを見た——プラトンは名門の家に生まれ、政治家になるはずでした。実際、親族が政権の中枢にいた時期もあります。"},{"t":"最も強い反論","ic":"⚡","v":"彼が描いた理想国家は、読むと戦慄します。詩人は追放され、物語は検閲され、支配層は家族を持たず、優れた者どうしを配合して子を作る。生まれた子は親から引き離される。国民をまとめるために有益な嘘を用いてよい、とも書かれています。二十世紀にポパーは、これを全体主義の原型として名指ししました。師の死から出発した思想が、なぜこの結論に至ったのか——彼を読む者は、この重さを引き受けなければなりません。"},{"t":"あなたへ","ic":"→","v":"あなたが今日「みんながそう言っているから正しい」と受け入れたことは何ですか。それは影ですか、それとも物ですか。"}],"アリストテレス":[{"t":"核心","ic":"◈","v":"師プラトンのイデアを天上に置く見方を退け、本質は個々の事物の内にあると考えた。"},{"t":"本人の言葉","ic":"❝","v":"一羽の燕は春を作らない。一日もまた然り。","by":"『ニコマコス倫理学』第1巻"},{"t":"転回","ic":"⟲","v":"それは、人間に固有の能力を、十分に発揮しきっている状態です。だから寝ている人は幸福ではない。楽しい気分でいることでもない。生涯を通じて、自分の力を良く働かせ続けている活動そのもの。彼は、それを一日や一瞬では測れないとも言いました。"},{"t":"生の事実","ic":"✦","v":"彼はアテナイで、生涯よそ者だった——アリストテレスはマケドニア北部の出身で、アテナイでは在留外国人でした。土地を所有できず、市民権もない。"},{"t":"最も強い反論","ic":"⚡","v":"彼の著作には、擁護できない部分があります。一部の人間は生まれつき奴隷であり、支配されるのが自然だと明言した。女性を、不完全な形の男性として記述した。これらは余談ではなく、『政治学』と生物学の中核にあります。加えて、彼の権威があまりに巨大だったため、その物理学の誤りは千八百年ものあいだ疑われず、探究をむしろ妨げました。優れた体系は、次の世代にとって牢獄にもなります。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分はこういう性格だ」と思っているものは、どんな行動の繰り返しで作られましたか。逆の行動を三十日続けたら、何が変わりますか。"}],"エピクロス":[{"t":"核心","ic":"◈","v":"快楽こそ善だと説いたが、それは放埒ではなく、心の平静(アタラクシア)という「静かな快」だった。"},{"t":"本人の言葉","ic":"❝","v":"この幸福な日に、そして生涯最後の日に、あなたにこれを書く。膀胱と胃の病は激しく、これ以上ないほどだ。だがそれらすべてに、私たちの語り合いの記憶がもたらす、心の喜びが対抗している。","by":"イドメネウス宛書簡"},{"t":"転回","ic":"⟲","v":"二番目が核心です。死が来たとき、あなたはもういない。あなたがいるとき、死はまだ来ていない。この二つが出会うことは決してない。だから死は、あなたにとって何ものでもない——彼はそう論じました。冷たい論法に見えますが、当時の人々を最も苦しめていた死後の罰の恐怖に対する、まっすぐな解毒剤でした。"},{"t":"生の事実","ic":"✦","v":"彼の学園には、女性と奴隷がいた——アテナイ郊外に「庭園」と呼ばれる共同体を作りました。当時、学園に女性や奴隷を迎える例はほとんどありません。彼は受け入れました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の哲学には、理論的な弱点があります。世界は原子でできており、すべては必然に従う——ならば人間の自由はどこにあるのか。彼は、原子がときどきわずかに逸れるという説を持ち込んで自由を確保しようとしました。だが、なぜ逸れるのかは説明されていません。批判者は、これを都合のために後から足された継ぎ当てだと見ます。加えて、彼の著作三百巻はほぼ全て失われ、私たちは断片と、彼を憎んだストア派やキリスト教側の記述…"},{"t":"あなたへ","ic":"→","v":"あなたの不安を紙に書き出して、実際に起きたことがある割合を数えてみてください。残りは何を恐れていたのですか。"}],"ゼノン(ストア派)":[{"t":"核心","ic":"◈","v":"世界は理性(ロゴス)に貫かれており、人はその宇宙的秩序に調和して生きるべきだと説いた。"},{"t":"本人の言葉","ic":"❝","v":"難破したときこそ、私は最も順調な航海をしたのだ。","by":"ゼノンの言葉と伝えられる"},{"t":"転回","ic":"⟲","v":"宇宙には理法があり、人間はその一部である。そして人間に固有の自然は、理性を持ち、社会的であることだ。だから自然に従うとは、理性的に、そして共同体の一員として生きることを指します。ストア派はしばしば個人的な忍耐の教えと誤解されますが、彼らは世界市民という概念の発明者でもありました。"},{"t":"生の事実","ic":"✦","v":"彼は、全財産を海で失った——キプロス島出身の商人でした。積荷は紫の染料——当時、極めて高価な商品です。"},{"t":"最も強い反論","ic":"⚡","v":"ストア派の最も厳しい主張は、徳さえあれば幸福には十分であり、健康も財産も家族も本質的にはどうでもよい、というものです。子を失った親に、それは自分の力の及ばぬことだから、と説くのは、強さなのか、感情の切除なのか。ストア派自身がこれを難問として抱え続け、後の世代は徐々に表現を和らげました。加えて、変えられないことを受け入れよという教えは、変えるべき不正に対する諦めへ滑りやすい、という政治的な批判があ…"},{"t":"あなたへ","ic":"→","v":"あなたが今いちばん悩んでいることを、変えられるものと変えられないものに分けてください。あなたはどちらに、より多くの時間を使っていますか。"}],"アウグスティヌス":[{"t":"核心","ic":"◈","v":"放縦な青年期からキリスト教へ回心した経験を『告白』に記し、内面を見つめる自己省察の伝統を切り開いた。"},{"t":"本人の言葉","ic":"❝","v":"わたしに貞潔と節制をお与えください。ただし、今はまだ。","by":"『告白』第8巻"},{"t":"転回","ic":"⟲","v":"人間の意志が、単純に一つでないことを示す一行です。彼は本気で望んでいた。同時に、まだ望んでいなかった。知識が足りないのではない。意志そのものが二つに割れて、互いを引っぱっている。彼が発見したのはこの構造でした。"},{"t":"生の事実","ic":"✦","v":"彼は、盗む必要のない梨を盗んだ——少年時代の出来事を、彼は生涯忘れませんでした。仲間と近所の梨の木を襲い、実をもぎ取り、豚に投げ与えて逃げた。"},{"t":"最も強い反論","ic":"⚡","v":"彼の影響には、暗い側面があります。原罪が性の行為を通じて伝わるという彼の理論は、西洋キリスト教が性と身体を長く罪深いものとして扱う土台になりました。また彼は、異端ドナトゥス派に対して国家権力による強制を認める議論を書いており、後の異端審問がそれを引用しています。自分の内面には誰よりも誠実だった人が、他人の内面には強制を許した。"},{"t":"あなたへ","ic":"→","v":"あなたがやめたいのにやめられないことについて。本当にやめたいと思っている自分と、やめたくない自分は、それぞれ何を望んでいますか。"}],"トマス・アクィナス":[{"t":"核心","ic":"◈","v":"アリストテレス哲学とキリスト教神学を大胆に総合した。"},{"t":"本人の言葉","ic":"❝","v":"恩寵は自然を破壊せず、かえってこれを完成する。","by":"『神学大全』第1部"},{"t":"転回","ic":"⟲","v":"この一行が、彼の全体の設計図です。信仰は、人間の自然な能力を否定して上書きするものではない。土台としての自然があり、その上に恩寵が積まれる。だから彼は、人間の理性、感情、身体、社会を、否定すべき障害ではなく、生かすべき素材として扱いました。"},{"t":"生の事実","ic":"✦","v":"同級生は彼を「唖の牛」と呼んだ——大柄で無口な学生でした。授業中ほとんど発言しない。仲間は彼を、鈍い牛だとからかいます。"},{"t":"最も強い反論","ic":"⚡","v":"彼の体系は美しく組まれていますが、土台はアリストテレスの自然学と目的論——すべての事物には本来向かうべき目的がある、という世界像です。近代科学はその世界像を捨てました。物体は目的に向かって落ちるのではなく、法則に従って落ちる。土台が外れたとき、その上の壮大な建築は何を支えにするのか。この問いに、トマス主義は今も答え続けています。"},{"t":"あなたへ","ic":"→","v":"あなたが信じたいことと、頭で考えた結論が食い違ったとき、どちらかを切り捨てていませんか。両方が立つ答えを、探しましたか。"}],"デカルト":[{"t":"核心","ic":"◈","v":"確実な知の土台を求め、疑いうるものをすべて疑う「方法的懐疑」を徹底した。"},{"t":"本人の言葉","ic":"❝","v":"我思う、ゆえに我あり。","by":"『方法序説』1637年"},{"t":"転回","ic":"⟲","v":"デカルトは何度か答えを試み、最後には、これは理解するというより日常の経験で感じるほかない、という趣旨のことを書きます。事実上、答えられませんでした。彼が作った心身の裂け目は、四百年後の脳科学と哲学がいまだに埋められずにいる問題です。哲学史上最強の反論の一つが、大学に入ることも許されなかった女性から出された、という事実も併せて記憶されるべきです。"},{"t":"生の事実","ic":"✦","v":"戦場の宿で、彼は三つの夢を見た——1619年11月10日。三十年戦争の最中、軍に身を置いていた23歳のデカルトは、ドイツの暖炉のある部屋にこもっていました。"},{"t":"最も強い反論","ic":"⚡","v":"心身二元論の副産物は、動物でした。彼は、動物は魂を持たない精巧な機械であり、その悲鳴は時計のきしみのようなものだと考えました。この見解は、当時の生体解剖を正当化する根拠として使われています。人間の内面を確実にするために引いた線が、線の外側を物として扱う許可証になった——理論の切れ味が、そのまま刃物になった例です。"},{"t":"あなたへ","ic":"→","v":"あなたが「絶対に確かだ」と思っていることを一つ、本気で疑ってみてください。疑いきったあと、それでも残るものは何ですか。"}],"スピノザ":[{"t":"核心","ic":"◈","v":"神と自然を同一視し、存在するのはただ一つの無限の実体だけで、精神も物体もその表れ(属性)だと考えた。"},{"t":"本人の言葉","ic":"❝","v":"昼も夜も呪われよ。臥すときも起きるときも呪われよ。……何人も彼と口をきいてはならない。何人も彼と同じ屋根の下にいてはならない。何人も彼の書いたものを読んではならない。","by":"1656年 破門宣告文（要約）"},{"t":"転回","ic":"⟲","v":"原因に支配されているなら自由はない、と普通は考えます。彼は逆でした。原因が分かっていない状態こそ、感情に振り回される奴隷である。なぜ自分が今こう感じているのかを理解したとき、その感情は「受動」から「能動」へ変わる。理解することが、彼にとって唯一の自由でした。"},{"t":"生の事実","ic":"✦","v":"23歳で、彼は全員から縁を切られた——1656年、アムステルダムのユダヤ人共同体。若い商人バールーフ・デ・スピノザに、破門（ヘーレム）が宣告されます。文面は、宗教文書としては異様なほど激烈でした。"},{"t":"最も強い反論","ic":"⚡","v":"彼の体系は、幾何学の証明のように定義・公理・定理で組み上げられています。だからこそ最大の反論もそこに向かう。出発点の定義を認めなければ、以降の全部が崩れる。そしてその定義が正しいことは、体系の内側からは証明できない。「美しく完璧だが、入口が信仰である」という批判に、彼は答えきっていません。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分で選んだ」と思っている今日の選択に、原因はありませんでしたか。育ち、疲れ、昨日の一言、空腹。それを全部わかった上で、それでも選び直せるものはどれですか。"}],"ジョン・ロック":[{"t":"核心","ic":"◈","v":"人は生得観念を持たず、心は白紙で生まれ、あらゆる知識は経験から来ると説いた。"},{"t":"本人の言葉","ic":"❝","v":"立法者が人民の財産を奪い破壊しようと企てるとき、彼らは人民との戦争状態に身を置くのである。","by":"『統治二論』1689年"},{"t":"転回","ic":"⟲","v":"この一文は、八十七年後のアメリカ独立宣言にほぼそのまま流れ込みます。生命・自由・幸福の追求という有名な三点は、ロックの三点の言い換えです。彼の思想は、書物の中ではなく、国家の設計図として使われました。"},{"t":"生の事実","ic":"✦","v":"彼は亡命者だった——ロックは医師であり、政治家シャフツベリ伯の側近でした。国王暗殺の陰謀に連座した疑いをかけられ、1683年にオランダへ亡命します。"},{"t":"最も強い反論","ic":"⚡","v":"そのロックが、王立アフリカ会社に投資していました。この会社は奴隷貿易を行っており、彼はカロライナ植民地の基本憲法の起草にも関与しています。そこには、自由民は奴隷に対して絶対的な権力を持つ、という条文が含まれていました。すべての人間は生まれながらに自由で平等だと書いた男が、です。彼の理論を彼自身に適用すれば、その事業は根本的な矛盾です。この不整合は、近代の自由主義そのものが抱えた不整合でもありまし…"},{"t":"あなたへ","ic":"→","v":"あなたが「生まれつきの性格だから」と諦めていることを一つ。それは、どんな経験があなたに書き込んだものですか。"}],"デイヴィッド・ヒューム":[{"t":"核心","ic":"◈","v":"経験論を徹底し、私たちが「因果」と呼ぶものは、繰り返し起こる出来事を結びつける心の習慣にすぎず、必然的な結びつきそのものは観察できないと喝破した。"},{"t":"本人の言葉","ic":"❝","v":"我々が原因と結果と呼ぶものの結びつきは、事物のうちにではなく、我々の心の習慣のうちにある。","by":"『人間知性研究』の趣旨"},{"t":"転回","ic":"⟲","v":"では、なぜ結ばれていると感じるのか。何度も一緒に起きたからです。それは論理ではなく、心の習慣です。だから明日も太陽が昇るという確信は、証明ではなく慣れにすぎない。彼はこれを絶望として書いてはいません。人間はそう作られている、と冷静に記述しただけです。"},{"t":"生の事実","ic":"✦","v":"死の床に、彼を試しに来た男がいた——1776年、ヒュームは腸の病で余命わずかでした。伝記作家ジェイムズ・ボズウェルが訪ねます。目的は一つ、無神論者が死を前にして信仰に戻る瞬間を見ることでした。"},{"t":"最も強い反論","ic":"⚡","v":"彼には、擁護しがたい一節があります。『国民性について』の注で、彼は非白人が生まれつき劣っているのではないかと書きました。同時代のビーティらに批判され、彼は表現を手直ししましたが、削除はしていません。2020年、エディンバラ大学は彼の名を冠した建物を改名しました。あらゆる断定に根拠を求めた男が、この点では根拠なき偏見を書いた。彼の方法は、彼自身にすら十分に適用されていなかった。"},{"t":"あなたへ","ic":"→","v":"あなたが「当然そうなるはずだ」と思っている予測を一つ。その根拠は、論理ですか。それとも、これまで何度もそうだったという慣れですか。"}],"カント":[{"t":"核心","ic":"◈","v":"認識は対象に従うのではなく、対象が私たちの認識の形式に従って現れると考えた(コペルニクス的転回)。"},{"t":"本人の言葉","ic":"❝","v":"あなたの意志の格率が、つねに同時に普遍的な立法の原理として妥当しうるように行為せよ。","by":"『実践理性批判』"},{"t":"転回","ic":"⟲","v":"難しく聞こえますが、やっていることは単純です。「自分がしようとしていることを、全員がやったとして、それでも成り立つか」。あなただけが列に割り込むのは得をする。全員が割り込めば列は消える。つまりそれは、本当は誰もやるべきでない。自分を例外にしないこと——彼の道徳はこの一点です。"},{"t":"生の事実","ic":"✦","v":"彼が散歩を欠かしたのは、生涯に数回しかない——ケーニヒスベルクの住民は、彼の姿を見て時計を合わせたと言われます。毎日、同じ時刻に、同じ道を歩いた。生涯独身。生まれた町からほとんど出ないまま80年を過ごしています。"},{"t":"最も強い反論","ic":"⚡","v":"この厳格さが、彼自身を破滅的な結論へ連れて行きます。1797年、彼は「殺人者が玄関に来て、友人がどこに隠れているか尋ねたときも、嘘をついてはならない」と書きました。嘘は例外なく禁じられる、と。当時から批判され、彼は撤回せず擁護しています。さらに深刻なのは、彼の人類学講義に含まれる人種についての記述です。彼は非ヨーロッパ人を明確に劣位に置いた。すべての人間を目的として扱えと説いた当人が、です。この…"},{"t":"あなたへ","ic":"→","v":"あなたが昨日した判断のうち、「自分だからいい」「今回だけ」で通したものはありませんか。それを全員がやったとして、世界はまだ回りますか。"}],"ヘーゲル":[{"t":"核心","ic":"◈","v":"世界と歴史を、精神(理性)が矛盾を乗り越えながら自己を実現していく壮大な運動として描いた。"},{"t":"本人の言葉","ic":"❝","v":"ミネルヴァの梟は、夕暮れが訪れてはじめて飛び立つ。","by":"『法の哲学』序文"},{"t":"転回","ic":"⟲","v":"梟は知恵の女神の使いです。つまり——理解は、いつも手遅れで訪れる。ある時代の意味が分かるのは、その時代が終わりかけてからだ、と。彼は世界を導く杖として哲学を書いたのではありません。過ぎ去るものを、過ぎ去る瞬間にようやく理解できる、という諦めに近い自覚を、体系の入口に置いた。"},{"t":"生の事実","ic":"✦","v":"街が燃える中、彼は原稿を抱えて逃げた——1806年10月、イェーナ。ナポレオン軍が町へ雪崩れ込み、略奪と放火が始まります。36歳の無名講師ヘーゲルは、書き上げたばかりの原稿を抱えて避難しました。それが『精神現象学』です。"},{"t":"最も強い反論","ic":"⚡","v":"この一文は、当時から「存在するものはすべて正しい、ゆえにプロイセン国家は正しい」という体制擁護として読まれました。ショーペンハウアーは彼を詐欺師と罵り、二十世紀にはポパーが『開かれた社会とその敵』で、全体主義の思想的先祖として名指ししています。加えて、彼の文章は誇張なく難解です。その難解さは深さなのか、それとも検証を拒む煙幕なのか。この問いは決着していません。"},{"t":"あなたへ","ic":"→","v":"あなたが今ぶつかっている対立は、どちらかを潰して終わる種類のものですか。それとも、両方が形を変えなければ抜けられない種類のものですか。"}],"ニーチェ":[{"t":"核心","ic":"◈","v":"キリスト教道徳と絶対的真理が力を失った時代(ニヒリズム)を診断し、それを乗り越える生き方を模索した。"},{"t":"本人の言葉","ic":"❝","v":"神は死んだ。神は死んだままだ。そして我々が神を殺したのだ。……この血を、我々はいかにして拭い去るのか。","by":"『悦ばしき知識』125節"},{"t":"転回","ic":"⟲","v":"これは宇宙論ではなく、秤です。今日のあなたの一日は、無限回くり返されてもいい一日でしたか。もし違うなら、なぜその日を過ごしたのですか。"},{"t":"生の事実","ic":"✦","v":"1889年1月3日、トリノの街角——44歳のニーチェは、広場で御者が馬を鞭打つのを見ました。彼は駆け寄り、馬の首を抱きしめて泣き崩れ、そのまま倒れます。"},{"t":"最も強い反論","ic":"⚡","v":"彼の死後、妹エリーザベトが未発表の草稿を編集し、反ユダヤ主義的な自分の思想に沿うよう並べ替えて出版しました。ニーチェ自身は反ユダヤ主義を軽蔑し、その理由で妹の夫と絶交しています。それでも、彼の書いた強者と弱者の言葉が、ナチスに利用されうる形をしていたことは事実です。「読まれ方は書き手の責任か」という問いは、彼の名誉が回復された今も終わっていません。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分は謙虚だ」「欲がない」と思っている部分は、本当に選び取った徳ですか。それとも、手に入らなかったものを、欲しくなかったことにしただけですか。"}],"ハイデガー":[{"t":"核心","ic":"◈","v":"西洋哲学が「存在するもの」ばかりを問い、「存在するとはどういうことか」という根本の問いを忘れてきたと批判した。"},{"t":"本人の言葉","ic":"❝","v":"我々は、ひとが楽しむように楽しみ、ひとが読み見るように読み見て、ひとが判断するように文学や芸術を判断する。","by":"『存在と時間』第27節"},{"t":"転回","ic":"⟲","v":"この「ひと」は特定の誰でもありません。責任を引き受ける人が一人もいない状態です。誰の意見でもない意見に従い、誰も選んでいない生き方を生きる。彼はそれを頽落と呼びました。非難ではなく、放っておけばそうなる、という診断です。"},{"t":"生の事実","ic":"✦","v":"先に、これを書きます——1933年5月、彼はナチ党に入党し、フライブルク大学総長に就任しました。就任演説で大学をナチスの理念に沿わせることを説き、政策を実行しています。"},{"t":"最も強い反論","ic":"⚡","v":"そして、ここに巨大な穴が開きます。「ひとに流されず、自分の生を引き受けよ」と説いた本人が、1933年に群衆の側へ加わりました。本来性の哲学は、何に対して本来的であるべきかを何も指定しません。だから彼は、それをナチスの運動に賭けることができた。哲学が中身を持たなかったから防げなかったのか、それとも彼の人格の問題なのか。彼を読む者は全員、この問いを自分で引き受けるしかありません。"},{"t":"あなたへ","ic":"→","v":"あなたが今日した選択のうち、「みんながそうしているから」で決めたものはいくつありますか。その一つを、今日の終わりまでに自分の名前で選び直せますか。"}],"サルトル":[{"t":"核心","ic":"◈","v":"人間には初めから決められた本質はなく、まず存在し、自らの選択によって自分が何者かを作っていくと説いた。"},{"t":"本人の言葉","ic":"❝","v":"実存は本質に先立つ。","by":"『実存主義とは何か』1946年"},{"t":"転回","ic":"⟲","v":"刑、です。逃げ場がない。選ばないという選択も選択であり、環境のせいにすることも、そう解釈すると決めた選択になる。あなたは自分の存在の全責任を、負わされている。"},{"t":"生の事実","ic":"✦","v":"彼はノーベル賞を断った——1964年、文学賞の受賞が決まると、彼は辞退します。理由は謙遜ではありません。"},{"t":"最も強い反論","ic":"⚡","v":"彼の最大の傷は、政治です。彼は長くソ連を擁護し、収容所の実態が伝わった後も批判を控えました。労働者を落胆させてはならない、という理由です。徹底した誠実さと自己欺瞞の告発を武器にした哲学者が、政治的な必要のために事実を伏せた。後年は毛沢東主義にも接近しています。カミュはこれを理由に彼と決裂しました。彼の哲学が彼自身に適用されたとき、彼は落第しています。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分はこういう立場だから仕方ない」と言うとき、本当に選択肢はありませんか。それとも、選ばなくて済むほうを選んでいますか。"}],"ウィトゲンシュタイン":[{"t":"核心","ic":"◈","v":"哲学の問題の多くは言語の誤用から生まれると考えた。"},{"t":"本人の言葉","ic":"❝","v":"語りえぬものについては、沈黙しなければならない。","by":"『論理哲学論考』7"},{"t":"転回","ic":"⟲","v":"だから彼は言います。哲学の問題の多くは、発見されるべき謎ではない。言葉が本来の使われ方から離れて空回りしているときに生じる、混乱である。哲学の仕事は解決ではなく、解消だと。"},{"t":"生の事実","ic":"✦","v":"彼はヨーロッパ有数の資産を、全部手放した——ウィーンの大富豪の家に生まれ、父の死で莫大な遺産を相続します。彼はそれを全額、兄姉に譲渡しました。"},{"t":"最も強い反論","ic":"⚡","v":"この立場には強い反論があります。それでは哲学は言葉の整理係に格下げされ、「善とは何か」「正義とは何か」という問いそのものを封じてしまうのではないか。実際に彼の影響下で、二十世紀の英語圏哲学はしばらく人生の問題を扱わなくなりました。彼自身は倫理を最も重んじていたのに、です。"},{"t":"あなたへ","ic":"→","v":"あなたが何年も抱えている悩みを、一度だけ疑ってみてください。それは本当に答えの要る問題ですか。それとも「幸せ」「本当の自分」といった大きな言葉が、行き場をなくして空回りしているだけですか。"}],"孔子":[{"t":"核心","ic":"◈","v":"乱れた世を立て直す鍵を、人と人との思いやり「仁」に見た。"},{"t":"本人の言葉","ic":"❝","v":"君子はもとより窮する。小人は窮すれば、そこで乱れる。","by":"『論語』衛霊公篇"},{"t":"転回","ic":"⟲","v":"だから彼の哲学は、瞑想でも論理でもなく、日常の関係の中にあります。親にどう接するか。友との約束をどうするか。目下の者にどう振る舞うか。壮大な原理ではなく、目の前の一人への態度の積み重ねで人は人になる、と。"},{"t":"生の事実","ic":"✦","v":"彼は「宿なし犬のようだ」と言われ、笑って認めた——孔子は生前、成功していません。五十五歳から六十八歳まで十四年間、自分の考えを採用してくれる君主を求めて諸国を歩き回り、どこにも用いられませんでした。"},{"t":"最も強い反論","ic":"⚡","v":"彼の思想は、その後二千年にわたり帝国官僚制の正統教義になりました。君臣・父子・夫婦の上下関係を絶対化し、女性と若年者を従属させる装置として働いた。1919年の五四運動は、それを人を食う礼教と呼んで攻撃しています。これは後世による歪曲なのか、それとも彼の思想に元々含まれていた帰結なのか。彼自身、女性について差別的と読める言葉を残しており、解釈は今も割れています。"},{"t":"あなたへ","ic":"→","v":"あなたが今日会う人に対して、自分がされたら嫌なことを、一つでもしていませんか。それは何ですか。"}],"老子":[{"t":"核心","ic":"◈","v":"万物を生み出す根源を、言葉では捉えきれない「道(タオ)」と呼んだ。"},{"t":"本人の言葉","ic":"❝","v":"道の道とすべきは、常の道に非ず。","by":"『老子』第一章"},{"t":"転回","ic":"⟲","v":"言葉にできる道は、本当の道ではない。——つまりこの本は、冒頭で自らを無効にしています。これから五千字読むが、それは本物ではない、と最初に断っている。言葉が指せる範囲の外に大事なものがある、という警告を、彼は本文の前に置きました。"},{"t":"生の事実","ic":"✦","v":"書きたくなかった男が、書かされた——老子が実在したのかどうか、確かなことは分かっていません。伝えられる話はこうです。"},{"t":"最も強い反論","ic":"⚡","v":"彼の政治論の章には、民の心を虚しくし、腹を満たし、志を弱くせよ、という記述があります。これは為政者に向けた統治術として読めば、民衆を考えさせず従順に保つ技術になる。事実、法家の韓非子は老子を直接引き継いでいます。柔らかい神秘思想の内側に、冷たい支配の技術が同居している——この読みを、老子の側から完全に退けることはできていません。"},{"t":"あなたへ","ic":"→","v":"あなたが今、力を入れて押している物事があるとして。手を離したら、本当に崩れますか。それとも、あなたが押しているから動かないのですか。"}],"荘子":[{"t":"核心","ic":"◈","v":"老子の道の思想を、自由で奔放な寓話によって深めた。"},{"t":"本人の言葉","ic":"❝","v":"人は皆、有用の用を知るも、無用の用を知る莫し。","by":"『荘子』人間世篇"},{"t":"転回","ic":"⟲","v":"荘子はここで反転させます。だからこそ、その木は誰にも切られず、これほど大きく、これほど長く生きられたのだ、と。役に立つものは伐られる。有用性という物差しは、測られる側にとっては刃物でもある。この視点は、能力で値踏みされ続ける社会にいる人間には、かなり効きます。"},{"t":"生の事実","ic":"✦","v":"妻が死んだ日、彼は盆を叩いて歌っていた——友人の恵子が弔問に訪れ、その姿を見て激怒します。長年連れ添った妻が死んだのに、泣きもせず歌うとは何事か、と。"},{"t":"最も強い反論","ic":"⚡","v":"ここに、彼の最大の弱点があります。すべての区別が視点次第だとすれば、残酷と親切の区別もまた視点次第なのか。彼の生きた戦国時代は、大量殺戮の時代でした。その中で泥の中の亀を選ぶことは、賢明な自己保存であると同時に、苦しむ人々を見捨てる選択でもあります。荘子の相対主義は、暴力に対して何を言えるのか。彼はほとんど答えていません。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分は役に立っていない」と感じるとき、その物差しを持ってきたのは誰ですか。その物差しの外側で、あなたはどんな木ですか。"}],"ブッダ(釈迦)":[{"t":"核心","ic":"◈","v":"人生は思い通りにならない苦であり、その原因は尽きない渇愛(執着)にあると見抜いた。"},{"t":"本人の言葉","ic":"❝","v":"つくられたものは、すべて滅びゆく。怠らず努めよ。","by":"最期の言葉と伝えられる"},{"t":"転回","ic":"⟲","v":"中道という言葉は、穏やかな折衷案のように聞こえます。違います。快楽の道でも苦行の道でも駄目だという結論は、彼が両方を極限までやって、両方とも失敗したところから出てきました。理論ではなく、二度の挫折の記録です。"},{"t":"生の事実","ic":"✦","v":"彼は、生まれたばかりの息子に「束縛」と名づけた——シッダールタは王子でした。父は彼を王にしたくて、老いも病も死も見せないように宮殿の中で育てたと伝えられます。"},{"t":"最も強い反論","ic":"⚡","v":"二つの難問があります。第一に、固定した自己が無いのなら、輪廻して生まれ変わるのは何なのか。この矛盾は二千五百年、仏教内部で論争され続けています。第二に、これは現代の問いですが——妻ヤショーダラーと生後間もない息子の側から見れば、あれは家族の遺棄です。伝統は出家として称えますが、置き去りにされた側の視点は、経典にほとんど残っていません。"},{"t":"あなたへ","ic":"→","v":"あなたがいま握りしめているものを一つ思い浮かべてください。それが手に入らなかったとして、十年後のあなたは、本当に不幸になっていますか。"}],"龍樹(ナーガールジュナ)":[{"t":"核心","ic":"◈","v":"あらゆる物事は他との関係(縁起)によって成り立ち、それ自体で独立した実体を持たない——これを「空」として論理的に徹底した。"},{"t":"本人の言葉","ic":"❝","v":"縁起なるものを、我々は空と説く。","by":""},{"t":"何を言ったか","ic":"⟲","v":"あらゆる物事は他との関係(縁起)によって成り立ち、それ自体で独立した実体を持たない——これを「空」として論理的に徹底した。有と無、生と滅といった極端な見方をことごとく論破し、対立を離れた中道を示した。"},{"t":"築いた体系","ic":"✦","v":"『中論』で空の思想を精緻な論理で基礎づけ、大乗仏教の中観派を確立。世俗の真理と勝義の真理という二諦説を立て、以後の東アジア仏教全体の理論的支柱となった「第二の仏陀」。"},{"t":"キーワード","ic":"⚑","v":"空　あらゆる存在は独立した実体を欠くという、縁起を徹底した中観の中心思想。\n縁起　すべては相互の関係と条件によって成立するという仏教の根本原理。\n中道　有と無、常と断などの極端な見方を離れた立場。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（継承・論理化）\nブッダの縁起の教えを受け継ぎ、それを徹底して『空』の思想へと論理的に展開し、大乗仏教の理論的支柱を築いた。"}],"西田幾多郎":[{"t":"核心","ic":"◈","v":"主観と客観に分かれる前の、経験そのもの(純粋経験)を実在の根本に据えた。"},{"t":"本人の言葉","ic":"❝","v":"経験するというのは事実其儘に知るの意である。全く自己の細工を棄てて、事実に従うて知るのである。","by":"『善の研究』1911年"},{"t":"転回","ic":"⟲","v":"西洋哲学は長く、主観と客観の分離を出発点にしてきました。まず私がいて、次に世界があり、どうやって私は世界を正しく知れるのか、と。西田は順序を疑います。分離のほうが後から来る加工品であって、分かれる前の経験こそが本来だ、と。彼はそれを純粋経験と呼びました。"},{"t":"生の事実","ic":"✦","v":"彼は、子どもを次々に失いながら書いた——長男の謙は、二十二歳で腹膜炎により死去。娘たちも幼くして亡くし、妻の寿美は脳出血で倒れて半身不随となり、その後世を去りました。"},{"t":"最も強い反論","ic":"⚡","v":"京都学派の戦争責任は、避けて通れません。彼の弟子たち、とりわけ田辺元や高山岩男らは、大東亜共栄圏を新たな世界史的原理の実現として正当化する論を書きました。西田自身の評価は今も割れています。彼は軍部を私的には批判し、憲兵の監視下にありましたが、政府の依頼で文章を書いてもいる。問題は本人の意図だけではありません。世界史における日本の使命といった彼の概念そのものが、国家に利用可能な形をしていた——ハイ…"},{"t":"あなたへ","ic":"→","v":"あなたが最後に、自分を忘れるほど何かに没入したのはいつですか。その時間を、いまの生活のどこに取り戻せますか。"}],"ヘラクレイトス":[{"t":"核心","ic":"◈","v":"世界は絶えず変化・生成する流れであり、その変化を貫く対立物の統一と、宇宙を支配する理法(ロゴス)を説いた。"},{"t":"本人の言葉","ic":"❝","v":"同じ川に足を踏み入れる者に、次々と新しい水が流れ寄せる。","by":"断片12"},{"t":"転回","ic":"⟲","v":"物騒に聞こえますが、彼が見ていたのは張力です。弓は、木がまっすぐ戻ろうとする力と弦が引く力が、逆向きに拮抗しているから弓でいられる。竪琴も同じ。対立が消えたら、それはもう弓ではなく、ただの棒です。調和とは対立の不在ではなく、対立が均衡している状態だ——彼はそう考えました。"},{"t":"生の事実","ic":"✦","v":"彼は王位を弟に譲り、山にこもった——エフェソスの名門に生まれ、世襲の祭祀王の地位を継ぐはずでした。彼はそれを弟に譲ります。"},{"t":"最も強い反論","ic":"⚡","v":"彼について、私たちは彼自身の本を一冊も持っていません。残っているのは約百三十の断片で、そのほとんどは後世の哲学者が自説を説明するために引用した切れ端です。プラトンもアリストテレスもストア派も、それぞれ都合よく彼を使いました。つまり「ヘラクレイトス」という思想家は、かなりの程度、引用者たちが作り上げた像でもある。彼の難解さが深遠さなのか、断片だけを見ている私たちの錯覚なのか、確かめる手立てがありま…"},{"t":"あなたへ","ic":"→","v":"一年前のあなたと今のあなたは、同じ人ですか。何が入れ替わって、それでも同じだと言えるのは何ですか。"}],"パルメニデス":[{"t":"核心","ic":"◈","v":"感覚がとらえる変化や多は錯覚であり、真に「あるもの(存在)」は生成も消滅もせず、分割もされない不変・唯一の全体だと論じた。"},{"t":"本人の言葉","ic":"❝","v":"あるはある。あらぬはあらぬ。","by":"断片2の趣旨"},{"t":"転回","ic":"⟲","v":"この一撃が、西洋哲学の骨格を決めます。感覚が示すものと、理屈が導くものが食い違ったとき、どちらを信じるのか。以後の哲学者は全員、この問いに答えなければならなくなりました。原子論も、プラトンのイデアも、パルメニデスへの応答として組み立てられています。プラトンは対話篇の一つで、彼を父と呼び、批判することへの畏れを表明しました。"},{"t":"生の事実","ic":"✦","v":"彼は、あなたの目が見ているものを全部否定した——パルメニデスの主張は、哲学史上おそらく最も常識に反しています。"},{"t":"最も強い反論","ic":"⚡","v":"最も明白な反論は、彼の書き方そのものです。運動は存在しないと主張する詩が、馬車で疾走する場面から始まる。語りえないはずの「あらぬ」について、彼は何ページも語っている。この自己矛盾は古代から指摘されました。加えて、彼の議論は「ある」という語の使い方に依存しており、存在と述語をきちんと区別すれば崩れる、という現代の批判もあります。それでもなお、彼を完全に論破した人はいない、というのが正直なところです。"},{"t":"あなたへ","ic":"→","v":"あなたの感覚が「こうだ」と言い、理屈が「そんなはずはない」と言うとき、あなたはどちらを採用していますか。それはなぜですか。"}],"デモクリトス":[{"t":"核心","ic":"◈","v":"万物はそれ以上分割できない微小な粒子「原子(アトム)」と、それが運動する「空虚」から成ると説いた。"},{"t":"本人の言葉","ic":"❝","v":"実際に存在するのは、原子と空虚だけである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"万物はそれ以上分割できない微小な粒子「原子(アトム)」と、それが運動する「空虚」から成ると説いた。世界の一切は原子の結合と離散で説明でき、魂も原子から成るとする徹底した唯物論・機械論を唱えた。"},{"t":"築いた体系","ic":"✦","v":"レウキッポスとともに古代原子論を大成し、目的でなく必然と偶然による自然の説明を打ち立てた。この原子論はエピクロスに受け継がれ、近代の機械論的自然観の遠い源流となった。"},{"t":"キーワード","ic":"⚑","v":"原子(アトム)　それ以上分割できない、万物を構成する不変の微粒子。\n空虚(ケノン)　原子が運動するための、何もない空間。\n機械論　世界を目的でなく、原子の必然的な運動と衝突で説明する立場。"},{"t":"つながり","ic":"→","v":"エピクロス（影響を与える）\n原子と空虚から世界を説明する原子論は、エピクロスに受け継がれ、心の平静を目指す倫理と結びつけられた。"}],"ディオゲネス":[{"t":"核心","ic":"◈","v":"文明や社会の慣習・所有・名誉をすべて余計なものと見なし、樽に住み、最小限の物で自然に従って生きることを実践した。"},{"t":"本人の言葉","ic":"❝","v":"そこをどいてくれ。日陰になる。","by":"ディオゲネスの返答と伝えられる"},{"t":"転回","ic":"⟲","v":"帝国の全権を差し出せる男に対して、彼が求めたのは日光でした。立ち去るとき、アレクサンドロスは側近にこう言ったと伝えられます——私がアレクサンドロスでなかったら、ディオゲネスでありたい。この逸話が二千年生き延びたのは、権力の側もこの一撃の重さを認めたからです。"},{"t":"生の事実","ic":"✦","v":"彼は「通貨を偽造した」罪で、故郷を追われた——シノペの造幣関係者だった彼は、貨幣を汚したか改鋳したかの罪で追放されます。"},{"t":"最も強い反論","ic":"⚡","v":"彼をめぐる最大の疑問は、これが哲学なのか、それとも演技なのか、という点です。彼は一行も書いていません。私たちが知る彼は、数百年かけて集積された逸話の集合体で、その多くは創作の可能性があります。加えて、彼の自由には寄生の構造があります。彼が軽蔑した市民たちの施しで、彼は生きていました。都市が生む余剰がなければ、彼の樽の生活も成立しません。慣習を全否定しながら、慣習が作った街の中でしか生きられなかっ…"},{"t":"あなたへ","ic":"→","v":"あなたが手放せない持ち物を一つ思い浮かべてください。それは、あなたの生活に必要ですか。それとも、あなたの立場に必要ですか。"}],"プロティノス":[{"t":"核心","ic":"◈","v":"すべての根源に、あらゆる規定を超えた「一者(ト・ヘン)」を置き、そこから知性(ヌース)・魂(プシュケー)・自然界へと段階的にあふれ出る(流出する)と説いた。"},{"t":"本人の言葉","ic":"❝","v":"われらの魂の内なる神を、万物の内なる神へと導き還すこと。","by":"最期の言葉と伝えられる"},{"t":"転回","ic":"⟲","v":"重要なのは、これが「創造」ではないことです。一者は意図して世界を作ったのではありません。完全であるがゆえに、自然に溢れる。だから世界は罰でも失敗でもなく、下位ではあるが必然の帰結です。悪とは何かというと、彼の答えは、実体ではなく、善から遠ざかった度合い——光が届かない距離のことです。"},{"t":"生の事実","ic":"✦","v":"彼は、自分に身体があることを恥じていた——弟子ポルフュリオスが書いた伝記は、こう始まります。プロティノスは、身体を持っているということを恥じているように見えた、と。"},{"t":"最も強い反論","ic":"⚡","v":"最大の批判は、検証の不可能性です。一者は言葉でも思考でも捉えられないと彼は言う。ならば、それが存在すると彼が知っているのはなぜか。答えは、合一の体験だ、となります。だがそれは、体験していない者には何の根拠にもなりません。加えて、身体と物質を下位に置く構図は、後の西洋思想に、肉体と現世を軽んじる長い伝統を残しました。地上の生を、どこか別の場所へ向かう待合室にしてしまう危険があります。"},{"t":"あなたへ","ic":"→","v":"あなたが「本当に大事なのはこれではない」と感じる瞬間があるとして。では、本当に大事なものを、あなたはどこに置いていますか。"}],"オッカム":[{"t":"核心","ic":"◈","v":"説明は必要以上に多くの前提を立てるべきでないという「オッカムの剃刀」で知られる。"},{"t":"本人の言葉","ic":"❝","v":"陛下は剣をもって私を守られよ。私はペンをもって陛下を守ろう。","by":"伝承"},{"t":"転回","ic":"⟲","v":"この一撃が何を壊したかというと、事物の背後にある本質の秩序です。それが無いなら、世界の構造を頭の中の推論で導き出すことはできなくなる。個物を一つずつ観察するしかない。彼は神学者でしたが、結果として近代の経験科学へ道をあけました。"},{"t":"生の事実","ic":"✦","v":"彼は教皇と戦い、皇帝のもとへ逃げた——フランシスコ会士だったオッカムは、清貧をめぐる論争で教皇ヨハネス22世と対立します。異端の嫌疑をかけられ、アヴィニョンに軟禁されました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の唯名論は、副作用として、理性と信仰の橋を焼き落としました。トマス・アクィナスは、理性で神に至る道を築いていました。オッカムの世界では、神が何をするかは理性で推し量れない。結果として神学は信仰の側へ、自然探究は経験の側へ分離していきます。中世の壮大な総合が終わったのはこの地点だ、と多くの歴史家が見ます。彼が意図した結末ではありませんでした。"},{"t":"あなたへ","ic":"→","v":"あなたが今説明しようとしている出来事について。余分な仮定を全部そぎ落としたら、最小限いくつの前提で足りますか。"}],"フランシス・ベーコン":[{"t":"核心","ic":"◈","v":"思弁でなく観察と実験から出発し、多くの事例を集めて一般法則へ至る帰納法を科学の方法として提唱した。"},{"t":"本人の言葉","ic":"❝","v":"人間の知識と力は一致する。原因を知らなければ、結果を生み出すことはできない。","by":"『ノヴム・オルガヌム』1620年"},{"t":"転回","ic":"⟲","v":"とりわけ鋭いのが最初のものです。人は、自分の説を支持する事例ばかり集め、反する事例を軽く扱う。彼は四百年前にこう書いています。この一点だけで、現代の認知バイアス研究の入口に立っていました。"},{"t":"生の事実","ic":"✦","v":"彼は雪を詰めた鶏で死んだ——1626年3月、寒い日。馬車で移動中のベーコンは、ふと思いつきます。低温は肉の腐敗を止めるのではないか。"},{"t":"最も強い反論","ic":"⚡","v":"彼の言葉には、後に問題視される側面があります。自然を拷問にかけて秘密を吐かせる、という趣旨の比喩を彼は用いました。自然を対等な相手ではなく、屈服させるべき対象として扱う姿勢です。環境思想の側からは、近代の自然支配とその帰結の出発点として彼が名指しされてきました。加えて、彼の帰納法は、観察をいくら積んでも一般法則の確実性は出ないという、後にヒュームとポパーが突く弱点を抱えています。"},{"t":"あなたへ","ic":"→","v":"あなたが正しいと思っている考えについて。それを否定する事実を、これまで何件、真剣に探しましたか。"}],"ホッブズ":[{"t":"核心","ic":"◈","v":"国家が無い自然状態では、各人が自己保存の権利を主張し合い「万人の万人に対する闘争」となると論じた。"},{"t":"本人の言葉","ic":"❝","v":"そこでは、人の生は孤独で、貧しく、不快で、動物的で、短い。","by":"『リヴァイアサン』第13章"},{"t":"転回","ic":"⟲","v":"注意すべきは、彼が王権神授説を採っていないことです。主権者の正統性は神から降ってくるのではなく、下から、人々の同意によって作られる。この発想自体は、後の民主主義理論と同じ地面にあります。彼は絶対王政を擁護しましたが、その論理は近代的でした。"},{"t":"生の事実","ic":"✦","v":"母は、恐怖と一緒に彼を産んだ——1588年、スペイン無敵艦隊がイングランドに迫っているという報せが村に届きます。恐怖のあまり、身重だった母は早産しました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の理論には、致命的な穴が指摘され続けています。主権者は契約の当事者ではないため、何をしても契約違反になりません。つまり暴政に対する抵抗権が、原理的に存在しない。安全のために自由を渡した人々は、安全でなくなっても取り戻す手段がない。ロックはまさにこの点を突いて抵抗権を組み込みました。恐怖から出発した思想は、恐怖を制度化する危険と隣り合わせです。"},{"t":"あなたへ","ic":"→","v":"あなたが守られていると感じている仕組みは、何と引き換えに得たものですか。その交換条件を、最後に確認したのはいつですか。"}],"ライプニッツ":[{"t":"核心","ic":"◈","v":"世界は、それ以上分割できない無数の精神的実体「モナド」から成ると考えた。"},{"t":"本人の言葉","ic":"❝","v":"なぜ、無ではなく何かが存在するのか。","by":"『理性にもとづく自然と恩寵の原理』1714年"},{"t":"転回","ic":"⟲","v":"では、なぜ世界は整合して見えるのか。あなたが手を伸ばすとコップが動く。彼の説明は独特です。神があらかじめ、すべてのモナドの内的な展開を完全に調律しておいた。二つの時計が、繋がっていないのに同じ時刻を指し続けるように。因果ではなく、あらかじめ合わせてある——それが予定調和です。"},{"t":"生の事実","ic":"✦","v":"葬列に参加したのは、秘書ひとりだった——1716年、ハノーファー。かつてヨーロッパ中の宮廷と文通し、微積分を発明し、計算機を作り、法律・神学・地質学・言語学に業績を残した男が死にます。"},{"t":"最も強い反論","ic":"⚡","v":"1755年、リスボン大地震。万聖節の教会に人が集まっていた朝に、地震と津波と火災で数万人が死にました。ヴォルテールは激怒し、『カンディード』でライプニッツを戯画化します。何が起きても最善だと言い張る哲学者パングロスは、以後この立場の代名詞になりました。批判の核心は単純です——現に苦しんでいる人に向かって、これが最善だと言う理屈は、慰めではなく侮辱になりうる。この批判に、最善説は今も十分に答えてい…"},{"t":"あなたへ","ic":"→","v":"あなたが今、どうしても受け入れられない出来事について。それに理由があると考えることは、あなたを助けますか、それとも苦しめますか。"}],"ルソー":[{"t":"核心","ic":"◈","v":"人間は本来善良で自由だが、文明と私有財産が不平等と堕落を生んだと批判した。"},{"t":"本人の言葉","ic":"❝","v":"人間は自由なものとして生まれた。しかもいたるところで鎖につながれている。","by":"『社会契約論』1762年"},{"t":"転回","ic":"⟲","v":"この鎖の多くは、法律や暴力ではありません。他人の目です。彼が痛烈に描いたのは、文明が進むほど人は自分の内側ではなく、他人からどう見えるかを基準に生きるようになる、という転倒でした。三百年前に、彼は承認欲求の構造を書いています。"},{"t":"生の事実","ic":"✦","v":"先に、これを書きます——ジャン=ジャック・ルソーには五人の子どもがいました。彼はその全員を、生まれてすぐ孤児院へ送っています。"},{"t":"最も強い反論","ic":"⚡","v":"ここに、近代政治思想で最も危険な一文が出てきます。彼は、一般意志に従うことを拒む者は、全体によって自由であるよう強制される、と書きました。自由になるよう強制する。この論理は、少数意見を「まだ本当の自分の意志に気づいていない」として押し潰す扉を開きます。フランス革命の恐怖政治から二十世紀の全体主義まで、この一文の系譜を辿る研究は絶えません。彼が本当にそれを意図したかは別として、書かれてしまった以上…"},{"t":"あなたへ","ic":"→","v":"あなたが最近こだわった選択のうち、他人にどう見えるかを外しても、まだ欲しいものはどれですか。"}],"アダム・スミス":[{"t":"核心","ic":"◈","v":"各人が自分の利益を追求しても、市場の「見えざる手」に導かれて、結果的に社会全体の富が増すと論じた。"},{"t":"本人の言葉","ic":"❝","v":"人間をどれほど利己的とみなすとしても、その本性のうちには明らかにいくつかの原理があり、それによって彼は他人の運命に関心を持つ。","by":"『道徳感情論』1759年 冒頭"},{"t":"転回","ic":"⟲","v":"パン屋がパンを焼くのは、あなたへの好意からではなく自分の利益のためだ。だが結果として、あなたは毎朝パンを食べられる。この洞察は、意図と結果はずれるという一般則の一例です。彼はこれを万能の法則としては述べていません。"},{"t":"生の事実","ic":"✦","v":"彼は死ぬ前に、未発表の原稿をすべて焼かせた——1790年、死の数日前、スミスは友人に頼んで十六冊分の草稿を焼却させました。中身は分かっていません。"},{"t":"最も強い反論","ic":"⚡","v":"彼は市場の擁護者として引用されますが、本人が書いた警告のほうは引用されません。彼は、商人と製造業者は自分たちの利益のために結託し、価格を吊り上げようとする、と繰り返し批判しています。同業者が集まれば、話は必ず公衆に対する共謀か、値上げの企てに終わる、とも書いた。さらに、分業が労働者の知性を鈍らせる危険を指摘し、公教育の必要を説いています。彼の名を掲げる主張の多くが、彼自身の記述と食い違う——これ…"},{"t":"あなたへ","ic":"→","v":"あなたが自分の利益のためにしている仕事は、めぐって誰の役に立っていますか。逆に、誰かの損の上に成り立っている部分はありますか。"}],"J.S.ミル":[{"t":"核心","ic":"◈","v":"ベンサムの功利主義を継ぎつつ、快楽には質の差があると主張し、精神的な高級な快楽を重視した。"},{"t":"本人の言葉","ic":"❝","v":"満足した豚であるより、不満足な人間であるほうがよい。満足した愚者であるより、不満足なソクラテスであるほうがよい。","by":"『功利主義』1863年"},{"t":"転回","ic":"⟲","v":"根拠は、両方を経験した人の判断です。詩も知り、飲み食いも知る人が、どちらを選ぶか。彼はそこに賭けました。ただしこの論法には弱点があり、彼自身の育ちが偏っていたという反論を招き続けています。"},{"t":"生の事実","ic":"✦","v":"彼は実験台として育てられた——父ジェイムズ・ミルは、息子を天才に育てる計画を立て、実行しました。三歳でギリシア語。八歳でラテン語。十二歳で論理学。同年代の子どもと遊ぶことは、悪影響として禁じられています。"},{"t":"最も強い反論","ic":"⚡","v":"彼は東インド会社に三十五年勤め、インド統治の実務文書を書き続けました。そして『自由論』の中で、危害原理は文明化された社会の成員にのみ適用され、未開の人々には専制的な統治が正当でありうる、と明記しています。自由を最も精密に擁護した書物の中に、支配の例外条項が置かれている。この一節は、彼の思想全体をどう読むかを揺さぶり続けています。"},{"t":"あなたへ","ic":"→","v":"あなたが誰かの選択を「その人のためを思って」止めようとしたとき、その人は実際に誰かを傷つけていましたか。"}],"ショーペンハウアー":[{"t":"核心","ic":"◈","v":"世界は認識される限りで「表象」だが、その根底には盲目的で満たされることのない「意志」が働いていると説いた。"},{"t":"本人の言葉","ic":"❝","v":"人生は、苦痛と退屈のあいだを揺れ動く振り子である。","by":"『意志と表象としての世界』"},{"t":"転回","ic":"⟲","v":"暗い診断ですが、救いにもなります。暗い診断ですが、救いにもなります。手に入れても満たされないのは、あなたが感謝を知らないからでも、努力が足りないからでもない。欲望とはそういう構造をしているからです。"},{"t":"生の事実","ic":"✦","v":"彼はヘーゲルと同じ時間に講義を入れ、誰も来なかった——1820年、ベルリン大学。当時ヘーゲルは絶頂にあり、大教室が学生で埋まっていました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の人格は、彼の哲学と深刻に食い違います。同情を道徳の根拠とした男が、下宿の隣人の女性と争って階段から突き落とし、裁判で敗れて二十年間、賠償金を払い続けました。彼女が死んだとき、彼は「老婆が死ぬ、重荷が去る」とラテン語で書き記しています。加えて、彼の著作には女性を劣位に置く露骨な文章があります。思想と人格は別だ、という弁護は可能ですが、彼の場合は思想の中心が同情であるだけに、傷は深い。"},{"t":"あなたへ","ic":"→","v":"あなたが最近手に入れたもので、手に入れる前に想像したほどの喜びが続かなかったものは何ですか。次に欲しいものは、それと違いますか。"}],"キルケゴール":[{"t":"核心","ic":"◈","v":"客観的・普遍的な体系(ヘーゲル)に抗し、いま・ここで決断し生きる「単独者」としての実存を問題にした。"},{"t":"本人の言葉","ic":"❝","v":"私にとって真理であるような真理を見出すこと、私がそのために生き、そして死にたいと思うような理念を見出すこと。","by":"1835年 ギレライエの日記"},{"t":"転回","ic":"⟲","v":"ここで彼の思考が動きます。倫理とは「みんなに説明できること」だ。だが人生で最も重い決断は、説明できない。誰も代われず、正しさの保証もなく、それでも自分ひとりで選ぶしかない。彼はそれを質的飛躍と呼びました。連続した階段ではなく、断絶を跳ぶこと。"},{"t":"生の事実","ic":"✦","v":"1841年、ある男が婚約指輪を送り返した——コペンハーゲン。27歳のセーレンは、愛していたレギーネ・オルセンに指輪を返します。理由を誰にも説明しませんでした。彼女は泣き崩れ、街は彼を卑劣漢と呼んだ。"},{"t":"最も強い反論","ic":"⚡","v":"ここに最大の反論があります。「私にとっての真理」を最上位に置くなら、狂信者と信仰の騎士をどうやって区別するのか。テロリストも「自分にとっての真理」に賭けている。キルケゴール自身、区別できないと認めています。誠実といえば誠実ですが、あらゆる独断がこの論法で正当化されうる。この穴は、今も塞がっていません。"},{"t":"あなたへ","ic":"→","v":"あなたが今まで下した決断のうち、誰にも説明できないまま、それでも選んだものはいくつありますか。説明できるものだけを選んで生きてきたのなら、それはあなたの人生ですか、それともみんなの人生ですか。"}],"マルクス":[{"t":"核心","ic":"◈","v":"歴史を動かす根本は観念でなく、物質的な生産のあり方(経済的土台)だと考えた。"},{"t":"本人の言葉","ic":"❝","v":"宗教は、抑圧された者のため息であり、心なき世界の心情であり、魂なき状態の魂である。","by":"『ヘーゲル法哲学批判序説』1844年"},{"t":"転回","ic":"⟲","v":"彼は宗教を馬鹿にしていません。心のない世界で、それでも人が心を求める、その求め自体は正しいと認めている。問題は宗教ではなく、宗教という慰めを必要とさせる世界のほうだ、と言っている。アヘンは当時、嘲りの語ではなく、実際に使われた鎮痛薬でした。痛みは本物だ、と彼は言っているのです。"},{"t":"生の事実","ic":"✦","v":"娘が死んだとき、彼には棺を買う金がなかった——1852年、ロンドン、ソーホーのディーン街。二部屋のアパートに家族六人。国外追放を重ねた末に流れ着いた亡命先です。"},{"t":"最も強い反論","ic":"⚡","v":"二十世紀、彼の名を掲げた国家が、数千万人の生命を奪いました。擁護者は「マルクスなら反対した」と言い、それは恐らく正しい。だが問題は残ります。彼の理論には、革命を主導する前衛が新しい支配階級になることを防ぐ仕組みが用意されていません。そして彼が数箇所で書いたプロレタリアートの独裁という語が、彼らに正当化の根拠を与えたことも事実です。「思想は、その帰結にどこまで責任を負うのか」——この問いは終わって…"},{"t":"あなたへ","ic":"→","v":"あなたが今日した仕事のうち、成果が本当にあなたのものになったのはどれですか。そして、あなたを追い立てているその数字は、誰が作ったものですか。"}],"フッサール":[{"t":"核心","ic":"◈","v":"あらゆる先入観や理論をいったん括弧に入れ(エポケー)、意識に立ち現れる経験そのものを厳密に記述しようとした。"},{"t":"本人の言葉","ic":"❝","v":"事象そのものへ。","by":"『論理学研究』1900年"},{"t":"転回","ic":"⟲","v":"彼のスローガンです。理論からでも、常識からでも、科学の知識からでもなく、意識に現れているものそのものから始めよ、と。そのために彼が編み出したのが、判断の停止です。目の前のコップについて、それが本当に実在するかという問いを、いったん括弧に入れる。実在するかどうかではなく、どのように現れているかだけを見る。"},{"t":"生の事実","ic":"✦","v":"彼は、自分の大学の図書館に入れなくなった——1933年、ナチスの法律により、ユダヤ人であるフッサールはフライブルク大学の職と権利を剥奪されます。名誉教授の称号も、図書館の利用も失いました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の企ては、生涯にわたって完成しませんでした。全ての前提を括弧に入れて厳密な出発点に立つ、という理想そのものが可能なのか。弟子たちは早々に見切りをつけます。ハイデガーは、括弧に入れられない世界の中に既に投げ込まれているのが人間だと論じ、メルロ=ポンティは完全な還元は不可能だと明言しました。最も忠実な後継者たちが、師の中心的な方法を放棄したのです。"},{"t":"あなたへ","ic":"→","v":"あなたが毎日見ているのに、実は見ていないものは何ですか。今日ひとつ、初めて見るつもりで眺めてみてください。"}],"ベルクソン":[{"t":"核心","ic":"◈","v":"時計で測る空間化された時間とは別に、意識が生きる質的で不可分な流れ「持続(デュレ)」があると説いた。"},{"t":"本人の言葉","ic":"❝","v":"持続とは、未来を蝕みながら進み、進みつつ膨れあがってゆく過去の連続的な前進である。","by":"『創造的進化』1907年"},{"t":"転回","ic":"⟲","v":"旋律を思い浮かべてください。旋律は音符の集合ではありません。前の音が後の音に浸透し、全体が一つの流れとして進む。切り取ったら旋律ではなくなる。意識も同じで、過去が現在に染み込みながら、二度と同じにならない仕方で進んでいく。"},{"t":"生の事実","ic":"✦","v":"彼は特権を断り、列に並んだ——1940年、ナチス占領下のフランス。ヴィシー政権はユダヤ人の登録を命じますが、世界的名声を持つベルクソンには免除が提示されました。"},{"t":"最も強い反論","ic":"⚡","v":"この一件は、ベルクソン個人の敗北にとどまりませんでした。科学の主張に対して哲学が語る資格を問われる象徴的な場面として記憶され、彼の名声は急速に衰えます。後に彼が相対性理論を誤解していた点も指摘されました。彼の生命の飛躍もまた、生物学の側からは、何も説明しない命名だと批判されています。現象を記述する言葉と、それを説明する理論の区別——彼はそこで足をすくわれました。"},{"t":"あなたへ","ic":"→","v":"今日あなたが過ごした時間のうち、時計で測ると短いのに、濃かった時間はどれですか。何がそれを濃くしましたか。"}],"ウィリアム・ジェイムズ":[{"t":"核心","ic":"◈","v":"観念や信念の真理は、それがもたらす具体的な効果や有用性によって決まると考えた(プラグマティズム)。"},{"t":"本人の言葉","ic":"❝","v":"私の自由意志の最初の行為は、自由意志を信じることであろう。","by":"1870年4月30日 日記"},{"t":"転回","ic":"⟲","v":"彼はこれを意識の流れと名づけました。この語は心理学を超え、ジョイスやウルフの小説技法として文学史に残ります。学者の術語が、芸術の方法になった稀な例です。"},{"t":"生の事実","ic":"✦","v":"最初の自由な行為は、自由意志を信じることにする——若いジェイムズは深刻な鬱の中にいました。医学を修めた彼は、人間が完全に物理法則に支配された機械なら、自分の意志も幻だと考え、動けなくなっていた。"},{"t":"最も強い反論","ic":"⚡","v":"この定義は、当時から激しく叩かれました。ラッセルは、それでは慰めになる嘘が真理になってしまう、と批判します。信じれば幸福になれる信念は、それだけで真になるのか。ジェイムズは、長期にわたって全体の経験と整合しなければならないと反論しましたが、真理を有用性で測る枠組みが、都合の良い信念を守る装置になりうる危険は残ります。"},{"t":"あなたへ","ic":"→","v":"あなたが結論を出せずにいる問いについて。どちらを選んでも生活が変わらないなら、それは本当に問いですか。"}],"デューイ":[{"t":"核心","ic":"◈","v":"知識は現実の問題を解決するための道具であり、思考は探究の過程だと考えた(道具主義)。"},{"t":"本人の言葉","ic":"❝","v":"教育とは、生活の準備ではない。教育は生活そのものである。","by":"デューイの教育論の趣旨"},{"t":"転回","ic":"⟲","v":"将来役立つから今我慢して覚える、という構図を彼は否定しました。子どもが今まさに生きている経験の中に、学びが含まれていなければならない。準備として過ごされる十数年は、その人にとっては人生そのものです。"},{"t":"生の事実","ic":"✦","v":"彼は、学校を実験室にした——1896年、シカゴ大学に彼が作った付属小学校は、実験学校と呼ばれました。仮説を立て、実際にやってみて、結果を見て直す——教育を科学の手続きで扱ったのです。"},{"t":"最も強い反論","ic":"⚡","v":"彼への批判は、両側から来ます。保守の側からは、内容の軽視だ、という批判。子どもの興味から出発すれば、体系的な知識が身につかず、古典も基礎も失われる、と。実際、彼の名のもとに行われた進歩主義教育の一部は、放任に陥りました。彼自身は晩年、その誤用を明確に否定しています。もう一方、左派からは、彼の漸進的な改良主義では、深い構造的不正には届かないという批判が出ました。"},{"t":"あなたへ","ic":"→","v":"あなたが最近何かを本気で学んだのは、教わったからですか。それとも、何かができなくて困ったからですか。"}],"ラッセル":[{"t":"核心","ic":"◈","v":"数学を論理学から基礎づけようとし、言語を論理的に分析することで哲学の問題を明晰にしようとした。"},{"t":"本人の言葉","ic":"❝","v":"望ましいのは、信じることではなく、証拠を求めて生きることである。","by":"講演・著作より（趣旨）"},{"t":"転回","ic":"⟲","v":"彼が繰り返し説いたのは、確信の強さと正しさは無関係だという一点です。むしろ、根拠が薄いときほど人は強く確信する。だから彼は、自分の意見にも常に確率の目盛りをつけよ、と言いました。"},{"t":"生の事実","ic":"✦","v":"彼は反戦を理由に投獄された——第一次大戦中、ラッセルは徴兵拒否者を擁護する活動を続け、大学の職を失い、1918年に禁錮六か月を科されます。"},{"t":"最も強い反論","ic":"⚡","v":"彼は率直すぎるがゆえに、生涯にわたって撤回を重ねました。第二次大戦前には対独宥和を支持し、後に撤回。戦後の一時期には、ソ連が核を持つ前に核の脅しで屈服させるべきだという趣旨の発言をし、後に強く否定しています。四度の結婚と多くの関係をめぐって、身近な人々を傷つけた記録も残っています。証拠に応じて意見を変えることは彼の思想の中核ですが、それは同時に、彼が何度も間違えたという記録でもあります。"},{"t":"あなたへ","ic":"→","v":"あなたが最も強く確信していることを一つ。その確信の強さに、根拠の量は見合っていますか。"}],"ポパー":[{"t":"核心","ic":"◈","v":"科学と非科学を分けるのは、その理論が「反証可能」かどうかだと論じた。"},{"t":"本人の言葉","ic":"❝","v":"我々は、我々の誤りから学ぶことができる。","by":"『推測と反駁』1963年"},{"t":"転回","ic":"⟲","v":"検証と反証は対称ではない。ここからポパーは科学の姿を書き換えます。科学は、真理を積み上げていく作業ではない。大胆な推測を出し、それを全力で殺そうとし、まだ殺せていないものを暫定的に使い続ける営みである、と。科学的知識は、これまでの反証攻撃を生き延びた仮説の集まりにすぎません。"},{"t":"生の事実","ic":"✦","v":"1919年のウィーンで、彼は違いに気づいた——十七歳の彼のまわりには、三つの強力な理論がありました。マルクス主義、フロイトの精神分析、そしてアインシュタインの相対性理論。"},{"t":"最も強い反論","ic":"⚡","v":"彼の反証主義には、強い反論があります。実験が失敗しても、科学者は理論を捨てず、補助的な仮定を追加して守るのが普通です。実際、そうやって守り抜いて後に正しかった理論もある。クーンは、科学は反証で進むのではなく、多くの人が枠組みを共有し、それが限界に達したときに丸ごと乗り換えるのだと論じました。ポパーの描く清潔な科学像は、実際の科学史とかなりずれています。"},{"t":"あなたへ","ic":"→","v":"あなたの信じている考えについて。どんな事実が出てきたら、それを間違いだと認めますか。答えられないなら、それは知識ですか、信念ですか。"}],"メルロ=ポンティ":[{"t":"核心","ic":"◈","v":"認識の主体を、純粋な意識でなく、世界に住み込む「身体」に見いだした。"},{"t":"本人の言葉","ic":"❝","v":"世界とは、私が思考するものではなく、私が生きるものである。","by":"『知覚の現象学』1945年"},{"t":"転回","ic":"⟲","v":"これは劣った知性ではなく、別種の知です。彼はそれを身体図式と呼びました。世界と関わる最初の理解は、頭の中の判断ではなく、身体が世界に対して構えている姿勢そのものだ、と。"},{"t":"生の事実","ic":"✦","v":"彼は机に向かったまま、53歳で急死した——1961年5月3日、心臓発作。机の上にはデカルトの『屈折光学』が開かれていました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の記述は精緻ですが、そこから何が導けるのかが見えにくい、という批判が続いてきました。身体が知っている、と言われても、それは分析なのか言い換えなのか。また彼は戦後、サルトルとともに一時ソ連を擁護する立場を取り、後に朝鮮戦争を機に決別しました。政治的判断において、彼の慎重な曖昧さは、態度の保留と区別がつきにくくなります。"},{"t":"あなたへ","ic":"→","v":"頭では正しいと分かっているのに気が進まないこと。あなたの身体は、何を先に知っているのでしょうか。"}],"アーレント":[{"t":"核心","ic":"◈","v":"人間の営みを労働・仕事・活動に分け、他者と言葉を交わし共に行為する「活動」にこそ人間の自由と複数性があると論じた。"},{"t":"本人の言葉","ic":"❝","v":"悪の凡庸さ。","by":"『エルサレムのアイヒマン』1963年"},{"t":"転回","ic":"⟲","v":"活動だけが、あなたが何者かを現します。履歴書に書ける属性ではなく、この人はこういう人だ、という誰か。それは一人では絶対に生じない。見て、聞いて、応える他人がいて初めて成立する。だから彼女にとって、公の場から人が退いた社会は、人間が消えた社会です。"},{"t":"生の事実","ic":"✦","v":"18年間、彼女はどの国の国民でもなかった——1933年、ゲシュタポに8日間拘束されます。反ユダヤ的宣伝の実態を調べていたためでした。釈放後すぐドイツを脱出。パリへ。"},{"t":"最も強い反論","ic":"⚡","v":"二つの深刻な批判があります。第一に、2011年に公開されたサッセン録音の研究により、アイヒマンは裁判で凡庸な役人を演じていたが、実際は確信的な反ユダヤ主義者だったことが示されました。彼女は騙された可能性がある。第二に、彼女は18歳のときの師であり愛人でもあったハイデガーと戦後に関係を修復し、その名誉回復に手を貸しました。ナチスの加担者に対して、彼女はなぜそれをしたのか。彼女自身は十分に説明してい…"},{"t":"あなたへ","ic":"→","v":"あなたが最近従った指示や慣行のうち、一度でも「これは正しいのか」と自分の言葉で考えたものはいくつありますか。考えなかったものは、なぜ考えなかったのですか。"}],"カミュ":[{"t":"核心","ic":"◈","v":"意味を求める人間と、それに応えない沈黙する世界との食い違いを「不条理」と呼んだ。"},{"t":"本人の言葉","ic":"❝","v":"シーシュポスが幸福であると想像しなければならない。","by":"『シーシュポスの神話』1942年"},{"t":"転回","ic":"⟲","v":"そのとき彼は、自分の運命を完全に理解しています。無駄だと知っている。それでも下りていく。カミュに言わせれば、その意識こそが神々への勝利です。運命を軽蔑しきった瞬間、罰は罰でなくなる。"},{"t":"生の事実","ic":"✦","v":"彼の家には、本が一冊もなかった——アルジェリアの貧民街。父は彼が生後一年になる前に、第一次大戦のマルヌ会戦で戦死しました。母は文字が読めず、耳も不自由で、他家の掃除をして生計を立てていた。電気のない二部屋に、祖母と兄と四人で暮らしています。"},{"t":"最も強い反論","ic":"⚡","v":"彼の生涯で最も激しく批判されたのは、アルジェリア戦争です。フランス系入植者の子である彼は、独立支持を最後まで拒みました。ストックホルムで学生に詰め寄られたとき、彼はこう答えています——正義を信じるが、正義より先に私は母を守る、と。母はアルジェの、テロの起きる街に暮らしていました。左派は彼を植民地主義者と呼び、サルトルとは決裂したままです。個人的な愛と普遍的な正義がぶつかったとき、彼は愛を選んだ。…"},{"t":"あなたへ","ic":"→","v":"あなたが今、答えの出ない状況にいるとして——その状況を理解したうえで、それでも今日やると決められることは何ですか。"}],"フーコー":[{"t":"核心","ic":"◈","v":"狂気・病・監獄・性などの歴史をたどり、「正常」と「異常」といった区分が、時代ごとの知と権力の関係の中で作られてきたことを暴いた。"},{"t":"本人の言葉","ic":"❝","v":"権力のあるところには、つねに抵抗がある。","by":"『知への意志』1976年"},{"t":"転回","ic":"⟲","v":"つまり、まず理性が狂気を病として発見したのではない。まず排除という行為があり、その後で、閉じ込めたものを説明するために病という概念が作られた。順番が逆だと彼は言います。"},{"t":"生の事実","ic":"✦","v":"彼自身が、精神科の監視下に置かれた——1948年、高等師範学校の学生だった彼は、深刻な精神的危機に陥り、自ら死を選ぼうとします。学校の医師は、その原因を彼が同性愛者であることの苦悩に帰しました。当時のフランスで、それは病とみなされていました。"},{"t":"最も強い反論","ic":"⚡","v":"最も鋭い反論はハーバーマスからのものです。あらゆる知が権力と絡み合っているなら、フーコー自身の批判はどの地面に立っているのか。彼は正しさの基準を否定しながら、暗黙のうちにそれを使って告発している——ハーバーマスはこれを、隠された規範主義と呼びました。加えて歴史家からは、大監禁の実証的な裏づけについて疑問が出されています。彼の描く歴史は、どこまで史実で、どこからが図式なのか。"},{"t":"あなたへ","ic":"→","v":"あなたが誰にも見られていない部屋で、それでもやめられない振る舞いは何ですか。それは誰の目を、あなたの内側に住まわせているのですか。"}],"デリダ":[{"t":"核心","ic":"◈","v":"西洋思想が、話し言葉／書き言葉、現前／不在のように一方を優位に置く二項対立の上に成り立ってきたと指摘し、その内部の矛盾を露わにして揺さぶる「脱構築」を行った。"},{"t":"本人の言葉","ic":"❝","v":"私はひとつの言語しか持たない。しかもそれは、私のものではない。","by":"『他者の単一言語使用』1996年"},{"t":"転回","ic":"⟲","v":"つまり、上位にあったはずの話し言葉は、下位に押しやったものの性質に最初から依存していた。純粋な起源など、どこにも無かった。これが彼の手つきです。壊すのではなく、対立の内側に入り、優劣が自分で崩れるのを見せる。"},{"t":"生の事実","ic":"✦","v":"12歳のとき、彼は理由もなく学校から追い出された——1942年10月、フランス領アルジェリア。新学期の初日、リセに登校したユダヤ人の少年は職員に呼ばれ、こう言われます。帰りなさい、と。"},{"t":"最も強い反論","ic":"⚡","v":"反対した哲学者たちの言い分は、無視できるものではありません。彼の文章は難解で、言葉遊びが多く、何を主張しているのか検証しづらい。「排除の構造」を告発する当人が、読めない文章で書いていること自体が、新しい排除ではないのか。この批判に、彼は文体を変えることでは応えませんでした。"},{"t":"あなたへ","ic":"→","v":"あなたが当たり前として受け入れている対立は何ですか。強さと弱さ、成功と失敗、正常と異常、役に立つ人と立たない人。その線を引いたのは誰で、あなたはどちら側に自分を置いていますか。"}],"ロールズ":[{"t":"核心","ic":"◈","v":"公正な社会の原理を、自分の立場や才能を知らない「無知のヴェール」の下で人々が選ぶルールとして導いた。"},{"t":"本人の言葉","ic":"❝","v":"正義は、社会制度の第一の徳である。思想の体系にとって真理がそうであるように。","by":"『正義論』1971年 冒頭"},{"t":"転回","ic":"⟲","v":"この状態で、あなたはどんな社会を選ぶか。自分が最下層に生まれる可能性がある以上、最下層が悲惨な社会は選べません。かといって全員が完全に同じ社会も選ばない。彼が導いたのは、不平等が許されるのは、それが最も恵まれない人々の利益を最大にする場合に限る、という原理でした。"},{"t":"生の事実","ic":"✦","v":"彼は、自分のせいで弟二人が死んだと信じていた——1928年、七歳のロールズはジフテリアにかかりました。感染は弟のボビーに移り、弟は死にます。翌年、彼は肺炎にかかり、それがもう一人の弟トミーに移って、トミーも死にました。"},{"t":"最も強い反論","ic":"⚡","v":"最も有名な反論は、同僚ノージックからのものです。あなたの身体も才能もあなたのものであり、他人がその果実を再分配する権利はどこから来るのか。ノージックは、正義とは分配の型ではなく、取得と移転が正当だったかという歴史の問題だと論じました。もう一方、サンデルやマッキンタイアからは、無知のヴェールの下にいる人間——共同体も歴史も愛着も剥ぎ取られた個人——は、そもそも人間ではないという批判が出ています。ロ…"},{"t":"あなたへ","ic":"→","v":"あなたが今持っているもののうち、あなた自身が選んで手に入れたものと、たまたま与えられたものを、分けてみてください。割合はどれくらいですか。"}],"孟子":[{"t":"核心","ic":"◈","v":"人は生まれつき善への芽をもつと説いた(性善説)。"},{"t":"本人の言葉","ic":"❝","v":"人に忍びざるの心あり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人は生まれつき善への芽をもつと説いた(性善説)。井戸に落ちそうな子を見れば誰もが助けようとする——この惻隠の心など四つの端緒を育てれば、仁義礼智の徳になるとした。為政者は民の幸福を第一にすべきだとした。"},{"t":"築いた体系","ic":"✦","v":"孔子の仁を継ぎ、性善説と四端説によって儒教倫理を深めた。民を重んじ暴君の交代を認める王道政治・易姓革命の思想を展開し、後世の儒学に大きな影響を残した。"},{"t":"キーワード","ic":"⚑","v":"性善説　人は生まれつき善への芽(善性)を備えているとする考え。\n四端　惻隠・羞悪・辞譲・是非の四つの心。仁義礼智の徳の芽となる。\n惻隠の心　他者の苦しみを見過ごせない、思いやりの心。仁の端緒。"},{"t":"つながり","ic":"→","v":"孔子（継承）\n孔子の仁の思想を受け継ぎ、それを性善説と四端説として理論的に深めた。"}],"荀子":[{"t":"核心","ic":"◈","v":"人は生まれつき欲望に従う悪い性をもつと説いた(性悪説)。"},{"t":"本人の言葉","ic":"❝","v":"人の性は悪、その善なるものは偽なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人は生まれつき欲望に従う悪い性をもつと説いた(性悪説)。だからこそ礼という後天的な規範と教育・修養によって性を矯め、善へ導く必要があるとした。天は道徳とは無関係な自然だとし、人為を重んじた。"},{"t":"築いた体系","ic":"✦","v":"孟子の性善説に対して性悪説を立て、礼による社会秩序と教育の役割を強調した。その現実主義的な人間観は、弟子の韓非子ら法家の思想にも影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"性悪説　人は生まれつき欲望に従う悪い性をもつとする考え。\n礼　欲望を秩序づけ、人を善へ導くための後天的な規範・制度。\n化性起偽　教育と努力によって生まれつきの性を矯め、善を作り上げること。"},{"t":"つながり","ic":"→","v":"孔子（継承）\n孔子が重んじた礼による秩序を受け継ぎ、それを性悪説の立場から基礎づけ直した。"}],"墨子":[{"t":"核心","ic":"◈","v":"身内をえこひいきする愛を退け、すべての人を分け隔てなく愛する「兼愛」を説いた。"},{"t":"本人の言葉","ic":"❝","v":"兼ねて愛し、交々利す。","by":""},{"t":"何を言ったか","ic":"⟲","v":"身内をえこひいきする愛を退け、すべての人を分け隔てなく愛する「兼愛」を説いた。人々が互いに利し合えば争いはなくなるとし、他国を攻める侵略戦争に反対した(非攻)。無駄な出費や儀礼を戒めた。"},{"t":"築いた体系","ic":"✦","v":"儒家の差別的な仁を批判し、兼愛・非攻・節用を柱とする墨家を創始。功利的で合理的な思想と、規律ある集団は、戦国時代に儒家と並ぶ有力な学派となった。"},{"t":"キーワード","ic":"⚑","v":"兼愛　身内も他人も分け隔てなく、すべての人を等しく愛すること。\n非攻　他国を侵略する不義の戦争に反対する主張。\n節用　無駄な出費や贅沢を戒め、実利にかなう倹約を重んじること。"},{"t":"つながり","ic":"→","v":"孔子（批判）\n身内をまず愛する儒家の差別的な仁を批判し、分け隔てのない兼愛を対置した。"}],"韓非子":[{"t":"核心","ic":"◈","v":"人は利によって動くという現実的な人間観から、道徳でなく明確な法と、賞罰の徹底によって国を治めるべきだと説いた。"},{"t":"本人の言葉","ic":"❝","v":"賞罰は君主が握るべき二つの柄である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人は利によって動くという現実的な人間観から、道徳でなく明確な法と、賞罰の徹底によって国を治めるべきだと説いた。君主は臣下を操る術と、揺るがぬ権勢を握らねばならないとした。"},{"t":"築いた体系","ic":"✦","v":"法・術・勢を総合し、法家思想を大成した。その現実主義的な統治理論は秦の中国統一を支え、以後の中央集権的な帝国統治の理論的支柱となった。"},{"t":"キーワード","ic":"⚑","v":"法　万人に等しく適用される、公開された明確な規範・法律。\n術　君主が臣下を見抜き操るための、表に出さない統治の技術。\n勢　君主が持つべき、揺るがぬ権威と権力の位置。"},{"t":"つながり","ic":"→","v":"荀子（師）\n人は生まれつき欲深いとする荀子の性悪説に学び、それを法による統治へと徹底した。"}],"朱熹":[{"t":"核心","ic":"◈","v":"万物には理(普遍的な原理)が宿り、それが気(素材・エネルギー)と結びついて具体的な物になると説いた。"},{"t":"本人の言葉","ic":"❝","v":"事物に至りて、その理を窮む。","by":""},{"t":"何を言ったか","ic":"⟲","v":"万物には理(普遍的な原理)が宿り、それが気(素材・エネルギー)と結びついて具体的な物になると説いた。事物を一つひとつ究めて理を窮め(格物致知)、私欲を抑えて本来の善なる性を回復すべきだとした。"},{"t":"築いた体系","ic":"✦","v":"理気二元論によって儒教を壮大な形而上学として再構築し、朱子学(宋学)を大成した。四書を重んじるその学は、東アジアの官学・科挙の基準として絶大な影響を及ぼした。"},{"t":"キーワード","ic":"⚑","v":"理　万物に宿る普遍的な原理・あるべき筋道。\n気　物を形づくる素材・エネルギー。理と結びついて事物となる。\n格物致知　事物を究めてその理を窮め、知を極めること。"},{"t":"つながり","ic":"→","v":"孔子（継承・体系化）\n孔子以来の儒教を、理と気による壮大な形而上学として再構築し、朱子学を大成した。"}],"王陽明":[{"t":"核心","ic":"◈","v":"理は外の事物でなく、自分の心のうちにあると説いた(心即理)。"},{"t":"本人の言葉","ic":"❝","v":"知は行の始め、行は知の成るなり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"理は外の事物でなく、自分の心のうちにあると説いた(心即理)。人は生まれつき善悪を知る「良知」をもち、それを曇りなく発揮すればよいとした。知ることと行うことは切り離せない一体だとした(知行合一)。"},{"t":"築いた体系","ic":"✦","v":"朱子学の外向きの探究を批判し、心を重んじる陽明学を打ち立てた。良知と実践を強調するその思想は、明代以降の中国や日本の思想・行動に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"心即理　理は外の事物でなく、自分の心のうちにあるとする考え。\n良知　人が生まれつきもつ、善悪をおのずと知る心の働き。\n致良知　その良知を曇らせず、十分に発揮しきること。"},{"t":"つながり","ic":"→","v":"朱熹（批判）\n事物を究めて理を得よと説く朱熹の外向きの学を批判し、理は自分の心のうちにあると説いた(心即理)。"}],"空海":[{"t":"核心","ic":"◈","v":"密教を体系化し、大日如来を宇宙そのものとする世界観を説いた。"},{"t":"本人の言葉","ic":"❝","v":"この身のまま、仏となる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"密教を体系化し、大日如来を宇宙そのものとする世界観を説いた。手に印を結び(身)、真言を唱え(口)、心を仏に定める(意)という三密の修行によって、この身このままで仏になれる(即身成仏)とした。"},{"t":"築いた体系","ic":"✦","v":"唐で密教を学び、真言宗を開いて日本仏教に密教を確立した。『十住心論』で諸思想を段階づける壮大な体系を示し、宗教のみならず書・詩文・社会事業でも足跡を残した。"},{"t":"キーワード","ic":"⚑","v":"即身成仏　修行によって、この身このままで仏になれるとする教え。\n三密　身(印)・口(真言)・意(観想)の三つの修行で仏と一体化すること。\n大日如来　宇宙そのものであり、万物の根源とされる密教の中心の仏。"},{"t":"つながり","ic":"→","v":"最澄（同時代（交流と対立））\n天台宗の最澄と同時代に活躍し、当初交流したが、密教の理解をめぐって後に袂を分かった。"}],"道元":[{"t":"核心","ic":"◈","v":"ただひたすら坐ること(只管打坐)そのものが悟りの現れだと説いた。"},{"t":"本人の言葉","ic":"❝","v":"仏道をならふといふは、自己をならふなり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ただひたすら坐ること(只管打坐)そのものが悟りの現れだと説いた。悟りを得るために坐るのでなく、坐る修行と悟りは一つ(修証一等)だとした。生滅する現象のただ中に仏法の真理があると見た。"},{"t":"築いた体系","ic":"✦","v":"宋で禅を学び、日本曹洞宗を開いた。『正法眼蔵』で存在と時間、修行と悟りをめぐる深い思索を日本語で展開し、日本を代表する宗教哲学を築いた。"},{"t":"キーワード","ic":"⚑","v":"只管打坐　何かのためでなく、ただひたすらに坐禅すること。\n修証一等　修行と悟りは別ではなく、坐ることがそのまま悟りだとする考え。\n身心脱落　身も心もとらわれを脱ぎ捨てた、悟りの境地。"},{"t":"つながり","ic":"→","v":"慧能（継承）\n慧能に始まる禅の教えを受け継ぎ、ひたすら坐る只管打坐として日本に伝えた。"}],"シャンカラ":[{"t":"核心","ic":"◈","v":"宇宙の根源ブラフマン(梵)と、個人の本質アートマン(我)は本来同一だと説いた。"},{"t":"本人の言葉","ic":"❝","v":"梵我一如——ブラフマンとアートマンは一つである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"宇宙の根源ブラフマン(梵)と、個人の本質アートマン(我)は本来同一だと説いた。私たちが見る多様な世界は無明による見せかけ(マーヤー)であり、この一如を悟ることで輪廻から解脱できるとした。"},{"t":"築いた体系","ic":"✦","v":"ウパニシャッドを体系化し、不二一元論(アドヴァイタ・ヴェーダーンタ)を大成した。その思想はインド哲学の主流の一つとなり、ヒンドゥー教の理論的支柱となった。"},{"t":"キーワード","ic":"⚑","v":"ブラフマン(梵)　宇宙の根源であり、唯一絶対の実在。\nアートマン(我)　個人の奥にある、変わらぬ真の自己。\n梵我一如　宇宙の根源と個の本質は本来同一であるという悟り。"},{"t":"つながり","ic":"→","v":"ラーマーヌジャ（批判され対立）\n神と魂の区別を残すラーマーヌジャは、この徹底した一元論を強く批判した。"}],"和辻哲郎":[{"t":"核心","ic":"◈","v":"人間を孤立した個人でなく、人と人との「間柄」において初めて成り立つ存在として捉えた。"},{"t":"本人の言葉","ic":"❝","v":"人間とは「間柄」において存在する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人間を孤立した個人でなく、人と人との「間柄」において初めて成り立つ存在として捉えた。倫理は個人の内面でなく、人間関係・共同体のうちにあるとした。風土が人間の生き方や文化を形づくることも論じた。"},{"t":"築いた体系","ic":"✦","v":"西洋の個人主義的倫理学を批判し、間柄を基礎とする独自の倫理学を築いた。『風土』で気候・環境と文化の関係を論じ、日本の倫理学・文化論に大きな足跡を残した。"},{"t":"キーワード","ic":"⚑","v":"間柄　人と人との関係。人間はこの間柄において初めて存在するとする考え。\n人間の学としての倫理学　倫理を個人でなく、人と人との間柄のうちに見る立場。\n風土　気候・環境が人間の生き方や文化を形づくるという考え。"},{"t":"つながり","ic":"→","v":"ハイデガー（批判的に継承）\n時間を軸とする存在論に対し、空間・風土の観点から人間を捉え直した。"}],"イブン・シーナー(アヴィセンナ)":[{"t":"核心","ic":"◈","v":"存在(あること)と本質(何であるか)を区別し、あらゆる可能な存在は、他によって存在させられる必然的存在者(神)を必要とすると論じた。"},{"t":"本人の言葉","ic":"❝","v":"存在するとは、本質に存在が加わることである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"存在(あること)と本質(何であるか)を区別し、あらゆる可能な存在は、他によって存在させられる必然的存在者(神)を必要とすると論じた。神の存在をこの必然性から証明しようとした。「空中人間」の思考実験で自己意識を論じた。"},{"t":"築いた体系","ic":"✦","v":"アリストテレス哲学と新プラトン主義をイスラームの一神教と統合し、壮大な形而上学を築いた。医学者としても『医学典範』を著し、その哲学・医学は中世ヨーロッパにも深く影響した。"},{"t":"キーワード","ic":"⚑","v":"存在と本質の区別　「あること(存在)」と「何であるか(本質)」を分ける考え。\n必然的存在者　他に依らず自らによって存在する存在者、すなわち神。\n可能的存在　存在してもしなくてもよく、他によって存在させられる被造物。"},{"t":"つながり","ic":"→","v":"アリストテレス（継承・発展）\nアリストテレス哲学を受け継ぎ、それをイスラームの一神教と統合して独自の形而上学を築いた。"}],"イブン・ルシュド(アヴェロエス)":[{"t":"核心","ic":"◈","v":"アリストテレスの著作に詳細な注釈を施し、その哲学を純化して復興した。"},{"t":"本人の言葉","ic":"❝","v":"哲学と宗教は、同じ真理への二つの道である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"アリストテレスの著作に詳細な注釈を施し、その哲学を純化して復興した。哲学(理性)と宗教(啓示)は矛盾せず、同じ真理を異なる仕方で語るとし、哲学的探究の正当性を擁護した。"},{"t":"築いた体系","ic":"✦","v":"「注釈者」と称されるほどのアリストテレス研究で知られ、その注釈はラテン世界に伝わって西欧スコラ哲学に絶大な影響を与えた。理性と信仰の関係をめぐる議論の先駆となった。"},{"t":"キーワード","ic":"⚑","v":"理性と信仰の調和　哲学と宗教は同じ真理への異なる道で、矛盾しないとする立場。\n二重真理説　哲学と神学それぞれに真理があるとされた考え(後世の解釈)。\nアリストテレス注釈　アリストテレスの著作を精緻に注解し、その哲学を復興したこと。"},{"t":"つながり","ic":"→","v":"アリストテレス（注釈・復興）\nアリストテレスの著作に詳細な注釈を施し、その哲学を純粋な形で復興した『注釈者』。"}],"マイモニデス":[{"t":"核心","ic":"◈","v":"ユダヤ教の信仰とアリストテレス哲学の調和を試みた。"},{"t":"本人の言葉","ic":"❝","v":"神については、何でないかを語ることしかできない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ユダヤ教の信仰とアリストテレス哲学の調和を試みた。聖書の擬人的な神の表現を理性的に解釈し直し、神は人間の言葉では積極的に規定できず、「〜でない」という否定によってのみ語りうるとした(否定神学)。"},{"t":"築いた体系","ic":"✦","v":"『迷える者への導き』で信仰と理性の統合を体系的に論じ、中世ユダヤ哲学を代表する思想家となった。その否定神学や神学的方法は、トマス・アクィナスら後のスコラ哲学にも影響した。"},{"t":"キーワード","ic":"⚑","v":"信仰と理性の調和　ユダヤ教の信仰とアリストテレス哲学を統合しようとする試み。\n否定神学　神は「〜でない」という否定を通してのみ語りうるとする立場。\n聖書の寓意的解釈　擬人的な神の表現を、理性に沿って比喩的に読み直すこと。"},{"t":"つながり","ic":"→","v":"アリストテレス（継承・統合）\nアリストテレス哲学を受け継ぎ、それをユダヤ教の信仰と統合しようとした。"}],"ピュタゴラス":[{"t":"核心","ic":"◈","v":"世界の根源を数と、数の比が生む調和(ハルモニア)に見た。"},{"t":"本人の言葉","ic":"❝","v":"万物は数である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"世界の根源を数と、数の比が生む調和(ハルモニア)に見た。音楽の音程が単純な数の比で表せることを発見し、宇宙全体も数的秩序に貫かれていると考えた。魂の不死と輪廻を信じ、禁欲的な教団を営んだ。"},{"t":"築いた体系","ic":"✦","v":"数学と宗教を結びつけた学派を率い、数を万物の原理とする思想を打ち立てた。その数的秩序の思想はプラトンに影響し、後の数理的自然観の遠い源流となった。"},{"t":"キーワード","ic":"⚑","v":"万物は数なり　世界のあらゆるものは数と数の関係で成り立つとする考え。\nハルモニア(調和)　数の比が生む秩序と調和。宇宙も音楽もこれに貫かれるとされた。\n魂の不死・輪廻　魂は死なず、別の身体へ生まれ変わるという信仰。"},{"t":"つながり","ic":"→","v":"プラトン（影響を与える）\n目に見える世界の背後に数学的な真の実在を見る発想は、プラトンのイデア論に影響した。"}],"パスカル":[{"t":"核心","ic":"◈","v":"人間は宇宙の中では無力な一本の葦にすぎないが、自分の悲惨さを考えることができる点で偉大だと説いた。"},{"t":"本人の言葉","ic":"❝","v":"火。アブラハムの神、イサクの神、ヤコブの神。哲学者と学者の神ならず。確信、確信、感情、喜び、平安。","by":"メモリアル 1654年"},{"t":"転回","ic":"⟲","v":"続きが重要です。彼はこう書きます。宇宙が彼を押し潰すのに、ひと吹きの蒸気、ひと滴の水で足りる。だが宇宙が彼を押し潰すとき、人間は自分を殺すものより気高い。なぜなら彼は自分が死ぬことを知っており、宇宙は何も知らないからだ、と。人間の偉大さを、勝利にではなく、負けを自覚できることに置いた。"},{"t":"生の事実","ic":"✦","v":"死後、彼の上着の裏から紙片が出てきた——1662年、パスカルが39歳で死んだ後、召使いが遺品の上着を扱っていて、裏地に何かが縫い込まれているのに気づきます。"},{"t":"最も強い反論","ic":"⚡","v":"彼の名を冠した賭けの議論——神を信じて存在すれば無限の得、存在しなくても損は小さい、ゆえに信じるほうが得だ——は、当時から批判されています。第一に、それは信仰ではなく損得計算であり、そんな打算を神が受け取るのか。第二に、この論法は、どの神についても同じように使えてしまう。彼自身は火の夜を経験しており、賭けは信じない人を入口へ誘うための道具でしたが、道具として粗いことは確かです。"},{"t":"あなたへ","ic":"→","v":"今日、あなたが何もせず一人で静かに座っていられた時間は何分ありましたか。その時間を避けるために、あなたは何をしていましたか。"}],"バークリー":[{"t":"核心","ic":"◈","v":"物質がそれ自体で存在するという考えを否定し、事物は知覚される限りで存在すると説いた(存在するとは知覚されること)。"},{"t":"本人の言葉","ic":"❝","v":"存在するとは、知覚されることである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"物質がそれ自体で存在するという考えを否定し、事物は知覚される限りで存在すると説いた(存在するとは知覚されること)。私たちが世界を秩序ある形で知覚できるのは、それを絶えず知覚し続ける神がいるからだとした。"},{"t":"築いた体系","ic":"✦","v":"ロックの経験論を徹底し、物質の実在を否定する非物質論(観念論)を打ち立てた。その主観的観念論は、経験論の一つの極として、後のヒュームやカントの議論を準備した。"},{"t":"キーワード","ic":"⚑","v":"存在するとは知覚されること　事物は知覚される限りで存在するという原理(エッセ・エスト・ペルキピ)。\n非物質論　心とは独立した物質の実在を否定する立場。\n観念論　存在するのは精神と観念だけだとする考え。"},{"t":"つながり","ic":"→","v":"ジョン・ロック（継承し徹底）\n経験論を徹底し、ロックがなお認めた物質の実在を否定して観念論へ進んだ。"}],"ベンサム":[{"t":"核心","ic":"◈","v":"善悪の基準を、快楽を増やし苦痛を減らすかどうかに置いた(功利性の原理)。"},{"t":"本人の言葉","ic":"❝","v":"最大多数の最大幸福が、正邪をはかる尺度である。","by":"初期の著作より（趣旨）"},{"t":"転回","ic":"⟲","v":"この単純さが武器でした。身分も、聖典の解釈も、関係ない。ひとりの苦しみは、ひとりぶんとして数える。彼は、誰も一人以上には数えられない、と書いています。国王の苦痛も貧民の苦痛も、同じ単位で計算する——それは当時、革命的な平等宣言でした。"},{"t":"生の事実","ic":"✦","v":"彼の遺体は、今もロンドンの大学に座っている——ベンサムは遺言で、自分の遺体を保存し、着衣のまま椅子に座らせて公開するよう指示しました。実際にそうされ、ユニヴァーシティ・カレッジ・ロンドンに今も展示されています。"},{"t":"最も強い反論","ic":"⚡","v":"功利計算には、有名な弱点があります。十人が少し得をし、一人が破滅的に傷つく選択を、総量では正当化できてしまう。奴隷制ですら、多数が十分に得をするなら計算上は成立しうる。彼の弟子であるJ.S.ミルはこの穴を塞ごうとし、さらにロールズは、功利主義は人と人の区別を真剣に受け取っていないと批判しました。総量に還元した瞬間、誰が苦しむかが見えなくなります。"},{"t":"あなたへ","ic":"→","v":"あなたが最近下した判断で、全体としては良い結果でも、一人だけ大きく損をした人はいませんでしたか。"}],"モンテスキュー":[{"t":"核心","ic":"◈","v":"権力の濫用を防ぐには、権力で権力を抑える仕組みが必要だと考えた。"},{"t":"本人の言葉","ic":"❝","v":"権力を持つ者は、それを濫用しがちである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"権力の濫用を防ぐには、権力で権力を抑える仕組みが必要だと考えた。立法・行政・司法の三権を分立させ、互いに抑制・均衡させることで自由が守られるとした。政治体制を風土や社会との関係で比較分析した。"},{"t":"築いた体系","ic":"✦","v":"『法の精神』で三権分立を提唱し、近代立憲主義と民主主義の制度設計に決定的な影響を与えた。法を社会・風土との関係で捉える比較政治の視点も切り開いた。"},{"t":"キーワード","ic":"⚑","v":"三権分立　立法・行政・司法を分け、互いに抑制・均衡させる仕組み。\n権力分立　権力の集中を防ぐため、権力を複数に分ける原理。\n抑制と均衡　各権力が互いをチェックし、暴走を防ぐ関係。"},{"t":"つながり","ic":"→","v":"ジョン・ロック（影響を受ける）\n立法と執行を分けるロックの構想を受け継ぎ、司法を加えた三権分立へと発展させた。"}],"フィヒテ":[{"t":"核心","ic":"◈","v":"カントを継ぎ、すべての出発点を能動的な「自我」に置いた。"},{"t":"本人の言葉","ic":"❝","v":"自我は自我自身を定立する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"カントを継ぎ、すべての出発点を能動的な「自我」に置いた。自我は自らを立て(定立)、自らに対して非我(世界)を立てることで自己を実現していくとした。道徳的な行為と努力にこそ自我の本質があると説いた。"},{"t":"築いた体系","ic":"✦","v":"自我を原理とする知識学を構想し、ドイツ観念論の展開を切り開いた。その能動的主体の哲学はシェリング・ヘーゲルへと受け継がれ、後の主体性の思想にも影響した。"},{"t":"キーワード","ic":"⚑","v":"自我(絶対我)　すべての出発点となる、自らを立てる能動的な主体。\n定立と反定立　自我が自らを立て、それに対し非我(世界)を立てる働き。\n知識学　自我を原理としてすべての知を基礎づけようとする体系。"},{"t":"つながり","ic":"→","v":"カント（批判的に継承）\n物自体の概念を退け、自我からすべてを基礎づけようとした。"}],"シェリング":[{"t":"核心","ic":"◈","v":"自然と精神を対立させず、両者を貫く一つの根源(絶対者)の異なる現れとして捉えた。"},{"t":"本人の言葉","ic":"❝","v":"自然は目に見える精神、精神は目に見えない自然である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"自然と精神を対立させず、両者を貫く一つの根源(絶対者)の異なる現れとして捉えた。自然もまた無意識のうちに精神へと生成していく生きた全体だとし、芸術こそ主観と客観の統一が示される場だとした。"},{"t":"築いた体系","ic":"✦","v":"自然哲学と同一哲学を展開し、フィヒテとヘーゲルをつなぐドイツ観念論の中心人物となった。自然を生きた有機的全体として捉える見方は、ロマン主義にも大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"同一哲学　自然と精神を、同一の絶対者の異なる現れとして捉える立場。\n自然哲学　自然を、無意識のうちに精神へ生成する生きた全体とみなす思想。\n絶対者　主観と客観、自然と精神の区別を超えた根源的な一者。"},{"t":"つながり","ic":"→","v":"フィヒテ（影響を受け離れた）\n自我の哲学から出発したが、自然と絶対者の重視で袂を分かった。"}],"レヴィナス":[{"t":"核心","ic":"◈","v":"西洋哲学が万物を自我の理解へ回収してきたと批判し、決して自我に還元できない「他者」との出会いを倫理の原点に置いた。"},{"t":"本人の言葉","ic":"❝","v":"顔は、私に語りかける。そしてそのことによって、私を、あらゆる関係へ招き入れる。","by":"『全体性と無限』1961年の趣旨"},{"t":"転回","ic":"⟲","v":"彼はこれを、全体性への暴力と呼びました。個人を全体の一部として扱う思考は、そのまま、個人を国家や人類や歴史の名のもとに処理する思考につながる。全体主義は、まず哲学の中で準備された、と彼は考えます。"},{"t":"生の事実","ic":"✦","v":"彼が収容所にいるあいだに、家族は殺された——リトアニア生まれのユダヤ人で、フランスに帰化していた彼は、1940年にフランス軍兵士として捕虜になります。ドイツの捕虜収容所に五年間。フランス軍の軍服を着ていたため、絶滅収容所ではなく捕虜収容所に送られ、生き延びました。"},{"t":"最も強い反論","ic":"⚡","v":"彼の思想には、深刻な緊張が指摘されています。無限の責任を説く倫理は、実行不可能なほど過酷であり、指針として使えるのかという問題。そして、より重い問題があります。1982年のレバノンの虐殺事件をめぐるラジオ討論で、パレスチナ人は隣人と呼べる他者かと問われた際、彼は、隣人とは必ずしも親族ではなく、時に敵は正義でない、という趣旨の曖昧な応答をしました。無限の他者を説いた哲学者が、具体的な政治状況で他者…"},{"t":"あなたへ","ic":"→","v":"あなたが「あの人はこういう人だ」と分類している相手について。その分類に収まらない部分を、今日ひとつ見つけられますか。"}],"ボーヴォワール":[{"t":"核心","ic":"◈","v":"「女らしさ」は生まれつきのものでなく、社会や文化によって作られると論じた。"},{"t":"本人の言葉","ic":"❝","v":"人は女に生まれるのではない、女になるのだ。","by":"『第二の性』1949年"},{"t":"転回","ic":"⟲","v":"二十世紀で最も影響力のある一文かもしれません。生物学的な事実を否定しているのではありません。彼女が言うのは、女らしさと呼ばれるものは、育てられ方、期待、禁止、褒められ方の積み重ねで後から作られる、ということです。おとなしくしなさい、可愛くしなさい、出しゃばるな。それが十数年続けば、本人がそれを自分の性質だと感じるようになる。"},{"t":"生の事実","ic":"✦","v":"彼女は、当時のフランスで最年少の哲学教授資格者だった——1929年の教授資格試験。首席はサルトル、次席がボーヴォワール。ただしサルトルはこれが二度目の受験で、彼女は一度目でした。しかも21歳、史上最年少です。"},{"t":"最も強い反論","ic":"⚡","v":"この契約には、現在では擁護しがたい部分があります。二人は教え子だった若い女性たちと関係を持ち、その一部は当時ボーヴォワールが教師の立場にありました。彼女はサルトルに女性を紹介する役回りを演じたこともあり、後年、当事者からの告発が出ています。1943年には未成年者に関わる問題で教職を一時剥奪されました。自由と対等を説いた思想と、実際の権力関係のあいだに、深刻な落差があります。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分の性格だ」と思っている振る舞いのうち、誰かに繰り返し求められて身についたものはどれですか。"}],"ドゥルーズ":[{"t":"核心","ic":"◈","v":"同一性を基準に差異を捉える伝統を逆転させ、差異そのものを根源に置く哲学を構想した。"},{"t":"本人の言葉","ic":"❝","v":"哲学とは、概念を創造する技術である。","by":"『哲学とは何か』1991年"},{"t":"転回","ic":"⟲","v":"インターネットは、彼の死後に現れた地下茎です。脱線しながら思いがけない結論に着いた雑談も、地下茎です。「正しい順番で基礎から積み上げなければ理解できない」——それは樹木の思想であり、多くの人を哲学から締め出してきた門番でした。"},{"t":"生の事実","ic":"✦","v":"その教室には、学生でない人間のほうが多かった——1970年代、パリ第8大学ヴァンセンヌ校。五月革命の後に作られた実験的な大学の、狭く煙たい部屋。"},{"t":"最も強い反論","ic":"⚡","v":"1990年代、物理学者ソーカルらが、彼とガタリを含むフランス現代思想が数学・物理の用語を意味なく借用し、権威づけに使っていると告発しました。実際、彼らの著作にはその種の使い方があります。「創造的な誤用だ」という擁護は成り立ちますが、それなら検証はどう成立するのか。この論争に、彼らの側から十分な応答はありません。"},{"t":"あなたへ","ic":"→","v":"あなたが「自分はこういう人間だ」と思っているそれは、本当にあなたの限界ですか。それとも、これまで出会った組み合わせの限界ですか。"}],"ハーバーマス":[{"t":"核心","ic":"◈","v":"理性を、孤立した個人の思考でなく、人々が対等に議論し合意を目指す「コミュニケーション」のうちに見いだした。"},{"t":"本人の言葉","ic":"❝","v":"より良い論拠がもつ、強制なき強制力。","by":"ハーバーマスの表現"},{"t":"転回","ic":"⟲","v":"強制ではないのに人を動かす、唯一の力です。彼にとって民主主義とは、多数決の手続きではなく、この条件をどれだけ現実に近づけられるかという課題でした。"},{"t":"生の事実","ic":"✦","v":"彼は口蓋裂で生まれ、話すことに苦しんだ——生まれつき口蓋が裂けており、幼少期に二度の手術を受けました。発音は明瞭にならず、人前で話すことに困難を抱え続けます。"},{"t":"最も強い反論","ic":"⚡","v":"彼の理想的な対話条件は、現実には一度も存在しないという批判が根強くあります。フーコーは、権力の外にある純粋な対話の場という想定自体が幻想だと考えました。誰が発言できるか、何が理性的とみなされるか、それ自体がすでに権力の産物である、と。またフェミニズムの側からは、彼の言う理性的な議論の作法が、特定の階層と性別の話法を標準にしていると指摘されています。"},{"t":"あなたへ","ic":"→","v":"最後に誰かと意見が対立したとき、あなたを納得させたのは相手の理由でしたか。それとも、相手の立場や勢いでしたか。"}],"タレス":[{"t":"核心","ic":"◈","v":"神話でなく自然そのものの中に世界の始まりを求めた最初の哲学者とされる。"},{"t":"本人の言葉","ic":"❝","v":"万物の根源は水である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"神話でなく自然そのものの中に世界の始まりを求めた最初の哲学者とされる。万物の根源(アルケー)を水に求め、あらゆるものは水から生じ水へ還ると考えた。天文・幾何の知識でも知られる。"},{"t":"築いた体系","ic":"✦","v":"自然を合理的に説明しようとする姿勢で、西洋哲学と自然科学の出発点(ミレトス学派)を開いた。根源を問う「アルケー」の探究は、以後の自然哲学の基本枠組みとなった。"},{"t":"キーワード","ic":"⚑","v":"アルケー　万物の根源・始まりとなる原理。\n水　タレスが万物の根源とみなした素材。\n自然哲学　神話でなく自然の内に世界の原理を求める探究。"},{"t":"つながり","ic":"→","v":"アナクシマンドロス（師（弟子へ））\n弟子アナクシマンドロスへ受け継がれ、根源を水でなく無限定なものへと発展させた。"}],"アナクシマンドロス":[{"t":"核心","ic":"◈","v":"根源を特定の物質でなく、規定を持たない無限なもの「ト・アペイロン」に求めた。"},{"t":"本人の言葉","ic":"❝","v":"万物の根源は、限りなきもの(ト・アペイロン)である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"根源を特定の物質でなく、規定を持たない無限なもの「ト・アペイロン」に求めた。対立するものはそこから分かれ出ては、また償いのように還っていくとした。世界地図や生物の起源についても考察した。"},{"t":"築いた体系","ic":"✦","v":"タレスを継ぎ、より抽象的な原理を立てて自然哲学を深めた。無限定の根源という発想は、後の宇宙論・存在論に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"ト・アペイロン　規定を持たない、無限で不定な万物の根源。\n対立と生成　対立するものが根源から分かれ出て、また還るという世界の運動。\n宇宙論　世界の成り立ちを合理的に説明しようとする試み。"},{"t":"つながり","ic":"→","v":"タレス（師事した）\n根源を問う姿勢を継ぎつつ、「水」から「無限定なもの」へ発展させた。"}],"アナクサゴラス":[{"t":"核心","ic":"◈","v":"あらゆる物にはあらゆる成分の種子が含まれると考え、混沌としたそれらを秩序づけ運動させる原理として「知性(ヌース)」を導入した。"},{"t":"本人の言葉","ic":"❝","v":"万物は万物のうちにある。ただ知性(ヌース)がそれを秩序づける。","by":""},{"t":"何を言ったか","ic":"⟲","v":"あらゆる物にはあらゆる成分の種子が含まれると考え、混沌としたそれらを秩序づけ運動させる原理として「知性(ヌース)」を導入した。太陽を燃える石とみなすなど、合理的な自然観を示した。"},{"t":"築いた体系","ic":"✦","v":"世界の秩序の原因として初めて「知性」を立て、後のプラトンやアリストテレスの目的論的思考に影響を与えた。物質と、それを動かす精神的原理を区別した点で画期的だった。"},{"t":"キーワード","ic":"⚑","v":"ヌース(知性)　混沌を秩序づけ運動させる、宇宙を貫く精神的原理。\n万物の種子　あらゆる物にあらゆる成分が含まれているという考え。\n秩序と混沌　混沌とした始原を知性が秩序づけて世界が生じるとする見方。"},{"t":"つながり","ic":"→","v":"ソクラテス（影響（と失望））\n世界を秩序づける知性という発想はソクラテスを引きつけたが、その用い方の不徹底に彼は失望したとされる。"}],"エンペドクレス":[{"t":"核心","ic":"◈","v":"万物の根源を土・水・火・空気の四元素とし、それらが「愛」と「争い」という二つの力によって結合・分離を繰り返すことで生成と消滅が起こると説いた。"},{"t":"本人の言葉","ic":"❝","v":"愛は結び、争いは分かつ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"万物の根源を土・水・火・空気の四元素とし、それらが「愛」と「争い」という二つの力によって結合・分離を繰り返すことで生成と消滅が起こると説いた。四元素説の祖として後世に大きな影響を残した。"},{"t":"築いた体系","ic":"✦","v":"複数の根源(四元素)と、それを動かす対立する二力によって世界を説明する体系を築いた。四元素説はアリストテレスに継承され、中世まで自然観の基礎となった。"},{"t":"キーワード","ic":"⚑","v":"四元素説　万物は土・水・火・空気の四つの根源から成るとする説。\n愛と争い　四元素を結合・分離させる、対立する二つの原動力。\n生成と消滅　元素の結合と分離として説明される、事物の生じ滅する過程。"},{"t":"つながり","ic":"→","v":"パルメニデス（応答）\n生成を否定するパルメニデスに応え、不滅の元素の結合・分離として変化を説明しようとした。"}],"プロタゴラス":[{"t":"核心","ic":"◈","v":"真理は誰にとっても同じ絶対的なものではなく、各人の感じ方次第で変わる(相対主義)と説いた。"},{"t":"本人の言葉","ic":"❝","v":"人間は万物の尺度である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"真理は誰にとっても同じ絶対的なものではなく、各人の感じ方次第で変わる(相対主義)と説いた。弁論術を教える職業教師(ソフィスト)の代表格で、説得の技術と人間中心の視点を重んじた。"},{"t":"築いた体系","ic":"✦","v":"ソフィストを代表し、絶対的真理より人間の感覚・判断を基準とする相対主義を打ち出した。その懐疑的・人間中心的な姿勢は、ソクラテスやプラトンが乗り越えるべき論敵となった。"},{"t":"キーワード","ic":"⚑","v":"人間は万物の尺度　物事の真偽・善悪は各人の感じ方によって決まるという相対主義。\n相対主義　絶対の真理を認めず、真理は立場や状況で変わるとする立場。\nソフィスト　報酬を取って弁論術や処世術を教えた、古代ギリシアの職業教師。"},{"t":"つながり","ic":"→","v":"ソクラテス（論敵）\n真偽を相対化するプロタゴラスに対し、ソクラテスは普遍的な定義と真理を求めて対決した。"}],"ピュロン":[{"t":"核心","ic":"◈","v":"どんな事柄についても、それが真だと確実には知りえないとし、判断を保留する(エポケー)ことを説いた。"},{"t":"本人の言葉","ic":"❝","v":"何も断定せず、判断を保留せよ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"どんな事柄についても、それが真だと確実には知りえないとし、判断を保留する(エポケー)ことを説いた。物事を断定しないことで、かえって心の平静(アタラクシア)が得られるとした。"},{"t":"築いた体系","ic":"✦","v":"古代懐疑主義(ピュロン主義)の祖となり、独断を避け判断を停止する態度を確立した。その懐疑論はセクストス・エンペイリコスによって体系化され、近代のモンテーニュやヒュームにも影響した。"},{"t":"キーワード","ic":"⚑","v":"判断保留(エポケー)　確実に知りえない事柄について、断定を差し控えること。\n懐疑主義　確実な知の成立を疑い、独断を避ける立場。\nアタラクシア　判断を保留することで得られる、心の平静。"},{"t":"つながり","ic":"→","v":"エピクロス（目標を共有）\n到達法は違うが、動揺のない平静(アタラクシア)を幸福とする点で通じる。"}],"セネカ":[{"t":"核心","ic":"◈","v":"ストア派の教えを、実践的な生き方の知恵として説いた。"},{"t":"本人の言葉","ic":"❝","v":"生きることは、生涯かけて学ぶべき技術である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ストア派の教えを、実践的な生き方の知恵として説いた。運命に左右されない徳ある心、時間を無駄にしない生、怒りや欲望の制御などを、書簡や論文でわかりやすく論じた。"},{"t":"築いた体系","ic":"✦","v":"ローマ・ストア派を代表し、倫理を日常の実践へと落とし込んだ。その平明で実用的な人生論は、後世の道徳思想や現代のストア哲学ブームにも影響を与えている。"},{"t":"キーワード","ic":"⚑","v":"ストア派の実践　徳と理性に従い、運命に動じず生きる生き方の知恵。\n時間の使い方　限りある生の時間を浪費せず、善く生きることの重視。\n情念の制御　怒りや欲望などの感情を理性で抑えること。"},{"t":"つながり","ic":"→","v":"ゼノン(ストア派)（継承）\nゼノンに始まるストア派の教えを受け継ぎ、それを実践的な人生論として広めた。"}],"エピクテトス":[{"t":"核心","ic":"◈","v":"元奴隷の身から哲学者となり、私たちを苦しめるのは出来事そのものでなく、それについての判断だと説いた。"},{"t":"本人の言葉","ic":"❝","v":"人を乱すのは、出来事ではない。出来事についての判断である。","by":"『提要』第5章"},{"t":"転回","ic":"⟲","v":"同じ一言に、深く傷つく人と、受け流す人がいます。差は出来事ではなく、そこに与えた意味です。彼はこれを、責任転嫁の話ではなく、主導権の話として語りました。出来事の側に苦しみの原因を置くかぎり、あなたは何もできない。判断の側に置いたとき、初めて手が届く。"},{"t":"生の事実","ic":"✦","v":"彼は奴隷として生まれ、足が不自由だった——エピクテトスという名前自体、ギリシア語で「所有物」を意味します。本名は伝わっていません。"},{"t":"最も強い反論","ic":"⚡","v":"最も重い問いはこうです。奴隷にされている人に向かって、あなたの隷属は本質的にはどうでもよく、大事なのはそれをどう受け止めるかだ、と言うことは、慰めなのか、それとも支配の追認なのか。エピクテトス自身が元奴隷であることは、この問いを複雑にしますが、消しはしません。実際、この教えは後の時代に、抑圧された人々に忍耐を説くために使われてきました。内面の自由を強調するほど、外の鎖は問われなくなる——その危険…"},{"t":"あなたへ","ic":"→","v":"今日あなたを苛立たせた出来事を一つ。その出来事そのものと、あなたがそれに与えた意味を、二つに分けて書けますか。"}],"マルクス・アウレリウス":[{"t":"核心","ic":"◈","v":"ローマ皇帝でありながらストア派の哲学を実践し、自らを戒める省察を『自省録』に書き記した。"},{"t":"本人の言葉","ic":"❝","v":"朝、目覚めたら自分に言え。今日、私は出しゃばりな者、恩知らずな者、傲慢な者、裏切る者、嫉妬深い者、非社交的な者に出会うだろう。","by":"『自省録』第2巻"},{"t":"転回","ic":"⟲","v":"悲観ではなく、準備です。続きで彼は、彼らがそうであるのは善悪を知らないからだ、と書き、さらに、彼らも自分と同じ理性を分け持つ同族だから憎むことはできない、と自分に言い聞かせます。人に腹を立てないための技術として、朝のうちに予測しておく。実践的な処方箋です。"},{"t":"生の事実","ic":"✦","v":"それは、出版する気のない手帳だった——『自省録』は著作ではありません。ローマ皇帝が、誰にも見せるつもりのない私的な覚書として、しかもラテン語ではなくギリシア語で書きつけたものです。"},{"t":"最も強い反論","ic":"⚡","v":"哲人皇帝という像には、無視できない影があります。彼の治世下、リヨンなどでキリスト教徒の迫害が起きています。彼が直接命じたかは議論がありますが、止めてもいません。彼は奴隷制の上に立つ帝国の頂点にあり、その制度を疑った形跡はない。そして最大の失敗は後継者です。彼は実子コンモドゥスに帝位を継がせ、その統治は帝国を混乱に陥れました。自分を律することに生涯を費やした男が、権力を誰に渡すかという最も重い判断…"},{"t":"あなたへ","ic":"→","v":"今日あなたが必死で守ろうとしたもののうち、十年後にも意味を持っているものはどれですか。"}],"キケロ":[{"t":"核心","ic":"◈","v":"ギリシア哲学をローマに紹介・翻訳し、実践的な道徳・政治・法の思想として広めた。"},{"t":"本人の言葉","ic":"❝","v":"自然に反することほど、法にかなわぬものはない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ギリシア哲学をローマに紹介・翻訳し、実践的な道徳・政治・法の思想として広めた。人間に共通する理性に基づく普遍的な「自然法」を説き、雄弁と教養を備えた市民の理想を掲げた。"},{"t":"築いた体系","ic":"✦","v":"折衷的にストア派やアカデメイア派を取り入れ、ラテン語の哲学語彙を整えた。その自然法思想と共和政の理念は、近代の法思想・人文主義に大きな影響を残した。"},{"t":"キーワード","ic":"⚑","v":"自然法　人間に共通する理性に根ざした、普遍的で不変の法。\n雄弁術　教養と徳を備えた説得の技術。市民の理想とされた。\n共和政の理想　法と徳に基づく市民の自治を重んじる政治観。"},{"t":"つながり","ic":"→","v":"ゼノン(ストア派)（影響を受ける）\nストア派の自然法と徳の思想を受け継ぎ、ローマに紹介した。"}],"ボエティウス":[{"t":"核心","ic":"◈","v":"無実の罪で投獄され処刑を待つ中、『哲学の慰め』を著した。"},{"t":"本人の言葉","ic":"❝","v":"運命の輪は回り続ける。","by":""},{"t":"何を言ったか","ic":"⟲","v":"無実の罪で投獄され処刑を待つ中、『哲学の慰め』を著した。移ろう運命(フォルトゥナ)に一喜一憂せず、真の幸福は失われることのない最高善=神のうちにあると説き、哲学によって心の平安を求めた。"},{"t":"築いた体系","ic":"✦","v":"古代哲学と中世をつなぐ「最後のローマ人」とされ、普遍論争の火種となる問題も提起した。その著作と論理学の翻訳は、中世スコラ哲学の重要な出発点となった。"},{"t":"キーワード","ic":"⚑","v":"運命(フォルトゥナ)　絶えず回り、人の幸不幸を移り変わらせる運命の力。\n哲学の慰め　哲学的思索によって不幸の中でも心の平安を得ること。\n最高善　失われることのない真の幸福であり、神と同一とされるもの。"},{"t":"つながり","ic":"→","v":"アウグスティヌス（影響を受けた）\n古代哲学とキリスト教信仰を結ぶ姿勢を受け継いだ。"}],"アンセルムス":[{"t":"核心","ic":"◈","v":"信仰を出発点としつつ、それを理性で理解しようとした。"},{"t":"本人の言葉","ic":"❝","v":"知らんがために信ず。","by":""},{"t":"何を言ったか","ic":"⟲","v":"信仰を出発点としつつ、それを理性で理解しようとした。「それより大きいものが考えられない存在」という神の定義から、神が現に存在することを論理のみで導く存在論的証明を試みた。"},{"t":"築いた体系","ic":"✦","v":"スコラ哲学の父とされ、信仰と理性の関係を問う枠組みを築いた。彼の存在論的証明は、以後デカルト、カント、現代の分析哲学に至るまで議論され続けている。"},{"t":"キーワード","ic":"⚑","v":"存在論的証明　神の概念そのものから神の存在を論理的に導こうとする証明。\n知解を求める信仰　信仰を前提に、それを理性で理解しようとする姿勢。\n最大の存在者　「それより大きいものが考えられない」ものとしての神の定義。"},{"t":"つながり","ic":"→","v":"アウグスティヌス（継承）\n信仰を理性で理解しようとするアウグスティヌスの姿勢を受け継いだ。"}],"ドゥンス・スコトゥス":[{"t":"核心","ic":"◈","v":"存在という概念は神にも被造物にも同じ意味で当てはまる(存在の一義性)と論じ、個物を他ならぬこの個物にしている原理を「このもの性」と呼んだ。"},{"t":"本人の言葉","ic":"❝","v":"個を個たらしめるもの、それが「このもの性」である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"存在という概念は神にも被造物にも同じ意味で当てはまる(存在の一義性)と論じ、個物を他ならぬこの個物にしている原理を「このもの性」と呼んだ。意志を知性より重んじる立場でも知られる。"},{"t":"築いた体系","ic":"✦","v":"精緻な論理で知られ「精妙博士」と呼ばれた。存在の一義性や個体化の理論はスコラ哲学を深化させ、後の存在論や近代哲学にも影響を残した。"},{"t":"キーワード","ic":"⚑","v":"存在の一義性　「存在する」は神にも被造物にも同じ意味で言えるとする説。\nこのもの性　個物を他ならぬこの個物にしている、個体化の原理。\n意志の優位　知性よりも意志を上位に置く考え(主意主義)。"},{"t":"つながり","ic":"→","v":"トマス・アクィナス（批判的に継承）\n存在や普遍をめぐるトマスの議論を踏まえつつ、存在の一義性や個体化の原理で独自の立場を示した。"}],"ニコラウス・クザーヌス":[{"t":"核心","ic":"◈","v":"無限なる神は人間の有限な理性では捉えきれないと自覚すること(知ある無知)こそ、真の知に近づく道だと説いた。"},{"t":"本人の言葉","ic":"❝","v":"知ある無知。","by":""},{"t":"何を言ったか","ic":"⟲","v":"無限なる神は人間の有限な理性では捉えきれないと自覚すること(知ある無知)こそ、真の知に近づく道だと説いた。神においては対立するものが一致する(反対の一致)とし、有限と無限の関係を数学的比喩で論じた。"},{"t":"築いた体系","ic":"✦","v":"中世とルネサンスをつなぐ思想家で、神秘思想と数学的思考を結びつけた。反対の一致や無限の思索は、後のブルーノや近代の宇宙論・哲学に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"知ある無知　無限の神を捉えきれないと自覚することが真の知に近づく道だとする考え。\n反対の一致　無限なる神においては、対立するものが一致するという思想。\n無限　人間の理性を超えた、神の捉えがたい無限性。"},{"t":"つながり","ic":"→","v":"プロティノス（影響を受ける）\nあらゆる規定を超えた一者を説く新プラトン主義の伝統を受け継いだ。"}],"マキャヴェッリ":[{"t":"核心","ic":"◈","v":"政治を道徳や理想からでなく、現実の権力の力学として捉えた。"},{"t":"本人の言葉","ic":"❝","v":"戸口で泥だらけの日常着を脱ぎ、宮廷にふさわしい衣装をまとう。そして古人の宮廷へ入る。","by":"ヴェットーリ宛書簡 1513年"},{"t":"転回","ic":"⟲","v":"ここで政治は道徳から切り離されました。良い人間であることと、有能な統治者であることは、別の技術である。この切断こそが彼の発明であり、罪状でもあります。以後、彼の名は権謀術数の代名詞になりました。"},{"t":"生の事実","ic":"✦","v":"彼は拷問を受け、そのあと『君主論』を書いた——1512年、フィレンツェ共和国が倒れ、メディチ家が復権します。共和国の外交官だったマキャヴェッリは失職し、翌年、陰謀に加担した疑いで投獄されました。"},{"t":"最も強い反論","ic":"⚡","v":"擁護の余地がない箇所もあります。彼は、必要なら残酷さは一度に集中して行え、恩恵は少しずつ与えよ、と助言し、実在の人物による粛清を手際の良い手本として挙げています。これは記述ではなく、明確な助言です。現実を直視することと、現実の残酷さを技術として洗練させることのあいだに、彼は線を引きませんでした。"},{"t":"あなたへ","ic":"→","v":"あなたが避けている問題について。あるべき姿ではなく、実際に何がどう動いているかだけを紙に書き出したら、何が見えますか。"}],"トマス・モア":[{"t":"核心","ic":"◈","v":"当時のイングランド社会を批判し、私有財産のない平等な理想の島国を描いた。"},{"t":"本人の言葉","ic":"❝","v":"どこにもない場所——ユートピア。","by":""},{"t":"何を言ったか","ic":"⟲","v":"当時のイングランド社会を批判し、私有財産のない平等な理想の島国を描いた。そこでは労働と富が共有され、寛容と理性によって人々が幸福に暮らすとした。この架空の国が「ユートピア」という言葉を生んだ。"},{"t":"築いた体系","ic":"✦","v":"人文主義の立場から理想社会を構想し、社会批判と政治哲学を文学の形で示した。『ユートピア』は後の空想的社会主義や理想社会論の源流となった。"},{"t":"キーワード","ic":"⚑","v":"ユートピア　どこにもない理想郷。私有財産のない平等な社会の構想。\n人文主義　古典の教養と人間性を重んじるルネサンスの思潮。\n財産の共有　私有財産を廃し、富と労働を共有する社会の理念。"},{"t":"つながり","ic":"→","v":"エラスムス（盟友）\n親友の人文主義者エラスムスと交流し、ともにルネサンスの学問と社会批判を担った。"}],"エラスムス":[{"t":"核心","ic":"◈","v":"聖書や古典の研究に基づき、形式化した教会や社会の偽善を、機知に富んだ風刺で批判した。"},{"t":"本人の言葉","ic":"❝","v":"愚神こそが、この世を回している。","by":""},{"t":"何を言ったか","ic":"⟲","v":"聖書や古典の研究に基づき、形式化した教会や社会の偽善を、機知に富んだ風刺で批判した。理性と寛容、内面的な信仰を重んじ、暴力でなく対話と教育による人間性の陶冶を訴えた。"},{"t":"築いた体系","ic":"✦","v":"北方ルネサンスを代表する人文主義者で、原典校訂の学問を確立した。その穏健で寛容な精神と教育論は、宗教改革期のヨーロッパに広く影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"人文主義　古典と聖書の原典研究に基づき、人間性を陶冶する立場。\n風刺　『痴愚神礼讃』に見る、機知による社会と教会への批判。\n寛容　異なる立場を認め、対話によって対立を和らげる態度。"},{"t":"つながり","ic":"→","v":"トマス・モア（盟友）\n親友トマス・モアと交流し、ともにルネサンス人文主義と社会批判を担った。"}],"モンテーニュ":[{"t":"核心","ic":"◈","v":"独断を避け、自分自身を観察の対象として率直に見つめ続けた。"},{"t":"本人の言葉","ic":"❝","v":"私は何を知っているか。","by":"モンテーニュの標語"},{"t":"転回","ic":"⟲","v":"彼はこれを、天秤の意匠と一緒にメダルに刻ませました。断定ではなく、問いの形をした標語です。宗教戦争でカトリックとプロテスタントが互いを虐殺していた時代に、彼はこの態度を選びました。自分が絶対に正しいという確信こそが、人を殺させる。それを彼は目の前で見ていました。"},{"t":"生の事実","ic":"✦","v":"最愛の友が死に、彼は塔にこもった——エティエンヌ・ド・ラ・ボエシとの友情は、彼の生涯で最も深い関係でした。その友が32歳で疫病により死にます。"},{"t":"最も強い反論","ic":"⚡","v":"彼の懐疑には、政治的な代償の指摘があります。すべてを疑い、判断を保留し、習慣に従って穏やかに生きる——それは宗教戦争の狂気に対する解毒剤であると同時に、現に殺されている人々の前で立場を取らない態度にもなりえます。彼自身はボルドー市長を務め、両陣営の調停に動いてもいますが、彼の書物から積極的な抵抗の原理は出てきません。控えめさは、時に不作為と区別がつかなくなります。"},{"t":"あなたへ","ic":"→","v":"あなたが確信していることを一つ選んで、「私は何を知っているか」と問い直してみてください。何が残りますか。"}],"ジョルダーノ・ブルーノ":[{"t":"核心","ic":"◈","v":"地球中心の閉じた宇宙像を退け、宇宙は無限で、太陽のような星が無数に散らばり、それぞれに世界があると説いた。"},{"t":"本人の言葉","ic":"❝","v":"宇宙は無限であり、無数の世界がある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"地球中心の閉じた宇宙像を退け、宇宙は無限で、太陽のような星が無数に散らばり、それぞれに世界があると説いた。神は宇宙に内在するとする汎神論的な思想を唱え、異端として火刑に処された。"},{"t":"築いた体系","ic":"✦","v":"コペルニクスの説を形而上学的に拡張し、無限宇宙論と汎神論を展開した。その大胆な宇宙観は近代の宇宙論やスピノザの汎神論を先取りするものだった。"},{"t":"キーワード","ic":"⚑","v":"無限宇宙　宇宙は有限でなく無限で、中心を持たないとする考え。\n多世界　太陽に似た無数の星があり、それぞれに世界があるという説。\n汎神論　神は宇宙の外でなく、宇宙そのものに内在するとする思想。"},{"t":"つながり","ic":"→","v":"ニコラウス・クザーヌス（影響を受ける）\n無限と反対の一致を説くクザーヌスの思索に学び、無限宇宙論へと展開した。"}],"ヴィーコ":[{"t":"核心","ic":"◈","v":"人間は自分たちが作った歴史や社会・言語だからこそ真に理解できると考え、自然科学とは別の、歴史を理解する学問の道を開いた。"},{"t":"本人の言葉","ic":"❝","v":"人間は、自らが作ったものだけを真に知りうる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人間は自分たちが作った歴史や社会・言語だからこそ真に理解できると考え、自然科学とは別の、歴史を理解する学問の道を開いた。諸民族の歴史は神話から理性へと共通の段階をたどると論じた。"},{"t":"築いた体系","ic":"✦","v":"デカルト的な数学的理性偏重に抗し、歴史と文化を理解する「新しい学」を構想した。その歴史哲学は当時は注目されなかったが、後のヘルダーやヘーゲル、人文学に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"真理は作られたもの　人は自らが作ったものだけを真に知りうるという原理。\n歴史の学(新しい学)　自然科学とは別に、人間の作る歴史・社会を理解する学問。\n歴史の反復　諸民族の歴史が神話から理性へと共通の段階をたどるという見方。"},{"t":"つながり","ic":"→","v":"デカルト（批判的に対立）\n数学的・自然中心の知に反対し、歴史と人間の学の固有の意義を主張した。"}],"ヴォルテール":[{"t":"核心","ic":"◈","v":"理性と経験を重んじ、教会の独断や不寛容、迷信、専制を鋭い風刺で批判した。"},{"t":"本人の言葉","ic":"❝","v":"あなたの意見には反対だが、あなたが言う権利は命がけで守る。","by":""},{"t":"何を言ったか","ic":"⟲","v":"理性と経験を重んじ、教会の独断や不寛容、迷信、専制を鋭い風刺で批判した。信教の自由や言論の自由、寛容を訴え、あらゆる盲信に「理性の光」を当てようとした啓蒙の代表的知識人。"},{"t":"築いた体系","ic":"✦","v":"啓蒙思想を体現し、寛容と自由をめぐる無数の著作・書簡で世論を動かした。その批判精神と人権擁護は、フランス革命や近代の自由主義に大きな影響を残した。"},{"t":"キーワード","ic":"⚑","v":"啓蒙　理性の光で迷信や偏見を払い、社会を進歩させようとする思潮。\n寛容　異なる信仰や意見を認め、迫害を退ける態度。\n反教権主義　教会の独断や権力の乱用を批判する立場。"},{"t":"つながり","ic":"→","v":"ジョン・ロック（影響を受ける）\nイギリス滞在中にロックの経験論と寛容の思想に学び、それをフランスに広めた。"}],"ディドロ":[{"t":"核心","ic":"◈","v":"あらゆる学問と技術の知識を集大成する『百科全書』を主導し、知を特権者から万人へ開こうとした。"},{"t":"本人の言葉","ic":"❝","v":"知識を集め、万人に手渡すこと。","by":""},{"t":"何を言ったか","ic":"⟲","v":"あらゆる学問と技術の知識を集大成する『百科全書』を主導し、知を特権者から万人へ開こうとした。唯物論的な自然観に立ち、宗教的独断を批判して、理性と経験に基づく世界理解を広めた。"},{"t":"築いた体系","ic":"✦","v":"啓蒙の知の巨大な事業を組織し、思想の普及によって社会を変えようとした。その唯物論と百科全書的な知の理念は、近代の科学的・世俗的世界観の形成に寄与した。"},{"t":"キーワード","ic":"⚑","v":"百科全書　あらゆる知識と技術を体系的に集め、万人に開こうとした事業。\n啓蒙　理性による知の普及で社会を進歩させようとする思潮。\n唯物論　世界を物質とその運動から説明する立場。"},{"t":"つながり","ic":"→","v":"ヴォルテール（同時代）\nヴォルテールらとともにフランス啓蒙を担い、理性による社会の改善を目指した。"}],"ヘルダー":[{"t":"核心","ic":"◈","v":"普遍的な理性を掲げる啓蒙に対し、各民族には固有の言語・文化・精神(民族精神)があり、歴史はそれぞれの個性の展開だと論じた。"},{"t":"本人の言葉","ic":"❝","v":"それぞれの民族には、固有の魂がある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"普遍的な理性を掲げる啓蒙に対し、各民族には固有の言語・文化・精神(民族精神)があり、歴史はそれぞれの個性の展開だと論じた。言語こそ思考と文化の母胎だとし、多様性を重んじた。"},{"t":"築いた体系","ic":"✦","v":"歴史主義と文化多元論の先駆となり、後のロマン主義やナショナリズム、文化人類学に影響を与えた。人類の歴史を有機的な発展として捉える見方を示した。"},{"t":"キーワード","ic":"⚑","v":"民族精神(フォルクスガイスト)　各民族に固有の、言語や文化に宿る精神。\n歴史主義　物事をその時代・文化の文脈の中で理解しようとする立場。\n言語と思考　言語こそ思考と文化を形づくる母胎だとする考え。"},{"t":"つながり","ic":"→","v":"カント（師事し後に対立）\nかつての師の普遍的理性主義に、歴史と個性の観点から異を唱えた。"}],"オーギュスト・コント":[{"t":"核心","ic":"◈","v":"人間の知識は、神々で説明する神学的段階、抽象概念で説明する形而上学的段階を経て、観察された事実と法則に基づく「実証的」段階に至ると説いた。"},{"t":"本人の言葉","ic":"❝","v":"人類の知は、神学・形而上学・実証の三段階を経る。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人間の知識は、神々で説明する神学的段階、抽象概念で説明する形而上学的段階を経て、観察された事実と法則に基づく「実証的」段階に至ると説いた。社会も科学的に研究できるとした。"},{"t":"築いた体系","ic":"✦","v":"実証主義を提唱し、経験的事実に基づく科学的知の理念を確立した。社会を科学的に扱う「社会学」を創始し、その名を与えた点で社会科学の父とされる。"},{"t":"キーワード","ic":"⚑","v":"実証主義　観察された事実と法則に基づく知だけを確実とみなす立場。\n三段階の法則　知識が神学的・形而上学的・実証的段階を経て進むという説。\n社会学　社会を科学的・実証的に研究する学問。コントが創始し命名。"},{"t":"つながり","ic":"→","v":"サン=シモン（影響を受ける）\n若い頃サン=シモンの秘書を務め、社会を科学的に組織する発想を受け継いだ(のち決別)。"}],"フォイエルバッハ":[{"t":"核心","ic":"◈","v":"神とは、人間が自分自身の理想的な本質(愛・理性・力)を天に投影し、対象化したものにすぎないと論じた(宗教の人間学的解釈)。"},{"t":"本人の言葉","ic":"❝","v":"神とは、人間が自らの本質を投影したものである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"神とは、人間が自分自身の理想的な本質(愛・理性・力)を天に投影し、対象化したものにすぎないと論じた(宗教の人間学的解釈)。だから宗教の秘密は人間学であり、愛の対象は神でなく人間だとした。"},{"t":"築いた体系","ic":"✦","v":"ヘーゲルの観念論を転倒させ、感性的な人間を出発点とする唯物論・人間中心の哲学を説いた。その宗教批判はマルクスやエンゲルスに決定的な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"投影説　神は人間が自らの本質を天に投影したものだとする宗教理解。\n宗教の人間学　宗教の秘密を、実は人間自身のあり方に見いだす立場。\n感性的人間　抽象的精神でなく、感じ生きる具体的な人間を出発点とすること。"},{"t":"つながり","ic":"→","v":"ヘーゲル（批判（転倒））\n精神を根本に置くヘーゲルの観念論を転倒させ、感性的な人間を出発点とする唯物論を説いた。"}],"エドマンド・バーク":[{"t":"核心","ic":"◈","v":"理性で一気に社会を作り変えようとするフランス革命を批判し、歴史の中で培われた伝統・慣習・制度の知恵を重んじた。"},{"t":"本人の言葉","ic":"❝","v":"社会は、死者と生者と、これから生まれる者との契約である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"理性で一気に社会を作り変えようとするフランス革命を批判し、歴史の中で培われた伝統・慣習・制度の知恵を重んじた。改革は急進でなく、漸進的に積み重ねるべきだと説いた。"},{"t":"築いた体系","ic":"✦","v":"経験と伝統を尊重する近代保守主義の祖とされる。抽象的理性への懐疑と、社会を有機的に捉える見方は、その後の保守思想の基本となった。"},{"t":"キーワード","ic":"⚑","v":"保守主義　伝統と慣習の知恵を重んじ、急激な変革を戒める立場。\n伝統・慣習　歴史の中で培われ受け継がれてきた制度や知恵。\n漸進的改革　社会を一気にでなく、少しずつ改良していくべきだとする考え。"},{"t":"つながり","ic":"→","v":"ルソー（批判）\n抽象的な一般意志で社会を作り直そうとするルソー的な発想を、伝統の側から批判した。"}],"トクヴィル":[{"t":"核心","ic":"◈","v":"アメリカの民主社会を観察し、身分でなく平等が支配する社会の可能性と危うさを分析した。"},{"t":"本人の言葉","ic":"❝","v":"民主主義は、平等への抑えがたい情熱である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"アメリカの民主社会を観察し、身分でなく平等が支配する社会の可能性と危うさを分析した。平等は自由をもたらす一方、人々を孤立させ、多数の意見が個人を圧する「多数の専制」を生みうると警告した。"},{"t":"築いた体系","ic":"✦","v":"近代民主主義を歴史的必然としつつ、その光と影を冷静に見つめる政治社会学を築いた。市民の結社や自由の意義を説くその分析は、現代の民主主義論に生き続けている。"},{"t":"キーワード","ic":"⚑","v":"平等化　身分の差が消え、条件の平等が進む近代社会の趨勢。\n多数の専制　多数派の意見が少数者や個人を圧迫する民主社会の危険。\n結社　市民が自発的に結びつき、自由を支える中間集団。"},{"t":"つながり","ic":"→","v":"モンテスキュー（影響を受ける）\n自由を守る制度の仕組みを問うモンテスキューの視点を受け継いだ。"}],"サン=シモン":[{"t":"核心","ic":"◈","v":"社会は、産業に携わる者(実業家・技術者・労働者)が中心となって組織され、科学と産業によって計画的に運営されるべきだと構想した。"},{"t":"本人の言葉","ic":"❝","v":"最も貧しい階級の運命の改善を、社会の目的とせよ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"社会は、産業に携わる者(実業家・技術者・労働者)が中心となって組織され、科学と産業によって計画的に運営されるべきだと構想した。最も貧しい人々の境遇の改善を社会の目標に掲げた。"},{"t":"築いた体系","ic":"✦","v":"産業社会の到来をいち早く捉え、科学者と産業者による社会の合理的組織化を説いた。その思想は空想的社会主義やコントの実証主義、産業社会論の源流となった。"},{"t":"キーワード","ic":"⚑","v":"産業主義　社会を産業と科学に基づいて計画的に組織すべきだとする思想。\n実業者の統治　技術者・実業家・労働者が社会運営の中心になるべきだとする考え。\n空想的社会主義　理性的な計画によって理想社会を築こうとする初期社会主義。"},{"t":"つながり","ic":"→","v":"オーギュスト・コント（師として影響）\n秘書を務めた弟子コントに、産業社会と科学的社会観の着想を与えた。"}],"フレーゲ":[{"t":"核心","ic":"◈","v":"近代論理学を根本から作り替え、命題の構造を厳密に記号で表す述語論理を創始した。"},{"t":"本人の言葉","ic":"❝","v":"意義(ジン)と意味(ベドイトゥング)は区別されねばならない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"近代論理学を根本から作り替え、命題の構造を厳密に記号で表す述語論理を創始した。「明けの明星」と「宵の明星」の例で、語の指示対象(意味)とその与えられ方(意義)を区別した。"},{"t":"築いた体系","ic":"✦","v":"数学を論理から基礎づけようとし(論理主義)、現代論理学と言語哲学の出発点を築いた。意義と意味の区別や文脈原理は、分析哲学の中心的問題を切り開いた。"},{"t":"キーワード","ic":"⚑","v":"述語論理　命題の内部構造を関数と項で厳密に表す、現代論理学の体系。\n意義と意味　語の指示対象(意味)と、その与えられ方(意義)の区別。\n論理主義　数学を論理学から導き出せるとする立場。"},{"t":"つながり","ic":"→","v":"ラッセル（影響を与える）\n論理から数学を導く論理主義と現代論理学の道具立ては、ラッセルに受け継がれ発展させられた。"}],"G.E.ムーア":[{"t":"核心","ic":"◈","v":"「善い」を快楽など他の自然的性質と同一視する試みを「自然主義的誤謬」として批判し、善はそれ以上分析できない単純な性質だとした。"},{"t":"本人の言葉","ic":"❝","v":"善は、それ以上定義できない単純な性質である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"「善い」を快楽など他の自然的性質と同一視する試みを「自然主義的誤謬」として批判し、善はそれ以上分析できない単純な性質だとした。常識的な確信を出発点に、懐疑論に反論したことでも知られる。"},{"t":"築いた体系","ic":"✦","v":"ラッセルとともにイギリスの分析哲学を興し、日常言語と常識を重んじる方向を示した。倫理学における自然主義批判は、メタ倫理学の議論の起点となった。"},{"t":"キーワード","ic":"⚑","v":"自然主義的誤謬　「善い」を快楽など自然的性質に還元してしまう誤り。\n善の非分析性　善はそれ以上定義・分析できない単純な性質だとする考え。\n常識の擁護　素朴な常識的確信を出発点に懐疑論へ反論する立場。"},{"t":"つながり","ic":"→","v":"ラッセル（同時代・盟友）\nともにケンブリッジで観念論を退け、明晰な分析の哲学を切り開いた。"}],"ホワイトヘッド":[{"t":"核心","ic":"◈","v":"世界を、静止した実体でなく、生成しつつ関係し合う出来事(現実的存在)の過程として捉えた。"},{"t":"本人の言葉","ic":"❝","v":"西洋哲学は、プラトンへの一連の脚注にすぎない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"世界を、静止した実体でなく、生成しつつ関係し合う出来事(現実的存在)の過程として捉えた。あらゆるものは互いに抱握し合いながら生成するとし、宇宙を有機的な創造の過程として描いた。"},{"t":"築いた体系","ic":"✦","v":"ラッセルと数学基礎論を築いたのち、過程と関係を軸とする有機体の哲学(プロセス哲学)を展開した。その形而上学は宗教哲学や環境思想にも影響を与えている。"},{"t":"キーワード","ic":"⚑","v":"プロセス哲学　世界を実体でなく、生成する出来事の過程として捉える立場。\n現実的存在　生成し消えていく、世界を構成する基本的な出来事。\n抱握　あらゆるものが互いを取り込み関係し合う働き。"},{"t":"つながり","ic":"→","v":"ラッセル（共同研究者）\nラッセルと『プリンキピア・マテマティカ』を共著し、記号論理学の基礎を築いた。"}],"カルナップ":[{"t":"核心","ic":"◈","v":"経験によって検証できる命題だけが有意味だとし(検証原理)、形而上学の問いは無意味な疑似問題だと退けた。"},{"t":"本人の言葉","ic":"❝","v":"形而上学の命題は、真でも偽でもなく無意味である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"経験によって検証できる命題だけが有意味だとし(検証原理)、形而上学の問いは無意味な疑似問題だと退けた。科学の言語を論理的に分析し、統一的で明晰な知の体系を目指した。"},{"t":"築いた体系","ic":"✦","v":"ウィーン学団を代表し、論理実証主義を推進した。論理分析と経験主義を結びつけるその方法は、現代の科学哲学・言語哲学に大きな影響を残した。"},{"t":"キーワード","ic":"⚑","v":"論理実証主義　経験的に検証できる命題と論理・数学だけを有意味とみなす立場。\n検証原理　命題の意味は、それを検証する経験的方法によって決まるとする原理。\n形而上学の排除　検証不能な形而上学の問いを無意味として退けること。"},{"t":"つながり","ic":"→","v":"ウィトゲンシュタイン（影響を受けた）\n『論理哲学論考』の語りうるものの限界という発想を実証主義へ生かした。"}],"クワイン":[{"t":"核心","ic":"◈","v":"分析的(意味だけで真)と総合的(事実による)命題の区別を疑い、経験と切り離せる純粋な意味はないと論じた。"},{"t":"本人の言葉","ic":"❝","v":"存在するとは、変項の値であることだ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"分析的(意味だけで真)と総合的(事実による)命題の区別を疑い、経験と切り離せる純粋な意味はないと論じた。私たちの信念は個々にでなく、全体として経験に向き合う網の目(ホーリズム)をなすとした。"},{"t":"築いた体系","ic":"✦","v":"論理実証主義の前提を内側から崩し、経験主義を刷新した。翻訳の不確定性や存在論的言明の分析など、その議論は戦後アメリカの分析哲学を方向づけた。"},{"t":"キーワード","ic":"⚑","v":"分析／総合の区別批判　意味だけで真の命題と事実による命題の境界を疑う議論。\nホーリズム　信念は個別でなく、全体として経験に向き合うという考え。\n翻訳の不確定性　ある言語の文の意味を一意に翻訳し尽くせないという主張。"},{"t":"つながり","ic":"→","v":"カルナップ（批判）\n師にあたるカルナップら論理実証主義の前提(分析／総合の区別)を、内側から批判した。"}],"クーン":[{"t":"核心","ic":"◈","v":"科学は事実の直線的な積み重ねでなく、時代を支配する枠組み「パラダイム」の内での通常研究と、それが行き詰まって別の枠組みへ乗り換わる「科学革命」を繰り返すと論じた。"},{"t":"本人の言葉","ic":"❝","v":"科学は、パラダイムの転換によって革命的に進む。","by":""},{"t":"何を言ったか","ic":"⟲","v":"科学は事実の直線的な積み重ねでなく、時代を支配する枠組み「パラダイム」の内での通常研究と、それが行き詰まって別の枠組みへ乗り換わる「科学革命」を繰り返すと論じた。新旧の枠組みは通約不能だとした。"},{"t":"築いた体系","ic":"✦","v":"『科学革命の構造』で科学の歴史的・社会的な見方を提示し、科学哲学に大きな転換をもたらした。パラダイムという語は諸分野に広まり、知の枠組みを問う議論を活性化させた。"},{"t":"キーワード","ic":"⚑","v":"パラダイム　ある時代の科学を支配する、問いと方法の共有された枠組み。\n通常科学　パラダイムの内部でパズルを解くように進む日常的な研究。\n科学革命　行き詰まったパラダイムが別の枠組みへ乗り換わる転換。"},{"t":"つながり","ic":"→","v":"ポパー（論争）\n反証によって科学が進むとするポパーに対し、パラダイムの転換という歴史的・社会的な見方を対置した。"}],"ローティ":[{"t":"核心","ic":"◈","v":"心を世界の「鏡」とし、真理を実在の正確な写しとみなす伝統を批判した。"},{"t":"本人の言葉","ic":"❝","v":"真理とは、私たちが信じるのがよいとされるものだ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"心を世界の「鏡」とし、真理を実在の正確な写しとみなす伝統を批判した。真理や知識は、私たちの言葉と実践、会話の中で役立つ合意にすぎないとし、哲学を人間同士の対話の営みとして捉え直した。"},{"t":"築いた体系","ic":"✦","v":"プラグマティズムを現代に甦らせ、基礎づけ主義を退ける反表象主義を唱えた。その思想は哲学と文学・政治を横断し、ポストモダンの知的状況に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"反表象主義　知識を実在の正確な写しとみなす見方を退ける立場。\nネオ・プラグマティズム　真理や知を、実践と会話の中で役立つ合意として捉える現代の立場。\n自然の鏡の批判　心を世界を映す鏡とする認識論の伝統への批判。"},{"t":"つながり","ic":"→","v":"デューイ（継承）\nデューイらのプラグマティズムを受け継ぎ、それを反表象主義として現代に甦らせた。"}],"クリプキ":[{"t":"核心","ic":"◈","v":"固有名は意味の記述によってでなく、最初の命名から因果的に受け継がれる連鎖によって対象を指すと論じた(固定指示子)。"},{"t":"本人の言葉","ic":"❝","v":"名前は、対象を固定的に指し示す。","by":""},{"t":"何を言ったか","ic":"⟲","v":"固有名は意味の記述によってでなく、最初の命名から因果的に受け継がれる連鎖によって対象を指すと論じた(固定指示子)。これにより、経験によって知られるが必然的に真である事柄がありうると示した。"},{"t":"築いた体系","ic":"✦","v":"様相論理の意味論を整備し、指示や必然性をめぐる議論を一新した。『名指しと必然性』は言語哲学・形而上学に決定的な影響を与え、記述説を覆した。"},{"t":"キーワード","ic":"⚑","v":"固定指示子　あらゆる可能な状況で同じ対象を指し続ける名前のあり方。\n因果的命名説　名前は記述でなく、命名からの因果連鎖で対象を指すとする説。\n必然的な後天的真理　経験で知られるが、必然的に真である事柄。"},{"t":"つながり","ic":"→","v":"フレーゲ（批判）\n名前は記述を通じて対象を指すとするフレーゲ以来の記述説を、因果的命名説によって覆した。"}],"サール":[{"t":"核心","ic":"◈","v":"発話を、約束・命令・断言などの「行為」として分析する言語行為論を発展させた。"},{"t":"本人の言葉","ic":"❝","v":"中国語の部屋は、記号を操っても理解してはいない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"発話を、約束・命令・断言などの「行為」として分析する言語行為論を発展させた。「中国語の部屋」の思考実験で、記号の操作(計算)だけでは意味の理解や心は生じないと論じ、強いAIを批判した。"},{"t":"築いた体系","ic":"✦","v":"言語哲学と心の哲学をつなぎ、志向性や意識をめぐる議論を展開した。言語行為論と中国語の部屋の議論は、言語・認知科学・AI論に広く影響している。"},{"t":"キーワード","ic":"⚑","v":"言語行為論　発話を約束・命令などの行為として捉え分析する理論。\n中国語の部屋　記号操作だけでは理解は生じないと示す、強いAI批判の思考実験。\n志向性　心が何ものかについて向かい、それを表す性質。"},{"t":"つながり","ic":"→","v":"ウィトゲンシュタイン（影響を受ける）\n言葉の意味を使用に見る後期ウィトゲンシュタインの流れを汲み、言語行為論を発展させた。"}],"パトナム":[{"t":"核心","ic":"◈","v":"語の意味は個人の心の中だけでなく、外界の対象や社会的な分業によって決まると論じた(意味の外在主義)。"},{"t":"本人の言葉","ic":"❝","v":"意味は、頭の中だけにあるのではない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"語の意味は個人の心の中だけでなく、外界の対象や社会的な分業によって決まると論じた(意味の外在主義)。心を機能の観点から捉える機能主義を唱えたが、後に自らの実在論を修正するなど、生涯思索を改め続けた。"},{"t":"築いた体系","ic":"✦","v":"科学哲学・言語哲学・心の哲学を横断し、実在論をめぐる議論を主導した。双子地球の思考実験など、その論点は現代哲学の基本問題として議論され続けている。"},{"t":"キーワード","ic":"⚑","v":"意味の外在主義　語の意味は頭の中でなく、外界や社会にも依存するという考え。\n双子地球　意味が外的環境に依存することを示す思考実験。\n機能主義　心的状態を、その担う機能・役割によって捉える立場。"},{"t":"つながり","ic":"→","v":"クワイン（師事し継承）\n経験主義と自然主義の姿勢を受け継ぎつつ、独自の実在論へ進んだ。"}],"ヤスパース":[{"t":"核心","ic":"◈","v":"死・苦しみ・争い・罪といった、避けることも乗り越えることもできない「限界状況」に直面するとき、人は初めて本来の実存に目覚めると論じた。"},{"t":"本人の言葉","ic":"❝","v":"限界状況において、人は本来の自己に目覚める。","by":""},{"t":"何を言ったか","ic":"⟲","v":"死・苦しみ・争い・罪といった、避けることも乗り越えることもできない「限界状況」に直面するとき、人は初めて本来の実存に目覚めると論じた。理性では捉えきれない超越者(包括者)への信を説いた。"},{"t":"築いた体系","ic":"✦","v":"精神医学から出発し、実存哲学を築いた。限界状況・実存的交わり・包括者などの概念で、科学では届かない人間の depth を照らし、実存主義と宗教哲学に影響した。"},{"t":"キーワード","ic":"⚑","v":"限界状況　死・苦・罪など、避けられず人を本来の自己へ目覚めさせる状況。\n実存　客観的に対象化できない、いま生きる本来的な自己。\n包括者　あらゆる対象を超え、それらを包み込む究極の全体・超越者。"},{"t":"つながり","ic":"→","v":"キルケゴール（影響を受ける）\nいま生きる個の実存を重んじるキルケゴールの問題意識を受け継いだ。"}],"ガダマー":[{"t":"核心","ic":"◈","v":"理解には、私たちが歴史から受け継いだ先入見(先入観)が不可欠に働いていると論じた。"},{"t":"本人の言葉","ic":"❝","v":"理解とは、地平の融合である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"理解には、私たちが歴史から受け継いだ先入見(先入観)が不可欠に働いていると論じた。テクストや他者を理解するとは、自分の地平と相手の地平が出会い溶け合うこと(地平の融合)だとした。"},{"t":"築いた体系","ic":"✦","v":"ハイデガーを継ぎ、哲学的解釈学を大成した。『真理と方法』で、科学的方法とは別の、対話と伝統を通じた真理のあり方を示し、人文学に広く影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"解釈学　テクストや他者を理解する営みそのものを問う哲学。\n地平の融合　理解する側とされる側の視野が出会い、溶け合うこと。\n先入見(先理解)　伝統から受け継がれ、理解を可能にする前提的な見方。"},{"t":"つながり","ic":"→","v":"ハイデガー（師・継承）\n師ハイデガーの理解と解釈の思索を受け継ぎ、それを哲学的解釈学として展開した。"}],"リクール":[{"t":"核心","ic":"◈","v":"象徴や物語、テクストの解釈を通して人間の自己理解を探究した。"},{"t":"本人の言葉","ic":"❝","v":"自己を、他者を経由して理解する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"象徴や物語、テクストの解釈を通して人間の自己理解を探究した。人は自らの人生を物語ることで一貫した自己(物語的アイデンティティ)を築くとし、隠喩や記憶・赦しといった主題を深く論じた。"},{"t":"築いた体系","ic":"✦","v":"現象学と解釈学を結びつけ、意志・象徴・物語・記憶を横断する広大な思索を展開した。その哲学は倫理学・歴史学・宗教学など多くの分野に影響を与えている。"},{"t":"キーワード","ic":"⚑","v":"解釈学　象徴やテクストの解釈を通じて意味と自己を理解する営み。\n物語的アイデンティティ　自らの人生を物語ることで築かれる、一貫した自己。\n隠喩　言葉の新しい結びつきによって現実を捉え直す働き。"},{"t":"つながり","ic":"→","v":"フッサール（継承しつつ転換）\n意識の直接把握を退け、解釈という迂回を組み込んで現象学を刷新した。"}],"アドルノ":[{"t":"核心","ic":"◈","v":"啓蒙の理性が、自然と人間を支配・管理する道具に転化し、かえって野蛮(全体主義や画一化)を生んだと批判した。"},{"t":"本人の言葉","ic":"❝","v":"アウシュヴィッツの後で詩を書くことは野蛮である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"啓蒙の理性が、自然と人間を支配・管理する道具に転化し、かえって野蛮(全体主義や画一化)を生んだと批判した。文化産業が大衆の思考を規格化することを鋭く分析し、既成の全体に回収されない思考を求めた。"},{"t":"築いた体系","ic":"✦","v":"フランクフルト学派の中心として批判理論を展開し、『啓蒙の弁証法』などを著した。同一性の思考を批判する否定弁証法や芸術論は、現代思想と美学に深い影響を残した。"},{"t":"キーワード","ic":"⚑","v":"批判理論　社会の支配構造を暴き、その変革を目指す哲学的社会理論。\n啓蒙の弁証法　理性が支配の道具に転化し、野蛮を生むという逆説の分析。\n文化産業　大衆文化が思考を規格化し、人々を順応させる仕組み。"},{"t":"つながり","ic":"→","v":"ヘーゲル（批判的に継承）\nヘーゲルの弁証法を受け継ぎつつ、対立を統合へ回収しない『否定弁証法』へと組み替えた。"}],"ベンヤミン":[{"t":"核心","ic":"◈","v":"写真や映画などの複製技術が、芸術作品の一回性がまとう神秘的な輝き「アウラ」を消し去ると論じた。"},{"t":"本人の言葉","ic":"❝","v":"複製技術は、芸術から「アウラ」を奪う。","by":""},{"t":"何を言ったか","ic":"⟲","v":"写真や映画などの複製技術が、芸術作品の一回性がまとう神秘的な輝き「アウラ」を消し去ると論じた。歴史を勝者の連続でなく、抑圧された者の記憶から救い出す視点で捉え直そうとした。"},{"t":"築いた体系","ic":"✦","v":"批評・言語・歴史・技術を横断する独特の思索を、断章的な文体で残した。アウラや複製技術論、歴史哲学のテーゼは、メディア論や現代思想に広く影響を与えている。"},{"t":"キーワード","ic":"⚑","v":"アウラ　芸術作品の一回性・真正性がまとう、近づきがたい輝き。\n複製技術　写真・映画など、作品を大量に複製する技術とその影響。\n歴史の天使　過去の破局を見つめ続ける、彼の歴史哲学の象徴的イメージ。"},{"t":"つながり","ic":"→","v":"アドルノ（盟友・相互影響）\nアドルノと深く交流し、複製技術やアウラの議論を通じて批判理論の芸術論に影響を与えた。"}],"慧能":[{"t":"核心","ic":"◈","v":"文字や段階的修行にとらわれず、自らの本性が本来仏であると一挙に悟る「頓悟」を説いた。"},{"t":"本人の言葉","ic":"❝","v":"菩提もともと樹なし、明鏡もまた台にあらず。","by":""},{"t":"何を言ったか","ic":"⟲","v":"文字や段階的修行にとらわれず、自らの本性が本来仏であると一挙に悟る「頓悟」を説いた。心はもともと清らかで、迷いを払えばそのまま悟りが現れるとし、坐禅も日常のふるまいの中にあるとした。"},{"t":"築いた体系","ic":"✦","v":"禅宗の第六祖とされ、その教えは『六祖壇経』にまとめられた。頓悟と見性を軸とする南宗禅は、後の中国・日本の禅の主流となり、東アジア仏教に決定的な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"頓悟　段階を踏まず、一挙に本性を悟ること。\n見性　自らの本性(仏性)を直接に見て取ること。\n本来清浄　心はもともと清らかで、そのまま仏であるとする考え。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（源流）\nブッダの悟りを、文字によらず心から心へ直接に受け継ぐ、という禅の系譜に立つ。"}],"世親":[{"t":"核心","ic":"◈","v":"外界の事物はそれ自体で実在するのでなく、すべては心(識)が生み出した現れにすぎないと説いた(唯識)。"},{"t":"本人の言葉","ic":"❝","v":"世界は、ただ識(心)の現れである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"外界の事物はそれ自体で実在するのでなく、すべては心(識)が生み出した現れにすぎないと説いた(唯識)。心の深層に、経験の種子を蓄え輪廻の基となる阿頼耶識があるとし、心の構造を精緻に分析した。"},{"t":"築いた体系","ic":"✦","v":"兄の無著とともに唯識思想を大成し、大乗仏教の一大学派(瑜伽行派)を築いた。その心の分析は東アジアの法相宗などに受け継がれ、仏教心理学の基礎となった。"},{"t":"キーワード","ic":"⚑","v":"唯識　外界は実在せず、すべては心(識)の現れだとする思想。\n阿頼耶識　経験の種子を蓄え、輪廻の基となる心の深層。\n種子　阿頼耶識に蓄えられ、経験や行為を生み出す潜在的な力。"},{"t":"つながり","ic":"→","v":"無著（兄・共同）\n兄の無著とともに唯識思想を大成し、瑜伽行唯識派を確立した。"}],"無著":[{"t":"核心","ic":"◈","v":"瞑想の実践(瑜伽)を通じて得た洞察をもとに、唯識思想を体系化した。"},{"t":"本人の言葉","ic":"❝","v":"菩薩は、一切衆生の救済のために歩む。","by":""},{"t":"何を言ったか","ic":"⟲","v":"瞑想の実践(瑜伽)を通じて得た洞察をもとに、唯識思想を体系化した。菩薩が悟りへ向かって歩む段階と実践を整え、慈悲によってすべての生きものを救おうとする大乗の理想を理論づけた。"},{"t":"築いた体系","ic":"✦","v":"弟の世親とともに瑜伽行唯識派を確立した。菩薩道の体系化と唯識の教理は、インドから東アジアへ伝わり、大乗仏教の思想的支柱の一つとなった。"},{"t":"キーワード","ic":"⚑","v":"瑜伽行　瞑想の実践(ヨーガ)を通じて真理を体得する道。\n菩薩道　衆生救済のために悟りへ向かって歩む、大乗の理想の歩み。\n唯識　すべては心の現れだとする、彼らが体系化した思想。"},{"t":"つながり","ic":"→","v":"世親（兄弟・共同）\n弟の世親を大乗に導き、ともに唯識思想を大成した。"}],"最澄":[{"t":"核心","ic":"◈","v":"すべての人に等しく仏になれる素質(仏性)があると説く天台の教えを、唐から日本へもたらした。"},{"t":"本人の言葉","ic":"❝","v":"一隅を照らす、これ則ち国宝なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"すべての人に等しく仏になれる素質(仏性)があると説く天台の教えを、唐から日本へもたらした。あらゆる衆生の成仏を認める立場に立ち、社会の片隅で人を照らす人材こそ国の宝だと説いた。"},{"t":"築いた体系","ic":"✦","v":"日本天台宗を開き、比叡山を総合的な仏教教育の場とした。その普遍的な成仏の思想と教育は、法然・親鸞・道元・日蓮ら鎌倉仏教の祖師を生む母胎となった。"},{"t":"キーワード","ic":"⚑","v":"一切衆生悉有仏性　すべての生きものが等しく仏になれる素質をもつという考え。\n天台の教え　『法華経』を最高とし、あらゆる教えを統合する仏教の体系。\n一隅を照らす　社会の片隅で人を照らし尽くす人こそ国の宝だという理念。"},{"t":"つながり","ic":"→","v":"空海（同時代（交流と対立））\n真言宗の空海と同時代に活躍し、当初交流したが、密教の理解をめぐって後に対立した。"}],"法然":[{"t":"核心","ic":"◈","v":"厳しい修行や学問によらず、ひたすら「南無阿弥陀仏」と称える念仏(専修念仏)によって、誰もが等しく極楽往生できると説いた。"},{"t":"本人の言葉","ic":"❝","v":"ただ念仏して、弥陀にたすけられまいらすべし。","by":""},{"t":"何を言ったか","ic":"⟲","v":"厳しい修行や学問によらず、ひたすら「南無阿弥陀仏」と称える念仏(専修念仏)によって、誰もが等しく極楽往生できると説いた。自力でなく、阿弥陀仏の本願にすべてをゆだねる他力の道を開いた。"},{"t":"築いた体系","ic":"✦","v":"浄土宗を開き、万人に開かれた易しい救いの道を示した。専修念仏の教えは民衆に広く受け入れられ、親鸞ら後の浄土教の発展の礎となった。"},{"t":"キーワード","ic":"⚑","v":"専修念仏　他の行を交えず、ひたすら念仏を称えること。\n他力本願　自力でなく、阿弥陀仏の本願の力にすべてをゆだねること。\n称名念仏　「南無阿弥陀仏」と口に称えること。"},{"t":"つながり","ic":"→","v":"親鸞（弟子へ）\nその他力・専修念仏の教えは、弟子の親鸞によって絶対他力へとさらに徹底された。"}],"親鸞":[{"t":"核心","ic":"◈","v":"師法然の他力の教えをさらに徹底し、救いは自分の善行によるのでなく、まったく阿弥陀仏の力(絶対他力)によると説いた。"},{"t":"本人の言葉","ic":"❝","v":"善人なほもて往生をとぐ、いはんや悪人をや。","by":""},{"t":"何を言ったか","ic":"⟲","v":"師法然の他力の教えをさらに徹底し、救いは自分の善行によるのでなく、まったく阿弥陀仏の力(絶対他力)によると説いた。自らの力では善をなしえない煩悩深き人間(悪人)こそ、まさに救いの対象だとした。"},{"t":"築いた体系","ic":"✦","v":"浄土真宗を開き、在家のまま信心によって救われる道を示した。悪人正機や絶対他力の思想は、日本の宗教思想に深い影響を与え続けている。"},{"t":"キーワード","ic":"⚑","v":"絶対他力　救いはすべて阿弥陀仏の力によるとし、自力を徹底して退ける立場。\n悪人正機　煩悩深く自力で善をなしえない者こそ救いの正しい対象だとする考え。\n信心　阿弥陀仏の救いを疑いなく受け入れる心。往生の要とされる。"},{"t":"つながり","ic":"→","v":"法然（師）\n師法然の専修念仏・他力の教えを受け継ぎ、それを絶対他力へとさらに徹底した。"}],"日蓮":[{"t":"核心","ic":"◈","v":"『法華経』こそ釈迦の真の教えであり、そこにすべての人が成仏する道が説かれていると確信した。"},{"t":"本人の言葉","ic":"❝","v":"南無妙法蓮華経。","by":""},{"t":"何を言ったか","ic":"⟲","v":"『法華経』こそ釈迦の真の教えであり、そこにすべての人が成仏する道が説かれていると確信した。題目「南無妙法蓮華経」を唱えることで、この身このまま仏になれると説き、現実世界に仏国土を築くことを目指した。"},{"t":"築いた体系","ic":"✦","v":"日蓮宗を開き、『法華経』への絶対的帰依と唱題を中心とする信仰を確立した。その現実変革的で情熱的な思想は、後世の宗教運動にも大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"題目(唱題)　「南無妙法蓮華経」と唱えること。成仏の直接の道とされる。\n法華経至上　『法華経』を釈迦の究極の教えとみなす立場。\n即身成仏　この身このまま仏になれるという考え。"},{"t":"つながり","ic":"→","v":"最澄（継承しつつ展開）\n法華経を重んじる天台の伝統を受け、それを唱題の実践へ純化した。"}],"伊藤仁斎":[{"t":"核心","ic":"◈","v":"後世の朱子学の抽象的な理論を退け、孔子・孟子の原典に立ち返ってその真意を捉えようとした(古義学)。"},{"t":"本人の言葉","ic":"❝","v":"仁とは、愛のみ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"後世の朱子学の抽象的な理論を退け、孔子・孟子の原典に立ち返ってその真意を捉えようとした(古義学)。仁の本質を、理屈でなく人を愛する具体的な情愛に見いだし、日常の人倫の中に道を求めた。"},{"t":"築いた体系","ic":"✦","v":"京都で古義学派を開き、『論語』『孟子』を熟読して独自の解釈を示した。その実践的で人間味ある儒学は、江戸時代の思想に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"古義学　後世の注釈でなく、孔孟の原典に立ち返って真意を求める学問。\n仁=愛　仁の本質を、人を愛する具体的な情愛に見る考え。\n日常の人倫　抽象理論でなく、日々の人間関係の中に道を求める姿勢。"},{"t":"つながり","ic":"→","v":"朱熹（批判的に対峙）\n理を中心とする思弁的な朱子学を退け、原典と日常の道徳に立ち返った。"}],"荻生徂徠":[{"t":"核心","ic":"◈","v":"道を、自然の理でなく、古代の聖王が民を治めるために作った具体的な制度・礼楽(先王の道)だと捉えた。"},{"t":"本人の言葉","ic":"❝","v":"道とは、先王が作った制度・文物のことである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"道を、自然の理でなく、古代の聖王が民を治めるために作った具体的な制度・礼楽(先王の道)だと捉えた。抽象的な心の修養より、社会を治める政治・制度の学を重んじ、古代中国語で原典を読む方法を説いた。"},{"t":"築いた体系","ic":"✦","v":"古文辞学を唱え、経典を古代の言語と歴史に即して読み解いた。その制度重視・政治優先の学は、後の経世論や国学の方法にも影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"先王の道　古代の聖王が制定した制度・礼楽としての道。\n古文辞学　経典を古代中国語と歴史の文脈に即して読み解く方法。\n経世済民　世を治め民を救うことを学問の目的とする考え。"},{"t":"つながり","ic":"→","v":"伊藤仁斎（批判しつつ継承）\n原典回帰を受け継ぎつつ、道を愛でなく制度と見る点で鋭く対立した。"}],"本居宣長":[{"t":"核心","ic":"◈","v":"儒教や仏教の理屈(漢意)を退け、古代日本人の素直な心情に立ち返ろうとした。"},{"t":"本人の言葉","ic":"❝","v":"もののあはれを知る、これぞ心なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"儒教や仏教の理屈(漢意)を退け、古代日本人の素直な心情に立ち返ろうとした。文学や人生の本質を、物事に触れて自然にわき起こる感動「もののあはれ」に見いだし、『源氏物語』や『古事記』を研究した。"},{"t":"築いた体系","ic":"✦","v":"国学を大成し、日本古来の心性と古典の価値を明らかにした。『古事記伝』などの緻密な文献研究と、もののあはれ論は、日本の文学論・思想に大きな足跡を残した。"},{"t":"キーワード","ic":"⚑","v":"もののあはれ　物事に触れて自然にわき起こる、しみじみとした感動・情趣。\n漢意(からごころ)　儒仏に染まった理屈っぽい心。宣長が退けようとしたもの。\n真心(まごころ)　作為のない、生まれつきの素直な心情。"},{"t":"つながり","ic":"→","v":"荻生徂徠（方法を受けた）\n古語を厳密に読む古文辞の方法を、日本古典の研究に応用した。"}],"福沢諭吉":[{"t":"核心","ic":"◈","v":"人はみな生まれながらに平等であり、身分でなく学問によって独立した個人となるべきだと説いた。"},{"t":"本人の言葉","ic":"❝","v":"天は人の上に人を造らず、人の下に人を造らず。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人はみな生まれながらに平等であり、身分でなく学問によって独立した個人となるべきだと説いた。西洋の実学と合理的精神を取り入れ、独立した個人が独立した国家を支えるという「独立自尊」を唱えた。"},{"t":"築いた体系","ic":"✦","v":"明治日本を代表する啓蒙思想家として、封建的な身分意識を批判し、近代的な人間観・国家観を広めた。『学問のすゝめ』などは近代日本の精神形成に絶大な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"天賦人権　人はみな生まれながらに平等な権利をもつという考え。\n独立自尊　他に頼らず自らの判断と責任で立つ、独立した個人のあり方。\n実学　生活や社会に役立つ、実際的で合理的な学問。"},{"t":"つながり","ic":"→","v":"ジョン・ロック（影響を受ける）\n人が生まれながらに権利をもつという西洋近代の天賦人権論を、日本に紹介・普及した。"}],"ガンディー":[{"t":"核心","ic":"◈","v":"暴力に暴力で応じず、真理を堅く守り抜くこと(サティヤーグラハ)によって不正に立ち向かうことを説いた。"},{"t":"本人の言葉","ic":"❝","v":"あなたが見たい変化に、あなた自身がなりなさい。","by":""},{"t":"何を言ったか","ic":"⟲","v":"暴力に暴力で応じず、真理を堅く守り抜くこと(サティヤーグラハ)によって不正に立ち向かうことを説いた。非暴力(アヒンサー)を単なる無抵抗でなく、愛と勇気に基づく積極的な闘いの原理とした。"},{"t":"築いた体系","ic":"✦","v":"宗教的・倫理的な思想を政治的実践に結びつけ、インド独立運動を導いた。非暴力・不服従の思想は、キング牧師ら世界の人権運動に受け継がれている。"},{"t":"キーワード","ic":"⚑","v":"非暴力(アヒンサー)　いかなる生きものも傷つけない、愛に基づく態度。\nサティヤーグラハ　真理を堅持し、非暴力で不正に抵抗する実践。\n不服従　不正な法や権力に、暴力によらず従わないこと。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（影響を受ける）\nあらゆる生きものを傷つけないというインドの非暴力(アヒンサー)の伝統を受け継いだ。"}],"ヴィヴェーカーナンダ":[{"t":"核心","ic":"◈","v":"ヴェーダーンタの不二一元の思想を、すべての人の内に神性が宿るという普遍的なメッセージとして説いた。"},{"t":"本人の言葉","ic":"❝","v":"あなた自身が神である。それを悟りなさい。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ヴェーダーンタの不二一元の思想を、すべての人の内に神性が宿るという普遍的なメッセージとして説いた。あらゆる宗教は同じ真理への異なる道だとし、他者への奉仕を神への礼拝とする実践的な精神性を訴えた。"},{"t":"築いた体系","ic":"✦","v":"近代ヒンドゥー教を刷新し、インドの精神的伝統を世界へ紹介した。宗教の普遍性と人間への奉仕を説くその思想は、近代インドの精神的覚醒を促した。"},{"t":"キーワード","ic":"⚑","v":"内なる神性　すべての人の魂の奥に神が宿っているという思想。\n諸宗教の調和　あらゆる宗教は同じ真理への異なる道だとする考え。\n奉仕　人々への奉仕を、そのまま神への礼拝とみなす実践。"},{"t":"つながり","ic":"→","v":"シャンカラ（継承し刷新）\n梵我一如の教えを受け継ぎ、近代の実践的な思想へと読み替えた。"}],"ラーマーヌジャ":[{"t":"核心","ic":"◈","v":"世界を幻とみなすシャンカラの厳格な一元論に対し、神と個々の魂・世界は区別されながらも一体をなす(限定不二一元)と説いた。"},{"t":"本人の言葉","ic":"❝","v":"神と魂は、区別を保ちつつ一つである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"世界を幻とみなすシャンカラの厳格な一元論に対し、神と個々の魂・世界は区別されながらも一体をなす(限定不二一元)と説いた。人格神への愛と帰依(バクティ)によって解脱に至る道を重んじた。"},{"t":"築いた体系","ic":"✦","v":"ヴェーダーンタの一学派を確立し、哲学と信仰・愛を結びつけた。その限定不二一元論とバクティの思想は、後のインドの信愛運動に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"限定不二一元論　神と魂・世界は区別を保ちつつ一体をなすとする立場。\nバクティ　人格神への深い愛と帰依。解脱への道とされる。\n人格神　愛と恩寵をもって魂を導く、人格をもった最高神。"},{"t":"つながり","ic":"→","v":"シャンカラ（批判し対立）\n世界を幻とする一元論に反対し、区別を残す信愛の道を示した。"}],"パタンジャリ":[{"t":"核心","ic":"◈","v":"心の動きを静め、真の自己(プルシャ)を、それを覆う物質(プラクリティ)から見分けることを解脱の道とした。"},{"t":"本人の言葉","ic":"❝","v":"ヨーガとは、心のはたらきを止滅することである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"心の動きを静め、真の自己(プルシャ)を、それを覆う物質(プラクリティ)から見分けることを解脱の道とした。八つの段階から成る実践(八支則)によって、心を制御し瞑想を深める体系的な方法を示した。"},{"t":"築いた体系","ic":"✦","v":"『ヨーガ・スートラ』を編み、ヨーガ学派を体系化した。心の制御と瞑想の実践を段階的に整えたその教えは、インド精神文化の根幹をなし、世界の瞑想実践の源泉となっている。"},{"t":"キーワード","ic":"⚑","v":"ヨーガ　心のはたらきを静め、真の自己に至るための実践。\n八支則　禁戒・勧戒・坐法・調気・瞑想など、ヨーガの八つの段階。\n心の止滅　揺れ動く心の作用を鎮め、静けさに至ること。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（実践を共有）\n心を静める瞑想を通して苦からの解放を目指す点で通じ合う。"}],"アル・キンディー":[{"t":"核心","ic":"◈","v":"ギリシア哲学をイスラーム世界に本格的に導入した最初の哲学者。"},{"t":"本人の言葉","ic":"❝","v":"真理は、どこから来ようと受け入れねばならない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ギリシア哲学をイスラーム世界に本格的に導入した最初の哲学者。理性による探究と啓示の真理は調和すると考え、他文化に由来する知でも真理であれば受け入れるべきだと説いた。数学・医学・天文にも通じた。"},{"t":"築いた体系","ic":"✦","v":"アラビア語による哲学の礎を築き、「アラブ人の哲学者」と呼ばれた。ギリシア哲学の翻訳・普及を進め、後のファーラービーやイブン・シーナーの哲学への道を開いた。"},{"t":"キーワード","ic":"⚑","v":"哲学と信仰の調和　理性による哲学と啓示の真理は矛盾しないとする立場。\nギリシア哲学の導入　ギリシアの学問をイスラーム世界へ本格的に取り入れたこと。\n真理の普遍性　真理はどの文化に由来しても受け入れるべきだという考え。"},{"t":"つながり","ic":"→","v":"アリストテレス（導入し継承）\nその哲学をイスラーム世界に紹介し、以後の思索の土台を据えた。"}],"アル・ファーラービー":[{"t":"核心","ic":"◈","v":"アリストテレスの論理学とプラトンの政治思想を統合し、人々が理性を完成させ真の幸福に至る「徳ある都市」を構想した。"},{"t":"本人の言葉","ic":"❝","v":"徳ある都市とは、真の幸福を目指す共同体である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"アリストテレスの論理学とプラトンの政治思想を統合し、人々が理性を完成させ真の幸福に至る「徳ある都市」を構想した。預言者=哲人王が人々を幸福へ導く理想国家を描いた。"},{"t":"築いた体系","ic":"✦","v":"「第二の師(アリストテレスに次ぐ師)」と称され、イスラーム哲学の体系を確立した。その論理学と政治哲学は、イブン・シーナーやマイモニデスに受け継がれた。"},{"t":"キーワード","ic":"⚑","v":"徳ある都市　人々が理性を完成させ、真の幸福を目指す理想の共同体。\n哲人王=預言者　哲学者にして預言者が人々を幸福へ導くとする理想像。\n知性の階梯　人間の知性が能動知性へと高まり真理に至る段階。"},{"t":"つながり","ic":"→","v":"アリストテレス（継承）\nアリストテレスの論理学と哲学を受け継ぎ、『第二の師』と称された。"}],"ガザーリー":[{"t":"核心","ic":"◈","v":"哲学者たちが理性で神や世界を論じることの限界を鋭く批判し、確実な真理は理性でなく神との直接的な体験(神秘的直観)にあると説いた。"},{"t":"本人の言葉","ic":"❝","v":"哲学者たちの主張は、自壊する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"哲学者たちが理性で神や世界を論じることの限界を鋭く批判し、確実な真理は理性でなく神との直接的な体験(神秘的直観)にあると説いた。自らの信仰の危機を、スーフィズムの実践によって乗り越えた。"},{"t":"築いた体系","ic":"✦","v":"神学・法学・哲学に精通しつつ、最終的にスーフィズム(イスラーム神秘主義)を正統な信仰の道として基礎づけた。その哲学批判と内面の探究は、イスラーム思想の方向を大きく定めた。"},{"t":"キーワード","ic":"⚑","v":"哲学批判　理性で神や世界を論じる哲学の越権と限界を突く議論。\nスーフィズム　神との直接的な合一を求めるイスラーム神秘主義。\n神秘的直観　論証でなく、体験によって真理を直接に知ること。"},{"t":"つながり","ic":"→","v":"イブン・シーナー(アヴィセンナ)（批判）\n理性で神や世界を論じるイブン・シーナーら哲学者を、その越権と矛盾ゆえに批判した。"}],"イブン・アラビー":[{"t":"核心","ic":"◈","v":"真に存在するのは神だけであり、世界の多様な事物は唯一の実在が自らを現した姿(存在一性論)だと説いた。"},{"t":"本人の言葉","ic":"❝","v":"存在するのは、ただ一つの実在(神)のみである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"真に存在するのは神だけであり、世界の多様な事物は唯一の実在が自らを現した姿(存在一性論)だと説いた。人間、とりわけ完成された人(完全人間)は、神が自らを映し出す鏡だとした。"},{"t":"築いた体系","ic":"✦","v":"イスラーム神秘主義思想を哲学的に深化させ、「最大の師」と称された。その存在一性論と象徴に満ちた思想は、後のスーフィズムやイスラーム哲学に絶大な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"存在一性論　真に存在するのは神のみで、万物はその現れだとする思想。\n完全人間　神の属性を余さず映し出す、完成された理想の人間。\n神の顕現　唯一の実在が、多様な事物として自らを現すこと。"},{"t":"つながり","ic":"→","v":"ガザーリー（継承しつつ深化）\n神秘主義を正統に位置づけた道を受け、その形而上学を深めた。"}],"イブン・ハルドゥーン":[{"t":"核心","ic":"◈","v":"歴史を、道徳の教訓でなく、社会の法則によって説明しようとした。"},{"t":"本人の言葉","ic":"❝","v":"王朝は、連帯意識の盛衰とともに興り、そして滅びる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"歴史を、道徳の教訓でなく、社会の法則によって説明しようとした。集団を結束させる連帯意識(アサビーヤ)の強弱が王朝の興亡を決めると分析し、遊牧と定住、都市の盛衰の循環を論じた。"},{"t":"築いた体系","ic":"✦","v":"『歴史序説』で社会の変動を法則的に捉える視点を打ち立て、社会学・歴史学の先駆者とされる。その循環史観と社会分析は、近代の社会科学を数世紀先取りしていた。"},{"t":"キーワード","ic":"⚑","v":"アサビーヤ(連帯意識)　集団を結束させる連帯感。王朝の興亡を左右する力。\n王朝の循環　連帯意識の盛衰に応じて王朝が興り衰えるという歴史観。\n社会の科学　歴史を教訓でなく、社会の法則によって説明しようとする試み。"},{"t":"つながり","ic":"→","v":"アリストテレス（影響を受ける）\n事物を観察し法則を求めるアリストテレス以来の学問の姿勢を、歴史・社会の分析に応用した。"}],"フィロン":[{"t":"核心","ic":"◈","v":"ユダヤ教の聖書とギリシア哲学(とりわけプラトン主義)を融合させた。"},{"t":"本人の言葉","ic":"❝","v":"聖書は、寓意として深く読まれねばならない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ユダヤ教の聖書とギリシア哲学(とりわけプラトン主義)を融合させた。聖書の記述を字義通りでなく寓意的に解釈し、神と世界を仲立ちする理性的原理「ロゴス」を説いた。"},{"t":"築いた体系","ic":"✦","v":"ヘレニズム期のユダヤ思想を代表し、信仰と哲学の総合を初めて大規模に試みた。そのロゴス論と寓意的解釈は、後のキリスト教神学や新プラトン主義に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"ロゴス　超越した神と世界を仲立ちする、神の理性的原理。\n寓意的解釈　聖書を字義通りでなく、隠された意味として読み解く方法。\n信仰と哲学の総合　ユダヤ教の啓示とギリシア哲学を結びつける試み。"},{"t":"つながり","ic":"→","v":"プラトン（影響を受けた）\n感覚を超えた真実在という発想を、聖書解釈に取り入れた。"}],"マルティン・ブーバー":[{"t":"核心","ic":"◈","v":"人が世界に関わる仕方には、相手を対象として利用する「われ-それ」と、相手を人格として全身で向き合う「われ-なんじ」の二つがあると論じた。"},{"t":"本人の言葉","ic":"❝","v":"はじめに関係ありき。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人が世界に関わる仕方には、相手を対象として利用する「われ-それ」と、相手を人格として全身で向き合う「われ-なんじ」の二つがあると論じた。真の生は後者の出会いの中にあり、そこに永遠のなんじ(神)が現れるとした。"},{"t":"築いた体系","ic":"✦","v":"ユダヤ教の伝統(ハシディズム)を汲みつつ、対話をめぐる独自の哲学を築いた。「われ-なんじ」の思想は、宗教哲学・教育・心理療法など幅広い分野に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"われ-なんじ　相手を人格として全身で向き合う、真の出会いの関係。\nわれ-それ　相手を対象・手段として扱う、利用的な関わり方。\n対話　互いを人格として認め合う、生きた出会いとしての関係。"},{"t":"つながり","ic":"→","v":"レヴィナス（影響を与えた）\n他者との出会いを哲学の中心に置く発想が、後の他者論へつながった。"}],"シモーヌ・ヴェイユ":[{"t":"核心","ic":"◈","v":"他者の苦しみ、とりわけ社会から見捨てられた人々の不幸に深く向き合った。"},{"t":"本人の言葉","ic":"❝","v":"注意とは、最も稀で、最も純粋な、寛大さの形である。","by":"書簡より"},{"t":"転回","ic":"⟲","v":"苦しんでいる人に対して、私たちはすぐ助言をし、励まし、自分の似た経験を語りたくなります。彼女に言わせれば、それらは全部、相手から目をそらす方法です。本当に難しいのは、ただ相手を見つめ、あなたはどんな苦しみの中にいるのですか、と問える状態でいること。彼女はそれを、学問の勉強が最終的に鍛えるべき能力だとまで言いました。"},{"t":"生の事実","ic":"✦","v":"哲学教師だった彼女は、工場へ働きに行った——1934年、名門校の教授資格を持つ彼女は、休職して工場労働者になります。ルノーなどの工場で、金属プレス機を扱いました。"},{"t":"最も強い反論","ic":"⚡","v":"彼女の生き方は、聖性と自己破壊のどちらとも読めます。友人たちは彼女の極端さに困惑し、支援を拒まれ続けました。他者の不幸に注意を向けよという教えを、彼女は自分を消すところまで実行しましたが、それは模倣可能な倫理なのか。加えて、ユダヤ人でありながら旧約聖書とユダヤ教に強い嫌悪を示した彼女の文章は、その出自と時代を考えると、今も痛みを伴う論点として残っています。"},{"t":"あなたへ","ic":"→","v":"最後に誰かの話を聞いたとき、あなたは助言も自分の話もせずに、ただ聞ききることができましたか。"}],"マルクーゼ":[{"t":"核心","ic":"◈","v":"高度産業社会は、豊かさと快適さによって人々の批判力を眠らせ、体制に順応した「一次元的人間」を作り出すと批判した。"},{"t":"本人の言葉","ic":"❝","v":"豊かな社会は、一次元的な人間を作り出す。","by":""},{"t":"何を言ったか","ic":"⟲","v":"高度産業社会は、豊かさと快適さによって人々の批判力を眠らせ、体制に順応した「一次元的人間」を作り出すと批判した。抑圧された欲求や芸術の中に、この管理社会を突き破る解放の可能性を求めた。"},{"t":"築いた体系","ic":"✦","v":"フランクフルト学派の一員として、フロイトとマルクスを結びつけ現代社会を分析した。その解放の思想は1960年代の学生運動・新左翼に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"一次元的人間　豊かさに順応し、批判力を失った現代社会の人間像。\n抑圧的脱昇華　欲望を管理された形で満たし、反抗心を骨抜きにする仕組み。\n管理社会批判　豊かさによって人々を体制へ順応させる社会への批判。"},{"t":"つながり","ic":"→","v":"アドルノ（同学派・同僚）\n批判理論の仲間として、現代社会と文化の支配を分析した。"}],"ノージック":[{"t":"核心","ic":"◈","v":"個人の権利、とりわけ自由と正当に得た所有を絶対的に尊重する立場から、富の再分配を行う大きな国家を批判した。"},{"t":"本人の言葉","ic":"❝","v":"個人には、侵してはならない権利がある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"個人の権利、とりわけ自由と正当に得た所有を絶対的に尊重する立場から、富の再分配を行う大きな国家を批判した。国家の役割は暴力・盗み・契約違反からの保護に限るべきだとする「最小国家」を擁護した。"},{"t":"築いた体系","ic":"✦","v":"ロールズの正義論に対し、リバタリアニズム(自由至上主義)の立場から反論した。『アナーキー・国家・ユートピア』は、権利と国家の正当性をめぐる現代の議論を活性化させた。"},{"t":"キーワード","ic":"⚑","v":"最小国家　暴力・盗み・詐欺からの保護に役割を限る、最小限の国家。\nリバタリアニズム　個人の自由と所有権を最大限に尊重する立場。\n権原理論　正当な取得と移転を経た所有は正義にかなうとする理論。"},{"t":"つながり","ic":"→","v":"ロールズ（批判・論争）\n格差是正のための再分配を認めるロールズに対し、個人の権利を絶対視して鋭く反論した。"}],"マッキンタイア":[{"t":"核心","ic":"◈","v":"近代の道徳が共通の目的を見失い、感情の表明に堕したと批判した。"},{"t":"本人の言葉","ic":"❝","v":"私は、いかなる物語の一部として生きているのか。","by":""},{"t":"何を言ったか","ic":"⟲","v":"近代の道徳が共通の目的を見失い、感情の表明に堕したと批判した。徳は、共同体の実践や伝統、人生という物語の文脈の中でこそ意味をもつとし、アリストテレス的な徳倫理の復権を唱えた。"},{"t":"築いた体系","ic":"✦","v":"『美徳なき時代』で近代道徳哲学を批判し、共同体・伝統・物語を軸とする徳倫理学を再興した。その議論は現代の徳倫理学とコミュニタリアニズムの中心となった。"},{"t":"キーワード","ic":"⚑","v":"徳倫理の復権　規則でなく、人格に備わる徳を中心に据える倫理の再生。\n実践　共同体に根ざし、内在的な善を目指す協働の営み。\n物語的自己　人生を一つの物語として生きることで得られる自己の統一。"},{"t":"つながり","ic":"→","v":"アリストテレス（復権させた）\n徳と共同体を軸とする倫理を現代によみがえらせようとした。"}],"チャールズ・テイラー":[{"t":"核心","ic":"◈","v":"人間を、自らの価値や意味を解釈しながら生きる存在として捉えた。"},{"t":"本人の言葉","ic":"❝","v":"人間は、意味を解釈する自己である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人間を、自らの価値や意味を解釈しながら生きる存在として捉えた。近代的な自己が、いかに個人の内面の真実性(オーセンティシティ)を重んじるようになったかを歴史的にたどり、その光と影を論じた。"},{"t":"築いた体系","ic":"✦","v":"共同体や文化の中で形づくられる自己を強調し、コミュニタリアニズムを代表した。承認や世俗化をめぐる大きな歴史的考察は、政治哲学・宗教社会学に広く影響している。"},{"t":"キーワード","ic":"⚑","v":"真正性(オーセンティシティ)　自分自身に忠実であろうとする、近代に生まれた価値。\n解釈する自己　意味や価値を解釈しながら生きる存在としての人間。\n承認　人が他者から認められることで自己を形づくるという考え。"},{"t":"つながり","ic":"→","v":"ヘーゲル（影響を受けた）\n自己が他者の承認を通して成り立つという承認論を受け継いだ。"}],"マイケル・サンデル":[{"t":"核心","ic":"◈","v":"個人の自由な選択を偏重するリベラリズムを批判し、正義は共同体で共有される善や美徳と切り離せないと論じた。"},{"t":"本人の言葉","ic":"❝","v":"すべてをお金で買えるわけではない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"個人の自由な選択を偏重するリベラリズムを批判し、正義は共同体で共有される善や美徳と切り離せないと論じた。市場の論理があらゆる領域に浸透することの倫理的な問題を問い、公共的な対話の必要を訴えた。"},{"t":"築いた体系","ic":"✦","v":"コミュニタリアニズムを代表し、正義をめぐる公共哲学を提唱した。その対話型の講義や著作は、道徳・市場・実力主義をめぐる議論を世界中で活性化させている。"},{"t":"キーワード","ic":"⚑","v":"コミュニタリアニズム　個人でなく、共同体の共有する善を重んじる立場。\n共通善　共同体が共に目指すべき善。正義の基礎とされる。\n市場の道徳的限界　金銭で売買すべきでない財や領域があるという主張。"},{"t":"つながり","ic":"→","v":"ロールズ（批判的に対峙）\n負荷なき自己という前提を批判し、共同体に根ざす自己を対置した。"}],"ジュディス・バトラー":[{"t":"核心","ic":"◈","v":"性別やジェンダーは生まれつき固定したものでなく、社会の規範に沿ったふるまいを繰り返すことで作り上げられる(パフォーマティヴィティ)と論じた。"},{"t":"本人の言葉","ic":"❝","v":"ジェンダーとは、反復される行為の効果である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"性別やジェンダーは生まれつき固定したものでなく、社会の規範に沿ったふるまいを繰り返すことで作り上げられる(パフォーマティヴィティ)と論じた。「女」「男」という区分そのものが自然でなく構築されたものだとした。"},{"t":"築いた体系","ic":"✦","v":"フェミニズムとクィア理論を刷新し、アイデンティティの脱構築を進めた。『ジェンダー・トラブル』は性とアイデンティティをめぐる現代の議論に決定的な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"ジェンダー・パフォーマティヴィティ　ジェンダーは反復される行為によって作られる効果だとする考え。\n構築されたジェンダー　性別の区分は自然でなく、社会的に構築されるという見方。\nアイデンティティの脱構築　固定した自己・性の区分を問い直し、揺るがすこと。"},{"t":"つながり","ic":"→","v":"ボーヴォワール（継承・発展）\n『人は女になる』というボーヴォワールの洞察を受け継ぎ、それをパフォーマティヴィティの理論へ発展させた。"}],"ジジェク":[{"t":"核心","ic":"◈","v":"ラカンの精神分析とヘーゲルの弁証法を用い、映画や大衆文化を素材に現代のイデオロギーを分析した。"},{"t":"本人の言葉","ic":"❝","v":"イデオロギーは、我々が知らずに従っているものだ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ラカンの精神分析とヘーゲルの弁証法を用い、映画や大衆文化を素材に現代のイデオロギーを分析した。人はイデオロギーを見抜いたつもりでも、行動においては従い続けていると指摘し、その無意識の構造を暴いた。"},{"t":"築いた体系","ic":"✦","v":"精神分析・ドイツ観念論・マルクス主義を独自に結びつけ、現代を挑発的に論じる思想家として知られる。その文化・政治批評は、現代思想の大衆的な受容にも大きな影響を与えている。"},{"t":"キーワード","ic":"⚑","v":"イデオロギー批判　人が無意識に従っている社会の枠組みを暴く分析。\nラカン派精神分析　欲望や無意識の構造を、言語との関係から捉える理論。\n大文字の他者　人々のふるまいを規定する、社会の象徴的秩序。"},{"t":"つながり","ic":"→","v":"ヘーゲル（継承し読み替え）\n否定と矛盾の弁証法を、精神分析と結びつけて現代に蘇らせた。"}],"ハイエク":[{"t":"核心","ic":"◈","v":"社会に必要な知識は一人の計画者に集められず、無数の個人に分散していると論じた。"},{"t":"本人の言葉","ic":"❝","v":"社会の知は、無数の個人に分散している。","by":""},{"t":"何を言ったか","ic":"⟲","v":"社会に必要な知識は一人の計画者に集められず、無数の個人に分散していると論じた。だからこそ、価格を通じて情報を伝える市場と、意図せず育った制度(自生的秩序)が、中央計画より優れて機能するとした。"},{"t":"築いた体系","ic":"✦","v":"新自由主義を代表し、計画経済と全体主義を批判した。自生的秩序や知の分散をめぐる議論は、経済学のみならず政治哲学・法思想にも大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"自生的秩序　設計されず、人々の相互作用の中から自然に育つ秩序。\n知識の分散　社会の知は一人に集められず、無数の個人に分かれてあるという考え。\n市場と価格　価格が分散した情報を伝え、社会を調整する仕組み。"},{"t":"つながり","ic":"→","v":"アダム・スミス（継承し発展）\n見えざる手による自生的秩序の発想を受け継ぎ、知識論から基礎づけた。"}],"エーリッヒ・フロム":[{"t":"核心","ic":"◈","v":"近代人は封建的な束縛から自由になった一方、孤独と不安に耐えきれず、権威への服従や画一化へ逃げ込みがちだと分析した(自由からの逃走)。"},{"t":"本人の言葉","ic":"❝","v":"自由は、しばしば重荷となって人を逃避へ向かわせる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"近代人は封建的な束縛から自由になった一方、孤独と不安に耐えきれず、権威への服従や画一化へ逃げ込みがちだと分析した(自由からの逃走)。所有でなく、愛し創造する「あることの様式」に人間の幸福を見た。"},{"t":"築いた体系","ic":"✦","v":"精神分析とマルクス主義を結びつけ、社会と人間の性格の関係を論じた。『自由からの逃走』『愛するということ』などで、現代人の疎外と愛の意味を広く問いかけた。"},{"t":"キーワード","ic":"⚑","v":"自由からの逃走　自由の孤独と不安に耐えられず、服従や画一へ逃げ込む傾向。\n持つことと在ること　所有に生きる様式と、愛し創造して生きる様式の対比。\n愛の技術　愛を、感情でなく学び育てるべき能力・技術として捉える考え。"},{"t":"つながり","ic":"→","v":"マルクーゼ（同学派・同時代）\n精神分析と社会理論を結ぶ批判的社会心理の問題意識を共有した。"}],"孫子":[{"t":"核心","ic":"◈","v":"戦争を、感情や偶然でなく、冷静な状況分析と合理的な計算によって捉えた。"},{"t":"本人の言葉","ic":"❝","v":"彼を知り己を知れば、百戦して危うからず。","by":""},{"t":"何を言ったか","ic":"⟲","v":"戦争を、感情や偶然でなく、冷静な状況分析と合理的な計算によって捉えた。戦わずして勝つことを最善とし、彼我の情勢を正しく知り、変化に応じて柔軟に対応することの大切さを説いた。"},{"t":"築いた体系","ic":"✦","v":"『孫子』十三篇によって兵法を体系化し、東アジアの軍事思想の古典となった。その状況分析と戦略の思想は、軍事を超えて政治・経営・処世の知恵として今も広く読まれている。"},{"t":"キーワード","ic":"⚑","v":"知彼知己　敵と自分の情勢を正しく知れば、負けることはないという教え。\n不戦而勝　戦わずして勝つことを最善とする考え。\n兵は詭道なり　戦いは相手を欺き、変化に応じて動く駆け引きだという見方。"},{"t":"つながり","ic":"→","v":"韓非子（発想が通じる）\n人を動かすものを冷静に計算する現実主義的な人間観で相通じる。"}],"レヴィ=ストロース":[{"t":"核心","ic":"◈","v":"文化人類学者。"},{"t":"本人の言葉","ic":"❝","v":"神話は、人間が意識せぬうちに、人間のうちで考える。","by":""},{"t":"何を言ったか","ic":"⟲","v":"文化人類学者。バラバラに見える神話・親族・慣習の背後に、人間の心に共通する無意識の「構造」があると考えた。個々の要素そのものより、要素どうしの関係の体系こそが意味を生むとし、未開と文明を優劣でなく、別の論理として並べて捉えた。"},{"t":"築いた体系","ic":"✦","v":"言語学（ソシュール）の構造分析を人類学へ応用し、『構造主義』を確立した。親族の体系や神話を、対立する項の組み合わせとして分析。西洋中心の進歩史観を退け、20世紀後半の人文学に大きな転回をもたらした。"},{"t":"キーワード","ic":"⚑","v":"構造　個々の要素そのものより、要素どうしの関係の体系こそが意味を生むとする見方。\n二項対立　自然/文化、生/煮のように、対立する項の組で人間は思考するという考え。\n野生の思考　未開とされる思考も、文明の科学に劣らない、別種の緻密な論理だとする見方。"},{"t":"つながり","ic":"→","v":"サルトル（論争・対立）\n歴史と主体を重んじる実存主義に対し、無意識の構造を対置して論争した。"}],"鈴木大拙":[{"t":"核心","ic":"◈","v":"禅を英語で世界に紹介し、東洋思想を西洋へ橋渡しした仏教学者。"},{"t":"本人の言葉","ic":"❝","v":"禅は、言葉や論理の手前にある、生きた経験そのものを指さす。","by":""},{"t":"何を言ったか","ic":"⟲","v":"禅を英語で世界に紹介し、東洋思想を西洋へ橋渡しした仏教学者。悟り（さとり）を、理屈で説明される教義ではなく、日常のただ中で起こる直接の体験として説いた。二元的な分別を超える『即』の逆説の論理を語った。"},{"t":"築いた体系","ic":"✦","v":"膨大な英文著作で禅を欧米に広め、20世紀の思想・芸術・心理学（ユングら）に影響を与えた。『日本的霊性』を論じ、浄土思想（妙好人）にも光を当てた。学問と実参（じっさんの修行）を両輪とした。"},{"t":"キーワード","ic":"⚑","v":"悟り　分別（二元的な思考）を超えて、実在に直接めざめる禅の体験。\n即非の論理　「AはAでない、ゆえにAである」という、分別を超えた逆説の論理。\n日本的霊性　日本人の宗教意識の深層にある、大地に根ざした霊性のあり方。"},{"t":"つながり","ic":"→","v":"西田幾多郎（盟友・同時代）\n生涯の親友。禅の体験を、西田は哲学の言葉へ、鈴木は世界への紹介へと展開した。"}],"モッラー・サドラー":[{"t":"核心","ic":"◈","v":"サファヴィー朝ペルシアの哲学者。"},{"t":"本人の言葉","ic":"❝","v":"存在は、静止した実体ではなく、絶えず高まりゆく運動である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"サファヴィー朝ペルシアの哲学者。哲学（理性）・神秘主義（直観）・啓示（信仰）を一つに統合する壮大な体系を築いた。本質ではなく『存在』こそが根源的な実在であり、存在は強弱の度合いをもって、たえず上位へと生成すると説いた。"},{"t":"築いた体系","ic":"✦","v":"『四つの旅』などで『超越的叡智（ヒクマ・ムタアーリヤ）』を大成した。イブン・シーナーの哲学、スフラワルディーの照明哲学、イブン・アラビーの神秘思想を総合し、以後のイランの思想に決定的な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"存在の根源性　本質ではなく『存在』こそが実在の根本だとする、彼の哲学の出発点。\n存在の階層　存在は強弱の度合いをもつ、ひとつながりの一なる実在だとする見方。\n実体的運動　実体そのものが静止せず、たえず上位の段階へと生成し続けるという説。"},{"t":"つながり","ic":"→","v":"イブン・シーナー(アヴィセンナ)（継承し乗り越えた）\n存在と本質の議論を受け継ぎつつ、存在の根源性を打ち出して超えた。"}],"ラカン":[{"t":"核心","ic":"◈","v":"フロイトの精神分析を、構造主義の言語論を用いて根本から読み直した。"},{"t":"本人の言葉","ic":"❝","v":"無意識は、言語のように構造化されている。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フロイトの精神分析を、構造主義の言語論を用いて根本から読み直した。無意識は本能の混沌ではなく、言語と同じ規則で構造化されているとし、人間の欲望や主体が、言葉と他者との関係のなかで形づくられると説いた。"},{"t":"築いた体系","ic":"✦","v":"乳児が鏡の像に自分を見いだす『鏡像段階』で自我の成り立ちを、『想像界・象徴界・現実界』の三つの位相で心の構造を捉えた。難解な語りで知られ、20世紀後半の思想・批評・映画論に絶大な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"鏡像段階　乳児が鏡に映る像を自分だと見いだし、まとまった自我を得る発達の段階。\n無意識は言語のように構造化されている　無意識は本能の混沌でなく、言葉の連鎖と同じ規則で働くという考え。\n象徴界　言語と法の秩序。人はここに参入して初めて社会的な主体となる。"},{"t":"つながり","ic":"→","v":"レヴィ=ストロース（影響を受けた）\n無意識を言語のように構造化されたものと捉える発想を、構造主義から得た。"}],"リオタール":[{"t":"核心","ic":"◈","v":"人類の進歩や解放を約束する『大きな物語』が、もはや信じられなくなった状態を『ポストモダン』と名づけた。"},{"t":"本人の言葉","ic":"❝","v":"私はポストモダンを、大きな物語への不信と定義する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"人類の進歩や解放を約束する『大きな物語』が、もはや信じられなくなった状態を『ポストモダン』と名づけた。単一で普遍的な正しさを疑い、多様で断片的な『小さな物語』の共存を重んじた。"},{"t":"築いた体系","ic":"✦","v":"『ポストモダンの条件』で、知識の正しさを支えるものの変化を論じた。共通の尺度では裁けない、異なる立場のあいだの根本的な対立（ディフェラン）に注目した。"},{"t":"キーワード","ic":"⚑","v":"大きな物語　人類全体を導くと称する、進歩・解放・全体的真理といった普遍的な物語。\nポストモダン　大きな物語への信頼が失われた、多様で断片的な時代のあり方。\n言語ゲーム　それぞれ固有の規則をもつ、複数の言葉の営み。単一の尺度に還元できない。"},{"t":"つながり","ic":"→","v":"ヘーゲル（批判した）\n歴史を一つの理性の自己展開として描く発想を、大きな物語として退けた。"}],"ディルタイ":[{"t":"核心","ic":"◈","v":"自然科学とは別に、歴史・文化・人間を扱う『精神科学』の独自の方法を基礎づけた。"},{"t":"本人の言葉","ic":"❝","v":"自然は説明し、精神（人間）は理解する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"自然科学とは別に、歴史・文化・人間を扱う『精神科学』の独自の方法を基礎づけた。自然を外から因果的に『説明』するのに対し、人間の営みは、内側からその意味を追体験して『理解』するのだと説いた。"},{"t":"築いた体系","ic":"✦","v":"『生（レーベン）』を出発点とし、テキストや歴史を解釈する解釈学（ヘルメノイティク）を、人文学の方法へと発展させた。後のハイデガーやガダマーの解釈学に、道を開いた。"},{"t":"キーワード","ic":"⚑","v":"精神科学　歴史・文化・人間を扱う学問。自然科学とは根本的に方法が異なるとされる。\n説明と理解　自然は因果関係で『説明』し、人間の営みは意味を『理解』するという区別。\n追体験　他者の体験を、内側から生き直すようにして、その意味を理解すること。"},{"t":"つながり","ic":"→","v":"ハイデガー（影響を与えた）\n生と歴史の理解の探究が、存在の解釈学へと受け継がれた。"}],"西谷啓治":[{"t":"核心","ic":"◈","v":"京都学派を代表する哲学者。"},{"t":"本人の言葉","ic":"❝","v":"虚無の底を突き抜けたところに、空（くう）がひらける。","by":""},{"t":"何を言ったか","ic":"⟲","v":"京都学派を代表する哲学者。西洋の虚無主義（ニヒリズム）と仏教の『空』を突き合わせ、近代人が陥る虚無を、仏教的な空の立場から突き抜けて乗り越える道を探った。"},{"t":"築いた体系","ic":"✦","v":"西田幾多郎に学び、宗教と哲学、東洋と西洋を架橋した。『宗教とは何か』で、科学的世界観のもとで意味を失った現代人の実存を、空の思想から問い直した。"},{"t":"キーワード","ic":"⚑","v":"空（くう）　実体としての自我も世界も無い、しかし単なる虚無でもない、仏教的な境地。\nニヒリズムの克服　近代の虚無を否定して逃げるのでなく、その底を突き抜けて空に至る道。\n京都学派　西田幾多郎を中心に、東西の思想を統合しようとした日本の哲学運動。"},{"t":"つながり","ic":"→","v":"西田幾多郎（師事し継承）\n西田の哲学を受け継ぎ、宗教と虚無の問題へと深めた。"}],"オーロビンド":[{"t":"核心","ic":"◈","v":"インドの独立運動家から、後に霊性の探求者へと転じた思想家。"},{"t":"本人の言葉","ic":"❝","v":"人間は、進化の最終形ではなく、途上にある存在である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"インドの独立運動家から、後に霊性の探求者へと転じた思想家。宇宙は物質から生命・心へと進化してきたが、その先に神的な『超精神（スーパーマインド）』への進化があると説き、精神と物質を統合する『統合ヨーガ』を唱えた。"},{"t":"築いた体系","ic":"✦","v":"ヴェーダーンタの伝統を、進化論的な世界観と結びつけて刷新した。人類は、より高い神的な意識へと進化する途上にあるとし、彼岸でなく、この地上における霊的な変容を目指した。"},{"t":"キーワード","ic":"⚑","v":"超精神（スーパーマインド）　物質・生命・心の上位にある、宇宙を貫く神的な意識の段階。\n統合ヨーガ　世俗の生を捨てず、物質と精神を一つに統合していく霊的な実践。\n意識の進化　宇宙は物質から生命・心・神的意識へと進化していくとする世界観。"},{"t":"つながり","ic":"→","v":"ヴィヴェーカーナンダ（影響を受けた）\nヴェーダーンタを現代に生かす近代インド精神の流れを受け継いだ。"}],"C.S.パース":[{"t":"核心","ic":"◈","v":"プラグマティズムの創始者であり、記号論（セミオティクス）の父。"},{"t":"本人の言葉","ic":"❝","v":"ある観念の意味は、それが生む実際的な効果のうちにある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"プラグマティズムの創始者であり、記号論（セミオティクス）の父。ある概念の意味は、それを真と認めたときに生じる、実際の行動上・経験上の効果のうちにあると説いた（プラグマティズムの格率）。"},{"t":"築いた体系","ic":"✦","v":"論理学・数学・科学方法論に深く通じ、探究を『アブダクション（仮説形成）→演繹→帰納』の過程として分析した。記号を『イコン・インデックス・シンボル』に分類し、後の記号論・分析哲学に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"プラグマティズムの格率　概念の意味は、それが生む実際的・経験的な効果にあるとする原則。\nアブダクション　観察された事実から、それを最もよく説明する仮説を立てる推論。\n記号論（セミオティクス）　記号とその意味作用の一般理論。記号をイコン・インデックス・シンボルに分類した。"},{"t":"つながり","ic":"→","v":"ウィリアム・ジェイムズ（創始し受け継がれた）\nパースが唱えた格率を、ジェイムズが分かりやすく広め、大衆化した。"}],"マックス・ウェーバー":[{"t":"核心","ic":"◈","v":"近代社会を『合理化』の進展として捉えた社会学者・思想家。"},{"t":"本人の言葉","ic":"❝","v":"世界の脱魔術化（呪術からの解放）が、近代の運命である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"近代社会を『合理化』の進展として捉えた社会学者・思想家。宗教・経済・支配など多方面を、意味を『理解』する方法で分析した。プロテスタントの禁欲的な倫理が、意図せず資本主義の精神を生んだと論じた。"},{"t":"築いた体系","ic":"✦","v":"『プロテスタンティズムの倫理と資本主義の精神』で、思想が経済を動かす面を示した。支配の三類型（伝統的・カリスマ的・合法的）や、価値と事実の峻別など、社会科学の方法を確立した。"},{"t":"キーワード","ic":"⚑","v":"合理化　社会のあらゆる領域が、計算可能で効率的な仕組みへと進んでいく過程。\n脱魔術化　世界から神秘や呪術が失われ、すべてが計算で捉えられるようになること。\n理解社会学　行為者の主観的な意味を『理解』することを通じて社会を捉える方法。"},{"t":"つながり","ic":"→","v":"マルクス（批判的に対峙）\n経済が土台だとする見方に対し、宗教的な観念が経済を動かす面を示した。"}],"ファノン":[{"t":"核心","ic":"◈","v":"カリブ海マルティニーク出身の精神科医・思想家。"},{"t":"本人の言葉","ic":"❝","v":"植民地支配は、被支配者の魂そのものを歪める。","by":""},{"t":"何を言ったか","ic":"⟲","v":"カリブ海マルティニーク出身の精神科医・思想家。植民地支配が、黒人の心に植えつける劣等感と自己疎外を、精神分析と実存主義を用いて鋭くえぐった。抑圧からの解放を、人間性そのものの回復として論じた。"},{"t":"築いた体系","ic":"✦","v":"『黒い皮膚・白い仮面』で人種と自己の疎外を、『地に呪われたる者』で植民地からの解放と暴力の問題を論じた。反植民地闘争と、後のポストコロニアル思想に決定的な影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"黒い皮膚・白い仮面　白人の価値観を内面化させられた黒人が陥る、自己疎外の状態。\n植民地の暴力　支配が生み出す構造的な暴力と、そこからの解放をめぐる問題。\n人種と実存　人種化されたまなざしのもとで身体を生きる、疎外された実存の分析。"},{"t":"つながり","ic":"→","v":"サルトル（影響を受け対話）\n実存主義を植民地状況に適用し、サルトルは『地に呪われたる者』に序文を寄せた。"}],"王弼":[{"t":"核心","ic":"◈","v":"三国時代の中国で、わずか二十三歳で世を去った天才思想家。"},{"t":"本人の言葉","ic":"❝","v":"有（存在するもの）は、すべて無を根本としている。","by":""},{"t":"何を言ったか","ic":"⟲","v":"三国時代の中国で、わずか二十三歳で世を去った天才思想家。『老子』『易経』の画期的な注釈で、道家の『無』を万物の根本原理として捉え直した。儒家と道家を融合する『玄学（げんがく・神秘の学）』を切り開いた。"},{"t":"築いた体系","ic":"✦","v":"『万物は無を本とする（貴無論）』と説き、現象の多様性の背後にある根源的な『無』を思索した。その老子・易経の注釈は、後世の東アジア思想の標準的な読み方となった。"},{"t":"キーワード","ic":"⚑","v":"貴無論　有（存在）は無を根本とし、無こそが万物の本だとする説。\n玄学　老荘思想と易を融合し、現象の奥の根源を探る、魏晋の神秘の学。\n得意忘言　言葉は意味をつかむための道具であり、意味を得たら言葉は忘れてよいという考え。"},{"t":"つながり","ic":"→","v":"老子（注釈し深めた）\n『老子』に画期的な注釈を施し、道を『無』として捉え直した。"}],"董仲舒":[{"t":"核心","ic":"◈","v":"前漢の儒学者で、儒教が中国の国家の学問（国教）となる道を開いた。"},{"t":"本人の言葉","ic":"❝","v":"天と人とは、たがいに感応し合う。","by":""},{"t":"何を言ったか","ic":"⟲","v":"前漢の儒学者で、儒教が中国の国家の学問（国教）となる道を開いた。天と人が互いに影響し合う『天人相関』を説き、君主の徳が乱れれば天が災いで警告する（災異説）とした。陰陽五行説を儒教に取り込み、壮大な宇宙論を築いた。"},{"t":"築いた体系","ic":"✦","v":"武帝に儒学の官学化を進言し、後の科挙と儒教国家の礎を築いた。『春秋繁露』で、天・自然・人間・政治を一つに結ぶ、体系的な世界観を展開した。"},{"t":"キーワード","ic":"⚑","v":"天人相関　天と人とは互いに感応し、影響し合っているという思想。\n災異説　君主の悪政に対して、天が災害や異変によって警告を下すという説。\n天人合一　天の道と人の道が、根本において一つに通じ合っているとする考え。"},{"t":"つながり","ic":"→","v":"孔子（継承し体系化）\n孔子の教えを、天の宇宙論と結びつけて国家の学問へと組み立てた。"}],"デイヴィッドソン":[{"t":"核心","ic":"◈","v":"20世紀後半の分析哲学を代表する哲学者。"},{"t":"本人の言葉","ic":"❝","v":"言葉の意味を知るとは、それが真になる条件を知ることである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀後半の分析哲学を代表する哲学者。言語・行為・心を統一的に論じた。ある文の意味は、それが真であるための条件（真理条件）にあるとし、他者の言葉を理解するには、相手の多くの信念を真だと前提しなければならないと説いた（好意の原理）。"},{"t":"築いた体系","ic":"✦","v":"心的な出来事は物理的な出来事だが、心を物理法則に還元はできないとする『非法則的一元論』を唱えた。行為・理由・因果の関係や、翻訳・解釈の理論など、心の哲学・言語哲学に広く影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"真理条件的意味論　文の意味は、それが真になるための条件のうちにあるとする考え。\n好意の原理　他者の言葉を理解するには、相手の多くの信念を真だと前提する必要がある。\n非法則的一元論　心的な出来事は物理的だが、心そのものは物理法則には還元できない。"},{"t":"つながり","ic":"→","v":"クワイン（師事し継承・批判）\nクワインの翻訳の不確定性を受けつつ、真理条件的な意味論を展開した。"}],"周敦頤":[{"t":"核心","ic":"◈","v":"宋代の儒学（宋学・のちの朱子学）の道を開いた先駆者。"},{"t":"本人の言葉","ic":"❝","v":"無極にして太極。太極が動いて陽を生じ、静にして陰を生ず。","by":""},{"t":"何を言ったか","ic":"⟲","v":"宋代の儒学（宋学・のちの朱子学）の道を開いた先駆者。『太極図説』で、宇宙が根源（太極）から陰陽・五行を経て万物を生み出す過程を、簡潔な図と言葉で示した。儒教に、道家的な壮大な宇宙論を取り込んだ世界像を与えた。"},{"t":"築いた体系","ic":"✦","v":"『太極図説』『通書』により、後の程頤・朱熹らの理気哲学の出発点を築いた。人間は、宇宙の最も正しい気を受けた優れた存在であり、欲を少なくして聖人を目指すべきだと説いた。"},{"t":"キーワード","ic":"⚑","v":"太極　万物を生み出す宇宙の根源。『無極にして太極』と表される。\n陰陽五行　太極から陰陽が分かれ、五行を経て万物が生じるという生成論。\n主静　欲を少なくし、心を静かに保つことを重んじる修養のあり方。"},{"t":"つながり","ic":"→","v":"朱熹（継承し体系化された）\n太極図説が、朱熹によって理気哲学の出発点として重んじられた。"}],"スフラワルディー":[{"t":"核心","ic":"◈","v":"『照明哲学（イシュラーク）』を創始したペルシアの哲学者。"},{"t":"本人の言葉","ic":"❝","v":"実在とは、光である。神は、光の光である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"『照明哲学（イシュラーク）』を創始したペルシアの哲学者。存在の根本を『光』として捉え、最も純粋な光である神（光の光）から、光が強弱の段階をなして流れ出て、世界が成り立つと説いた。理性の論証と、神秘的な直観を結び合わせた。"},{"t":"築いた体系","ic":"✦","v":"アリストテレス的な逍遥学派の論理を批判的に受けつつ、古代ペルシアやプラトンの叡智を取り込み、光の形而上学を築いた。後のモッラー・サドラーら、イランの思想に大きな影響を与えた。若くして処刑された。"},{"t":"キーワード","ic":"⚑","v":"照明哲学（イシュラーク）　実在を『光』として捉え、神秘的な直観を重んじる哲学。\n光の光　最も純粋で根源的な光。すなわち神。すべての光の源。\n光の階層　光が強弱の度合いをなして流れ出て、万物が成り立つという世界像。"},{"t":"つながり","ic":"→","v":"イブン・シーナー(アヴィセンナ)（批判的に継承）\n逍遥学派の論理を受けつつ、存在に代えて『光』を根本に据えた。"}],"ドゥッセル":[{"t":"核心","ic":"◈","v":"ラテンアメリカの『解放の哲学』を代表する哲学者。"},{"t":"本人の言葉","ic":"❝","v":"近代は、他者（周縁）を犠牲にして、自らを中心に立てた。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ラテンアメリカの『解放の哲学』を代表する哲学者。ヨーロッパ中心の近代を、征服と植民地支配によって非ヨーロッパ世界を『他者』として抑圧・排除することで成立した、と批判した。抑圧された者（貧者・周縁）の側から、倫理と歴史を問い直した。"},{"t":"築いた体系","ic":"✦","v":"レヴィナスの『他者』の思想を受けつつ、それをラテンアメリカの被抑圧者の現実へと展開した。『解放の哲学』『解放の倫理』を築き、後の脱植民地（デコロニアル）思想の先駆けとなった。"},{"t":"キーワード","ic":"⚑","v":"解放の哲学　ヨーロッパ中心の哲学を退け、抑圧された者の側から思考する哲学。\n他者　近代によって周縁化され、排除された、貧者・被抑圧者・非ヨーロッパ世界。\n近代性の裏面　近代の輝かしい光の裏にある、征服・植民地支配・搾取という暴力。"},{"t":"つながり","ic":"→","v":"レヴィナス（継承し展開）\n『他者』の倫理を受け、それをラテンアメリカの被抑圧者へと展開した。"}],"九鬼周造":[{"t":"核心","ic":"◈","v":"江戸文化の美意識『いき』を、哲学的に分析した日本の哲学者。"},{"t":"本人の言葉","ic":"❝","v":"「いき」とは、垢抜けして、張りのある、色っぽさである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"江戸文化の美意識『いき』を、哲学的に分析した日本の哲学者。『「いき」の構造』で、いきを『媚態・意気地・諦め』の三つの契機として解き明かした。また、すべては『そうでなくてもよかった』という偶然性の不思議に、深く思索を向けた。"},{"t":"築いた体系","ic":"✦","v":"ヨーロッパで現象学・実存哲学（ハイデガー、ベルクソンら）を学び、それを日本の美意識や、偶然性の問題へと独自に応用した。西洋の厳密な方法で、日本文化の核心を捉えようとした。"},{"t":"キーワード","ic":"⚑","v":"いきの構造　江戸の美意識『いき』を、媚態・意気地・諦めの三契機で分析したもの。\n偶然性　必然でなく、『そうでなくてもよかった』ことが現にある、という不思議。\n媚態　異性への、二元的な緊張をはらんだ、なまめかしさ。いきの土台。"},{"t":"つながり","ic":"→","v":"ハイデガー（師事し離れた）\nハイデガーに学びつつ、偶然性や日本の美意識という独自の道へ進んだ。"}],"ゴルギアス":[{"t":"核心","ic":"◈","v":"言葉の力で人を説得する技術（弁論術）を教えた、古代ギリシアのソフィスト。絶対の真理はないと考えた。"},{"t":"本人の言葉","ic":"❝","v":"何ものも存在しない。存在しても認識できない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"言葉の説得力を教えた代表的なソフィスト。『何ものも存在しない、たとえ存在しても認識できない、認識できても他人に伝えられない』という極端な議論で、絶対的な真理や存在の把握を疑った。弁論術こそが人を動かす最大の力だと説いた。"},{"t":"築いた体系","ic":"✦","v":"自然の真理探究から、人間と言葉の技術へと関心を移したソフィストの潮流を代表する。真理そのものより、言葉がもつ説得の力（ロゴスの力）を重んじ、相対主義的な立場をとった。プラトンは対話篇『ゴルギアス』で彼を批判的に描いた。"},{"t":"キーワード","ic":"⚑","v":"ソフィスト　報酬を取って弁論術や処世術を教えた、古代ギリシアの職業的教師たち。\n弁論術　言葉によって人を説得する技術。ゴルギアスが最大の力とみなしたもの。\n相対主義　絶対の真理はなく、物事は立場や人によって異なるとする見方。"},{"t":"つながり","ic":"→","v":"プロタゴラス（同時代）\nともに相対主義的な立場をとり、真理より人間と言葉の技術を重んじた代表的ソフィスト。"}],"プロクロス":[{"t":"核心","ic":"◈","v":"古代ギリシア哲学の最後の大物のひとり。すべては『一なるもの』から段階的に生まれ、また還っていくと考えた。"},{"t":"本人の言葉","ic":"❝","v":"一なるものから、万物は段階をなして流れ出る。","by":""},{"t":"何を言ったか","ic":"⟲","v":"新プラトン主義を体系的に大成した、古代末期の哲学者。万物は究極の『一者』から段階をなして流れ出（発出）、また源へと還っていくとした。プラトン哲学とギリシアの宗教を統合し、精緻な論理で世界の階層構造を描いた。アテナイのアカデメイアの学頭を務めた。"},{"t":"築いた体系","ic":"✦","v":"プロティノスに始まる新プラトン主義を、幾何学的なまでに整然とした体系へと組み上げた。『神学綱要』では、一者からの発出と還帰の運動を命題の連鎖として論証した。その思想は、偽ディオニュシオスを介して中世キリスト教神学や、後のルネサンス思想に流れ込んだ。"},{"t":"キーワード","ic":"⚑","v":"一者　あらゆる存在と認識を超えた、万物の究極の源。\n発出と還帰　万物が一者から流れ出て、また源へと還っていく循環運動。\n新プラトン主義　プラトン哲学を、一者からの流出として体系化した古代末期の思想。"},{"t":"つながり","ic":"→","v":"プロティノス（批判的に継承）\nプロティノスが開いた一者からの流出の思想を受け継ぎ、より精緻な体系へと組み上げた。"}],"ヒュパティア":[{"t":"核心","ic":"◈","v":"古代アレクサンドリアで数学と哲学を教えた女性学者。新プラトン主義を講じ、宗教対立のなかで悲劇的に殺された。"},{"t":"本人の言葉","ic":"❝","v":"考える権利を留保せよ。誤って考える方が、考えないよりよい。","by":""},{"t":"何を言ったか","ic":"⟲","v":"古代末期のアレクサンドリアで活躍した、数学者・天文学者・新プラトン主義の哲学者。父テオンとともに数学書に注釈を施し、多くの弟子に幾何学と哲学を教えた。理性による探究を重んじたが、当時の宗教的・政治的対立に巻き込まれ、群衆に惨殺された。"},{"t":"築いた体系","ic":"✦","v":"プロティノス以来の新プラトン主義を講じ、数学・天文学と哲学を結びつけて教えた。彼女自身の著作はほとんど残らないが、公開講義で幅広い聴衆に学問を開いた。その死は、古代的な学問と理性が宗教的熱狂に押し流された象徴として、後世に語り継がれた。"},{"t":"キーワード","ic":"⚑","v":"新プラトン主義　一者からの流出として世界を捉える、古代末期の哲学。ヒュパティアが講じた立場。\n数学と哲学　幾何学や天文学の探究を、真理へ至る道として哲学と結びつける姿勢。\n理性の擁護　独断や熱狂ではなく、自ら考えることを重んじる態度。"},{"t":"つながり","ic":"→","v":"プロティノス（影響を受けた）\nプロティノスに始まる流出の哲学を受け継ぎ、アレクサンドリアで講じた。"}],"ピエール・アベラール":[{"t":"核心","ic":"◈","v":"中世フランスの論理学者。『普遍は名前にすぎないのか、実在するのか』という大論争で、鋭い折衷案を出した。弟子エロイーズとの悲恋でも有名。"},{"t":"本人の言葉","ic":"❝","v":"疑うことによって、私たちは探究へと導かれる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"中世盛期の論理学者・神学者。『普遍』が実在するのか名前にすぎないのかをめぐる普遍論争で、普遍は事物でも単なる音声でもなく、心が言葉によって捉える意味だとする概念論を唱えた。疑いと問いを学問の出発点とし、鋭い論理で伝統的権威に切り込んだ。"},{"t":"築いた体系","ic":"✦","v":"『然りと否』では、教父たちの矛盾する言葉を並べ、理性による吟味を通じて調停しようとした。信仰の内容も理解の対象としうるとする姿勢は、後のスコラ学の方法を準備した。弟子エロイーズとの往復書簡と悲恋、たび重なる断罪でも知られる。"},{"t":"キーワード","ic":"⚑","v":"普遍論争　『人間一般』のような普遍が実在するか名前かをめぐる中世の大論争。\n概念論　普遍は実在でも音声でもなく、心が言葉で捉える意味だとする立場。\n疑いと問い　権威をうのみにせず、疑いから探究を始める学問の姿勢。"},{"t":"つながり","ic":"→","v":"アンセルムス（批判的に継承）\n信仰と理性の関係を問う流れを受けつつ、普遍論争ではより論理的・概念論的な立場をとった。"}],"マイスター・エックハルト":[{"t":"核心","ic":"◈","v":"中世ドイツの神秘思想家。魂のいちばん奥で、人は神と一つになれると説いた。理屈を超えた深い一体の体験を語った。"},{"t":"本人の言葉","ic":"❝","v":"神が私を見るその眼は、私が神を見る眼と一つである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"中世ドイツの神学者・神秘思想家。魂の最も深い底（魂の根底）において、人は被造物としての自分を手放し、神とじかに一つになると説いた。神を対象として語るより、あらゆる規定を超えた『神性』へと突き抜ける道を、大胆な言葉で語った。"},{"t":"築いた体系","ic":"✦","v":"ドミニコ会士としてスコラ学に通じつつ、ドイツ語による説教で神秘思想を民衆に語った。自己を無にして神に場所を明け渡す『放下（離脱）』を核とし、魂における『神の子の誕生』を説いた。その大胆な言葉は異端の嫌疑を招いたが、後の神秘主義や近代の思想に深い影響を残した。"},{"t":"キーワード","ic":"⚑","v":"魂の根底　魂の最も奥にある、神とじかに触れ合う場。\n神性　神という規定さえ超えた、あらゆる区別以前の根源。\n放下（離脱）　自己や所有への執着を手放し、心を空にすること。"},{"t":"つながり","ic":"→","v":"トマス・アクィナス（同じ会派・対比）\n同じドミニコ会のスコラ学の伝統に立ちつつ、理性的体系より魂の一体の体験を前面に出した。"}],"マルブランシュ":[{"t":"核心","ic":"◈","v":"デカルトの流れをくむフランスの哲学者。心と物はじかに作用し合えず、すべては神が仲立ちすると考えた（機会原因論）。"},{"t":"本人の言葉","ic":"❝","v":"われわれはすべてのものを神において見る。","by":""},{"t":"何を言ったか","ic":"⟲","v":"デカルト哲学とアウグスティヌスの神学を結びつけた、近代フランスの哲学者・神父。精神と物体はまったく異質で、じかに作用し合えないとし、あらゆる出来事の真の原因は神だとする機会原因論を唱えた。人は事物を、神のうちにある観念を通して認識する（万物を神において見る）とした。"},{"t":"築いた体系","ic":"✦","v":"心身が直接に因果関係をもてないというデカルト二元論の難問を、神を唯一の真の原因とすることで解決しようとした。原因と見えるものは、神が働く『機会（きっかけ）』にすぎない。この徹底した神中心の形而上学は、ライプニッツやヒュームの因果論に刺激を与えた。"},{"t":"キーワード","ic":"⚑","v":"機会原因論　真の原因は神だけで、事物は神が働くきっかけにすぎないとする説。\n神において見る　人は事物を、神のうちの観念を通して認識するとする考え。\n心身問題　異質な心と物がどう関わるかというデカルト以来の難問。"},{"t":"つながり","ic":"→","v":"デカルト（批判的に継承）\nデカルトの心身二元論を受け継ぎつつ、その相互作用の難問を機会原因論で解こうとした。"}],"シャフツベリ":[{"t":"核心","ic":"◈","v":"イギリスの貴族の思想家。人には生まれつき善悪を感じ取る『道徳感覚』が備わっていると考えた。美と道徳を結びつけた。"},{"t":"本人の言葉","ic":"❝","v":"美しいものと善いものは、調和において一つである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"18世紀初頭イギリスの道徳哲学者。人間には理屈以前に善悪や美醜を感じ取る『道徳感覚（モラル・センス）』が生まれつき備わっているとした。徳を、自己愛と社会愛が調和した心の美しさとみなし、道徳を美的な調和として捉えた。"},{"t":"築いた体系","ic":"✦","v":"ホッブズの利己的な人間観に反対し、人には他者への自然な情愛があると説いた。道徳を、感覚と情の調和に根ざすものとする立場は、ハチスンを経てヒュームやアダム・スミスの道徳感情論へと受け継がれ、イギリス道徳哲学の一潮流を形づくった。"},{"t":"キーワード","ic":"⚑","v":"道徳感覚　善悪を理屈以前に感じ取る、生まれつきの心の働き。\n自然な情愛　他者や社会へ自然に向かう、利己心ではない感情。\n徳＝調和　自己愛と社会愛が釣り合った、心の美しい調和としての徳。"},{"t":"つながり","ic":"→","v":"ジョン・ロック（批判的に継承）\nロックに学びつつ、その打算的な人間観に反対し、生得的な道徳感覚を主張した。"}],"トマス・リード":[{"t":"核心","ic":"◈","v":"ヒュームの徹底した懐疑に反対したスコットランドの哲学者。ふつうの人がもつ『常識』の確かさを守ろうとした。"},{"t":"本人の言葉","ic":"❝","v":"常識の原理は、証明を要さず、証明を拒むこともできない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"スコットランド常識学派を代表する哲学者。ヒュームの懐疑論が、心には観念しか現れないとする前提から世界の実在を疑うに至ったのに対し、リードは、外界や自我の存在といった常識の諸原理は証明以前に誰もが認めざるをえない土台だと主張した。"},{"t":"築いた体系","ic":"✦","v":"ロックやヒュームが前提した『観念の説』（心は観念のみを直接知る）を退け、知覚は観念を介さず直接に事物を捉えるとした。人間の心に共通する『常識（コモン・センス）』の原理を哲学の基礎に据える立場は、後の実在論やアメリカ思想に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"常識の原理　証明ぬきに誰もが認めざるをえない、思考の土台となる確信。\n観念の説批判　心は観念だけを直接知るという前提を退ける立場。\n直接的知覚　知覚は観念を介さず、じかに外界の事物を捉えるとする考え。"},{"t":"つながり","ic":"→","v":"デイヴィッド・ヒューム（対立）\nヒュームの懐疑論を、観念の説という誤った前提に由来するものとして批判し、常識から反論した。"}],"コンドルセ":[{"t":"核心","ic":"◈","v":"フランス啓蒙の数学者・思想家。人類は理性と教育によって限りなく進歩できると信じた。革命の混乱のなかで獄死した。"},{"t":"本人の言葉","ic":"❝","v":"人類の完成には、いかなる限界も定められていない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランス啓蒙末期の数学者・政治思想家。人類の歴史は理性と知識の増大によって進歩し続けるとし、その未来を楽観的に描いた。公教育の整備、女性や黒人の権利、多数決の数学的分析など、平等と理性にもとづく社会改革を構想した。"},{"t":"築いた体系","ic":"✦","v":"進歩を歴史の法則として捉え、迷信や専制からの解放を教育と科学に託した。投票と多数決を確率論で分析した『コンドルセの陪審定理』でも知られる。フランス革命に関わったが、恐怖政治のなかで追われ、逃亡の末に獄中で命を落とした。"},{"t":"キーワード","ic":"⚑","v":"進歩史観　人類は理性と知識により限りなく前進するとする歴史観。\n公教育　理性を万人に開き、偏見から解放するための教育の整備。\n権利の平等　身分・性別・人種を超えて権利を等しく認める理念。"},{"t":"つながり","ic":"→","v":"ヴォルテール（影響を受けた）\n理性による迷信と専制の批判という啓蒙の精神を受け継ぎ、進歩の思想へと展開した。"}],"ドルバック":[{"t":"核心","ic":"◈","v":"フランス啓蒙の急進的な思想家。世界は物質と運動だけでできており、神や霊魂は要らないと説いた徹底した唯物論者。"},{"t":"本人の言葉","ic":"❝","v":"人間は自然の作品であり、自然のうちに存在する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランス啓蒙を代表する唯物論者・無神論者。『自然の体系』で、宇宙は物質とその運動だけから成り、いっさいは因果の必然に従うと説いた。神・霊魂・自由意志を幻想として退け、道徳も人間の幸福と社会的な利害から説明できるとした。"},{"t":"築いた体系","ic":"✦","v":"デカルト以来の機械論を徹底し、精神現象も物質の運動に還元する一元的な唯物論を展開した。自邸のサロンにディドロら百科全書派を集め、宗教批判の拠点とした。その決定論的で反宗教的な自然観は、近代の科学的世界観と世俗的な倫理を先取りした。"},{"t":"キーワード","ic":"⚑","v":"唯物論　世界は物質とその運動だけから成るとする立場。\n決定論　いっさいの出来事は因果の必然に従うとする考え。\n無神論　神の存在を認めず、宗教を人間が作った幻想とみなす立場。"},{"t":"つながり","ic":"→","v":"ディドロ（盟友）\n百科全書派の中心としてサロンをともにし、唯物論的で反宗教的な思想を共有した。"}],"シュライアマハー":[{"t":"核心","ic":"◈","v":"近代ドイツの神学者・哲学者。宗教の核心は教義や道徳ではなく、無限なものに触れる『感情』だと説いた。近代神学と解釈学の父。"},{"t":"本人の言葉","ic":"❝","v":"宗教の本質は、無限なものへの直観と感情である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"『近代神学の父』と呼ばれるドイツの神学者・哲学者。宗教の本質を、教義や道徳ではなく、無限なもの・宇宙全体への直観と感情、とりわけ『絶対依存の感情』に見いだした。また、テキストを著者の心に即して理解する解釈学を、一般的な方法として基礎づけた。"},{"t":"築いた体系","ic":"✦","v":"啓蒙による宗教批判とロマン主義のただ中で、宗教を知識や倫理に還元せず、独自の感情の領域として擁護した。文法的解釈と心理的解釈を組み合わせるその解釈学は、ディルタイに受け継がれ、近代解釈学の出発点となった。プラトンの独訳者としても知られる。"},{"t":"キーワード","ic":"⚑","v":"絶対依存の感情　自分が無限なものにすべてを負っているという、宗教の核心の感情。\n宗教＝直観と感情　宗教を教義や道徳でなく、無限なものへの感じ取りとする見方。\n解釈学　テキストを著者の心に即して理解する技法・理論。"},{"t":"つながり","ic":"→","v":"カント（批判的に継承）\n宗教を道徳に還元するカント的な立場を超え、感情としての宗教の独自性を主張した。"}],"ハーバート・スペンサー":[{"t":"核心","ic":"◈","v":"進化の考えを社会にまで広げたイギリスの思想家。宇宙も生物も社会も、単純から複雑へと進化していくと考えた。"},{"t":"本人の言葉","ic":"❝","v":"最適者生存。","by":""},{"t":"何を言ったか","ic":"⟲","v":"進化の観念を宇宙・生物・社会・道徳にまで及ぼした、19世紀イギリスの哲学者・社会学者。あらゆるものは単純で未分化な状態から、複雑で分化した状態へと進化すると説いた。『最適者生存』の語を作り、社会の進歩も自由な競争による適応の過程として捉えた（社会進化論）。"},{"t":"築いた体系","ic":"✦","v":"ダーウィンとは独立に進化の思想を抱き、それを『総合哲学体系』として全分野に適用した。個人の自由を重んじ、国家の介入を最小限にすべきだとする自由放任を唱えた。その社会進化論は当時絶大な影響力をもったが、後に強者の支配を正当化するとして厳しく批判された。"},{"t":"キーワード","ic":"⚑","v":"社会進化論　社会も生物のように、競争と適応を通じて進化するとする考え。\n最適者生存　環境に最も適したものが生き残るとする原理。\n総合哲学　進化の原理をあらゆる分野に適用する統一的な体系。"},{"t":"つながり","ic":"→","v":"オーギュスト・コント（批判的に継承）\n社会を科学的に捉える流れを受けつつ、進化の原理による独自の総合哲学を築いた。"}],"ジンメル":[{"t":"核心","ic":"◈","v":"人と人との関わり方そのものに注目したドイツの社会学者・哲学者。お金や都市が人の心をどう変えるかを鋭く分析した。"},{"t":"本人の言葉","ic":"❝","v":"社会とは、諸個人のあいだの相互作用の総体である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"社会学の草創期を代表するドイツの哲学者・社会学者。社会を固定した実体ではなく、諸個人が結びつき合う『相互作用』の網として捉えた。貨幣が人間関係や価値観をどう変えるか、大都市が人の心をどう形づくるかなど、近代生活の細部を独創的に分析した。"},{"t":"築いた体系","ic":"✦","v":"内容（利害や目的）から独立した、結びつきそのものの『形式』を取り出す形式社会学を構想した。『貨幣の哲学』では、貨幣が事物を等質化し、人間関係を非人格的にする過程を描いた。その断章的で鋭い文明批評は、ルカーチやベンヤミンら次の世代に深い影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"相互作用　人と人が互いに働きかけ合うこと。社会の本体とされる。\n形式社会学　結びつきの中身でなく、その形そのものを取り出す社会学。\n貨幣の哲学　貨幣が価値や人間関係を変えていく過程の分析。"},{"t":"つながり","ic":"→","v":"マックス・ウェーバー（同時代）\nドイツ社会学の草創期をともに担い、近代社会の合理化・非人格化を別の角度から分析した。"}],"カッシーラー":[{"t":"核心","ic":"◈","v":"人間を『シンボル（象徴）を使う動物』と定義したドイツの哲学者。言語・神話・科学など、意味を作り出す働きを幅広く探った。"},{"t":"本人の言葉","ic":"❝","v":"人間は、シンボルを操る動物である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"新カント派の流れをくむドイツの哲学者。人間を、言語・神話・芸術・宗教・科学といった『象徴形式』を通して世界を作り上げる『シンボルを操る動物』と規定した。カントが理性の形式を問うたのを受け継ぎ、文化のあらゆる領域を、意味を形づくる形式として体系的に探究した。"},{"t":"築いた体系","ic":"✦","v":"主著『象徴形式の哲学』で、神話・言語・科学的認識を、それぞれ独自の仕方で世界を秩序づける象徴の体系として分析した。人間の本質を理性ではなく、シンボルによる意味の創造に見る点に独自性がある。1929年のダヴォス討論では、ハイデガーと人間理解をめぐって対峙したことでも知られる。"},{"t":"キーワード","ic":"⚑","v":"象徴形式　言語・神話・科学など、世界に意味と秩序を与える形式。\nシンボルを操る動物　人間を、記号を通じて意味を作る存在と捉える定義。\n文化の哲学　文化のあらゆる領域を、意味の形式として探究する立場。"},{"t":"つながり","ic":"→","v":"カント（批判的に継承）\n認識を形式から捉えるカントを受け継ぎ、その形式論を文化の全領域へと拡張した。"}],"マックス・シェーラー":[{"t":"核心","ic":"◈","v":"『価値』や『感情』を現象学で深く探ったドイツの哲学者。人は理屈より先に、心で価値を感じ取ると考えた。"},{"t":"本人の言葉","ic":"❝","v":"愛は、価値のより高いものへと向かう運動である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フッサールの現象学を、価値・感情・人格・宗教の領域へと展開したドイツの哲学者。カントの形式的な義務倫理に対し、心が直接に感じ取る客観的な『価値』に道徳の基礎を置く実質的価値倫理学を唱えた。共感や愛の分析、哲学的人間学の創始でも知られる。"},{"t":"築いた体系","ic":"✦","v":"価値には、快適・生命・精神・聖なるものといった高低の秩序があり、人はそれを感情（価値感得）を通じて捉えるとした。晩年には、人間を宇宙のなかに位置づける哲学的人間学を構想し、また知識のあり方を社会から捉える知識社会学の先駆ともなった。"},{"t":"キーワード","ic":"⚑","v":"実質的価値倫理学　形式でなく、具体的な価値の高低に道徳を基づける倫理学。\n価値の階層　快適・生命・精神・聖なるものという価値の高低の秩序。\n価値感得　理屈でなく感情によって価値を直接に捉える働き。"},{"t":"つながり","ic":"→","v":"フッサール（批判的に継承）\nフッサールの現象学の方法を受け継ぎつつ、それを価値・感情・人格の領域へと展開した。"}],"ルカーチ":[{"t":"核心","ic":"◈","v":"マルクス主義を哲学的に深めたハンガリーの思想家。資本主義のもとで人間関係が『物』のように見えてしまう仕組みを分析した。"},{"t":"本人の言葉","ic":"❝","v":"物象化とは、人と人との関係が物と物との関係に見えることである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀を代表する西欧マルクス主義の哲学者・文芸批評家。主著『歴史と階級意識』で、資本主義のもとでは人と人との関係が物と物との関係のように現れる『物象化』が社会全体を覆うと論じた。ヘーゲルの弁証法を復権させ、マルクス主義に人間的・哲学的な深みを与えた。"},{"t":"築いた体系","ic":"✦","v":"経済決定論的に硬直したマルクス主義に対し、主体である労働者階級が自らの状況を自覚する『階級意識』の役割を強調した。全体性の観点や物象化論は、フランクフルト学派をはじめ後の批判理論に大きな影響を与えた。文学論ではリアリズムを擁護した。"},{"t":"キーワード","ic":"⚑","v":"物象化　人と人の関係が、物と物の関係のように見えてしまう現象。\n階級意識　労働者が自らの立場と歴史的役割を自覚すること。\n全体性　部分でなく社会全体の連関から物事を捉える視点。"},{"t":"つながり","ic":"→","v":"マルクス（批判的に継承）\nマルクスの商品分析を受け継ぎ、物象化論として社会全体の分析へと拡張した。"}],"グラムシ":[{"t":"核心","ic":"◈","v":"『支配は暴力だけでなく、人々の同意によっても保たれる』と見抜いたイタリアの思想家。獄中で思索を書き続けた。"},{"t":"本人の言葉","ic":"❝","v":"理性の悲観、意志の楽観。","by":""},{"t":"何を言ったか","ic":"⟲","v":"イタリアの政治思想家・共産党の指導者。支配が、暴力や強制だけでなく、被支配者自身の同意を取りつける文化的な指導力『ヘゲモニー』によって保たれると論じた。ファシズム政権に投獄され、獄中の『ノート』に、後世に大きな影響を残す思索を書きつづった。"},{"t":"築いた体系","ic":"✦","v":"なぜ先進国で革命が起きないのかを問い、経済の土台だけでなく、学校・教会・メディアといった市民社会が支配の同意を作り出すと分析した。知識人の役割や『陣地戦』の戦略を論じ、文化とイデオロギーを重視するその思想は、後の文化研究や左派の理論に広く受け継がれた。"},{"t":"キーワード","ic":"⚑","v":"ヘゲモニー　強制でなく同意によって保たれる、文化的・道徳的な指導力。\n市民社会　学校・教会・メディアなど、同意が形づくられる領域。\n有機的知識人　民衆の中から生まれ、その立場を代弁する知識人。"},{"t":"つながり","ic":"→","v":"マルクス（批判的に継承）\n経済の土台を重んじるマルクス主義を、文化と同意の次元へと拡張してヘゲモニー論を築いた。"}],"ホルクハイマー":[{"t":"核心","ic":"◈","v":"フランクフルト学派の中心人物。人間を解放するはずの『理性』が、いつのまにか支配の道具になってしまった、と批判した。"},{"t":"本人の言葉","ic":"❝","v":"理性は、自らを道具へとおとしめてしまった。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランクフルト学派（批判理論）を率いたドイツの哲学者。既存の社会を丸ごと問い直す『批判理論』を掲げ、アドルノと共著した『啓蒙の弁証法』で、人間を迷信から解放するはずの理性が、自然や人間を支配する道具的理性へと転落した過程を分析した。"},{"t":"築いた体系","ic":"✦","v":"社会研究所の所長として、哲学・社会学・心理学・経済学を横断する学際的な社会批判を組織した。特定の党派や体制を前提にせず、現にある社会の全体を批判的に照らし出す点に『批判理論』の特徴がある。後期には、この理性への悲観を深めていった。"},{"t":"キーワード","ic":"⚑","v":"批判理論　現にある社会全体を根本から問い直す、解放をめざす理論。\n道具的理性　目的の吟味を忘れ、手段の効率だけを計る理性のあり方。\n啓蒙の弁証法　解放をめざす理性が支配へ転じてしまう逆説。"},{"t":"つながり","ic":"→","v":"アドルノ（盟友・共著）\n『啓蒙の弁証法』を共に著し、フランクフルト学派の批判理論を二人で築き上げた。"}],"アルチュセール":[{"t":"核心","ic":"◈","v":"マルクスを構造主義の目で読み直したフランスの哲学者。人は社会の仕組み（イデオロギー）によって、知らぬ間に『主体』に作られると考えた。"},{"t":"本人の言葉","ic":"❝","v":"イデオロギーは、個人を主体として呼びかける。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀フランスの構造主義的マルクス主義の哲学者。若きマルクスと成熟したマルクスの間に理論的な断絶（認識論的切断）を見て、後期を科学とみなした。人間を歴史の主人公とする人間主義を退け、個人は学校や家族などの装置を通じてイデオロギーに『主体』として呼びかけられ、作られると論じた。"},{"t":"築いた体系","ic":"✦","v":"社会を、経済・政治・イデオロギーが相対的に自律しつつ絡み合う構造として捉えた。国家権力を支える『イデオロギー装置』の分析は、権力と主体をめぐるその後の思想に大きな影響を与えた。弟子にはフーコーやデリダらがいる。"},{"t":"キーワード","ic":"⚑","v":"認識論的切断　若いマルクスと後期マルクスの間の理論的な断絶。\nイデオロギー装置　学校・家族・メディアなど、支配を支える制度。\n呼びかけ　イデオロギーが個人を『主体』として名指し作り出す働き。"},{"t":"つながり","ic":"→","v":"マルクス（批判的に継承）\nマルクスを構造主義の視点から読み直し、後期の著作に科学としての史的唯物論を見た。"}],"イザヤ・バーリン":[{"t":"核心","ic":"◈","v":"『自由』には二つの意味があると整理したイギリスの思想家。人の価値観は一つに統一できず、多様なままだと考えた（価値多元論）。"},{"t":"本人の言葉","ic":"❝","v":"人間性という曲がった木材から、まっすぐなものが作られたためしはない。","by":"カントの一節。バーリンが繰り返し引いた"},{"t":"転回","ic":"⟲","v":"どちらも大切に見えます。だが彼は、後者に危険が潜むと警告しました。真の自分という観念が入ると、誰かがこう言えるようになるからです——あなたが今望んでいることは、本当のあなたの望みではない。私はあなたの真の意志を知っている。だからあなたを強制することは、あなたを自由にすることだ、と。二十世紀の抑圧は、しばしばこの論法を使いました。"},{"t":"生の事実","ic":"✦","v":"七歳で、彼は群衆が人を引きずるのを見た——1917年、ロシア革命下のペトログラード。少年バーリンは、警官が群衆に捕まり、引きずられていく光景を目撃します。"},{"t":"最も強い反論","ic":"⚡","v":"彼の価値多元論には、実践的な弱点が指摘されます。価値が比較不能なら、対立する主張のどちらを選ぶべきかを、彼の理論は何も教えてくれない。結局は各人の直感に委ねられ、それは強い者の直感が通る状況を追認しかねない。加えて、彼は生前、公職や社交を好み、体制の内側にいる知識人でした。冷戦期には、その自由論が西側のイデオロギーとして機能した面も否定できません。"},{"t":"あなたへ","ic":"→","v":"あなたが今抱えている選択で、どちらを選んでも何かを失うものはありますか。失うものの名前を、はっきり言えますか。"}],"ギルバート・ライル":[{"t":"核心","ic":"◈","v":"『心は体の中にひそむ幽霊のようなものではない』と論じたイギリスの哲学者。心をめぐる言葉の使い方の混乱を解きほぐした。"},{"t":"本人の言葉","ic":"❝","v":"心とは、機械のなかの幽霊ではない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"日常言語学派を代表するイギリスの哲学者。デカルト以来の、心を身体とは別の内なる実体とみなす見方を『機械のなかの幽霊』と呼んで批判した。心的な言葉は、隠れた内部の出来事を指すのではなく、人のふるまいの傾向や仕方を表すのだと論じた。"},{"t":"築いた体系","ic":"✦","v":"哲学の混乱の多くは、言葉の文法を取り違える『カテゴリー錯誤』から生じるとした。主著『心の概念』で、知性や意志を内なる原因とみなす発想を解体し、心を行動の傾向として捉える見方を示した。この論理的行動主義は、後の心の哲学の出発点となった。"},{"t":"キーワード","ic":"⚑","v":"機械のなかの幽霊　心を身体に宿る別の実体とみなす見方への皮肉。\nカテゴリー錯誤　言葉の種類・文法を取り違えることから生じる混乱。\n論理的行動主義　心的な語を、ふるまいの傾向として捉える立場。"},{"t":"つながり","ic":"→","v":"デカルト（対立）\nデカルト由来の心身二元論を『機械のなかの幽霊』と呼び、その解体を試みた。"}],"トマス・ネーゲル":[{"t":"核心","ic":"◈","v":"『コウモリになるとはどんな感じか』という問いで有名なアメリカの哲学者。心の主観的な体験は、科学だけでは捉えきれないと論じた。"},{"t":"本人の言葉","ic":"❝","v":"コウモリであるとは、どのようなことか。","by":""},{"t":"何を言ったか","ic":"⟲","v":"現代アメリカを代表する分析哲学者。論文『コウモリであるとはどのようなことか』で、意識には当人だけが生きる主観的な『どのようなことか』という側面があり、それは物理的・客観的な説明には汲み尽くせないと論じ、心の哲学に難問を突きつけた。倫理や政治哲学でも幅広く活躍する。"},{"t":"築いた体系","ic":"✦","v":"世界を『どこでもない場所からの眺め』のように客観的に捉える科学的視点と、当人の主観的な視点との緊張を、一貫した主題とした。主観を消し去らずに客観と両立させる道を探り、還元主義的な唯物論に批判的な立場をとった。倫理学では利他性の合理的根拠を論じた。"},{"t":"キーワード","ic":"⚑","v":"コウモリであるとは　意識に固有の、当人だけが生きる主観的なあり方。\n主観的経験　本人にしか生きられない『どのようなことか』という感じ。\nどこでもない場所からの眺め　主観を離れた、客観的で中立な世界の見方。"},{"t":"つながり","ic":"→","v":"デカルト（批判的に継承）\n心の主観性を消せないとする点で、心身をめぐるデカルト以来の問題を現代に受け継いだ。"}],"張載":[{"t":"核心","ic":"◈","v":"北宋の儒学者。世界は『気』というエネルギーで満ちており、人も物もみな同じ気の仲間だと考えた。宋学の先駆者の一人。"},{"t":"本人の言葉","ic":"❝","v":"民は我が同胞、万物は我が友なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"北宋の儒学者で、宋学（道学）の礎を築いた一人。宇宙の根源を『気』とし、万物はこの一つの気が集まり散じることで生まれては消えると説いた。『西銘』では、天地を父母とし人類みなを同胞とみなす壮大な万物一体の倫理を示した。"},{"t":"築いた体系","ic":"✦","v":"気の集散によって世界の生成変化を説明する気の一元論を立て、後の朱熹の理気論に重要な素材を与えた。『正蒙』などでその思想を展開し、太虚（気の根源的なひろがり）を論じた。程氏兄弟とも交流し、北宋五子の一人に数えられる。"},{"t":"キーワード","ic":"⚑","v":"気　万物を形づくり、集まり散じて生成変化を生む根源のエネルギー。\n太虚　気の根源的なひろがり。形はないが気に満ちた状態。\n万物一体　天地を父母とし、人も物もみな一つのつながりとみる倫理。"},{"t":"つながり","ic":"→","v":"周敦頤（同時代）\nともに北宋に宋学（道学）の基礎を築いた五子の一人として、宇宙論的な儒学を切り開いた。"}],"程頤":[{"t":"核心","ic":"◈","v":"北宋の儒学者。あらゆる物や人には、そうあるべき『理（ことわり）』が備わっていると考えた。この考えを朱熹が受け継ぎ、朱子学になった。"},{"t":"本人の言葉","ic":"❝","v":"性は即ち理なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"兄の程顥とともに宋学を大成へ導いた北宋の儒学者。あらゆる事物や人の本性には、そうあるべき普遍の『理』が宿るとし、『性即理』を唱えた。理を窮め（窮理）、私欲を抑えてつつしみ深く心を保つ（居敬）修養を説いた。その学は朱熹に受け継がれ、程朱学（朱子学）の中核となった。"},{"t":"築いた体系","ic":"✦","v":"万物に内在する理と、それを担う気とを区別して論じ、後の朱熹の理気二元論の枠組みを準備した。事物にあたってその理を一つ一つ究める『格物窮理』を学問の方法とし、道徳的な修養と知の探究を結びつけた。兄程顥のより一体的な思想とは対照をなす。"},{"t":"キーワード","ic":"⚑","v":"性即理　人の本性は、そのまま普遍の理であるとする考え。\n窮理　事物に宿る理を一つ一つ究めていくこと。\n居敬　私欲を抑え、つつしみ深く心を保つ修養のあり方。"},{"t":"つながり","ic":"→","v":"朱熹（影響を与えた）\n理と性をめぐる思想は朱熹に受け継がれ、程朱学（朱子学）の中核として体系化された。"}],"中江兆民":[{"t":"核心","ic":"◈","v":"『東洋のルソー』と呼ばれた明治の思想家。ルソーの思想を日本に伝え、国民の権利と自由を説いた。民主主義の先駆者。"},{"t":"本人の言葉","ic":"❝","v":"我が日本、古より今に至るまで哲学なし。","by":""},{"t":"何を言ったか","ic":"⟲","v":"明治期日本の自由民権運動を思想的に導いた哲学者・政治家。ルソーの『社会契約論』を漢文に訳し、人民主権と自由・平等の思想を広めたことから『東洋のルソー』と称される。唯物論的な立場から宗教や霊魂を退け、生きているうちの自由と権利を重んじた。"},{"t":"築いた体系","ic":"✦","v":"フランス流の民権思想と唯物論を、東洋の古典的教養と結びつけて論じた。『三酔人経綸問答』では、理想と現実の異なる立場を対話させ、日本の進むべき道を問うた。西洋哲学の受容がうわべにとどまることを批判し、根づいた思想の必要を訴えた。"},{"t":"キーワード","ic":"⚑","v":"東洋のルソー　ルソーを日本に伝え、人民の権利を説いた兆民の異名。\n人民主権　国の主権は人民にあるとする、自由民権運動の理念。\n唯物論　霊魂や来世を認めず、物質と現世を根本とする立場。"},{"t":"つながり","ic":"→","v":"ルソー（影響を受けた）\nルソーの社会契約論を漢訳して日本に紹介し、人民主権の思想を広めた。"}],"田辺元":[{"t":"核心","ic":"◈","v":"西田幾多郎に続く京都学派の哲学者。戦争への反省から、自らの無力を認めて懺悔することから哲学をやり直そうとした。"},{"t":"本人の言葉","ic":"❝","v":"哲学は、懺悔（ざんげ）を通してよみがえる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"京都学派を代表する哲学者で、西田幾多郎の後継者。西田の哲学を批判的に受け継ぎ、個・種（民族・社会）・類（人類）の関係を論じる『種の論理』を展開した。敗戦後は、自らの思想の挫折を見つめ、懺悔を通して哲学を立て直す『懺悔道としての哲学』を説いた。"},{"t":"築いた体系","ic":"✦","v":"西田の『場所』の哲学に対し、より媒介と弁証法を重んじる立場をとった。絶対的な力の前で自己の無力を認め、その否定を通して新たに生かされる『懺悔道』は、他力の宗教思想と哲学を結ぶ試みであった。科学哲学から宗教哲学まで、その関心は広い。"},{"t":"キーワード","ic":"⚑","v":"種の論理　個人・種（社会民族）・人類の三者の関係を論じる論理。\n懺悔道　自らの無力と過ちを認め、その否定を通して生き直す道。\n絶対媒介　対立するものを媒介を通して結ぶ、弁証法的な思考。"},{"t":"つながり","ic":"→","v":"西田幾多郎（批判的に継承）\n西田の哲学を受け継ぎつつ、その直観的立場を批判し、媒介と弁証法を重んじる種の論理を展開した。"}],"タゴール":[{"t":"核心","ic":"◈","v":"詩でアジア初のノーベル賞を受けたインドの詩人・思想家。人と自然と神の調和を歌い、自由な教育や東西の対話を説いた。"},{"t":"本人の言葉","ic":"❝","v":"心に恐れがなく、頭が高く掲げられるところ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"インドの詩人・思想家・教育者で、詩集『ギタンジャリ』によりアジアで初めてノーベル文学賞を受けた。人間と自然、有限な人と無限なる神との、愛による調和を歌い上げた。狭い国家主義を超えた普遍的な人間性を説き、東西文化の対話と、自由でのびやかな教育を実践した。"},{"t":"築いた体系","ic":"✦","v":"ウパニシャッドの伝統を近代に生かし、神を遠い彼方でなく、人と自然のうちに宿る愛のはたらきとして捉えた。偏狭なナショナリズムを批判し、人類の普遍的な結びつきを重んじた。国際的な学び舎ビシュババラティ大学を創設し、詩・音楽・教育を通じて思想を体現した。"},{"t":"キーワード","ic":"⚑","v":"有限と無限の調和　有限な人間と無限なる神とが、愛によって結ばれること。\n普遍的人間性　国や民族の壁を超えた、人類に共通する人間らしさ。\nナショナリズム批判　狭い国家主義を、人を分断するものとして退ける立場。"},{"t":"つながり","ic":"→","v":"ガンディー（同時代・論争）\n独立をめざす同志として深い友情を結びつつ、ナショナリズムや近代文明のあり方をめぐって真摯に論じ合った。"}],"クリシュナムルティ":[{"t":"核心","ic":"◈","v":"『真理に決まった道はない』と説いたインドの思想家。あらゆる宗教や組織、権威に頼らず、自分の心を自分で見つめよと語り続けた。"},{"t":"本人の言葉","ic":"❝","v":"真理は、道なき大地である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀インドの思想家・宗教的教師。若くしてある教団から『来るべき世界教師』とされたが、後にそれを自ら解体し、いかなる組織・教義・権威も真理への道にはならないと宣言した。以後、世界中で対話を重ね、自分の心をありのままに観察することによる、思考からの自由を説いた。"},{"t":"築いた体系","ic":"✦","v":"特定の宗教にも哲学体系にも属さず、既成の権威や信念、時間をかけた修行という考えそのものを疑った。恐れや葛藤の根を、思考が作る自我のうちに見て、その働きを注意深く観察することで、いまここでの根本的な変容が起こりうるとした。"},{"t":"キーワード","ic":"⚑","v":"道なき真理　真理には決まった道や方法はないとする根本の主張。\n権威の否定　宗教・教団・教義など、外の権威に頼ることの拒否。\nあるがままの観察　心の動きを判断せず、ありのままに見つめること。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（響き合う）\n決まった教義に頼らず、自らの心を観察して執着から自由になる点で、仏教の精神と深く響き合う。"}],"ルーミー":[{"t":"核心","ic":"◈","v":"イスラーム神秘主義（スーフィズム）を代表するペルシアの詩人。神への愛を美しい詩で歌い、旋回する舞の教団を生んだ。"},{"t":"本人の言葉","ic":"❝","v":"葦笛の嘆きを聞け。それは別離を語っている。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ペルシア語で書いた、イスラーム神秘主義（スーフィズム）を代表する詩人・思想家。壮大な詩『精神的マスナヴィー』で、魂が根源である神から引き離された嘆きと、愛を通して神へ還り一つになる道を歌った。旋回舞踊で知られるメヴレヴィー教団の源となった。"},{"t":"築いた体系","ic":"✦","v":"理知的な神学よりも、愛と陶酔による神との合一を重んじるスーフィズムの伝統に立つ。師シャムスとの出会いを転機に、燃えるような愛の詩を生み出した。宗派や身分を超えた普遍的な愛を説き、その詩は時代と地域を超えて世界中で読み継がれている。"},{"t":"キーワード","ic":"⚑","v":"スーフィズム　愛と修行を通して神との合一を求める、イスラームの神秘主義。\n神への愛　魂を神へと引き寄せ、合一へ導く燃えるような愛。\n別離と帰還　根源から引き離された魂が、神へと還っていく道。"},{"t":"つながり","ic":"→","v":"イブン・アラビー（同時代）\nともに13世紀のイスラーム神秘主義を代表し、神と世界、愛と合一をめぐる思想を分かち合った。"}],"ユダ・ハレヴィ":[{"t":"核心","ic":"◈","v":"中世スペインのユダヤ人詩人・思想家。哲学の理屈よりも、生きた信仰と歴史のなかの神との結びつきを大切にした。"},{"t":"本人の言葉","ic":"❝","v":"我が心は東にあり、我が身は西の果てにある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"中世スペイン（アンダルス）のユダヤ人詩人・哲学者。名高い対話篇『クザーリ』で、アリストテレス哲学の抽象的な神に対し、歴史のなかでイスラエルの民に語りかけ導いてきた、生きた信仰の神を対置した。祖国シオンへの熱い思いを歌った詩人としても知られる。"},{"t":"築いた体系","ic":"✦","v":"理性による哲学が到達する非人格的な第一原因よりも、預言と啓示という直接の体験にこそ、神の真の認識があるとした。哲学の限界を説きつつ、ユダヤの民と土地、歴史の特別な役割を強調した。その立場は、ギリシア哲学に傾く同時代の思潮への批判でもあった。"},{"t":"キーワード","ic":"⚑","v":"生きた信仰の神　歴史のなかで民に語りかけ導く、人格をもつ神。\n哲学の限界　理性が神の真の認識には届かないとする考え。\n預言と啓示　神が直接に語りかける、信仰の特別な経験。"},{"t":"つながり","ic":"→","v":"マイモニデス（対比）\n同じ中世スペインのユダヤ思想家だが、哲学と信仰の総合を目指したマイモニデスとは対照的に、哲学の限界と信仰の独自性を強調した。"}],"ルクレティウス":[{"t":"核心","ic":"◈","v":"エピクロスの哲学を美しい詩でうたった古代ローマの詩人。世界は原子でできており、死を恐れる必要はないと説いた。"},{"t":"本人の言葉","ic":"❝","v":"何ものも無からは生じない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"古代ローマの詩人・哲学者。長編詩『物の本性について』で、エピクロスの原子論を格調高くうたい上げた。万物は原子とそのあいだの空虚から成り、神々は世界に干渉しないとして、迷信と死への恐れから人を解放しようとした。"},{"t":"築いた体系","ic":"✦","v":"デモクリトス以来の原子論を受け継ぎ、原子がわずかに逸れる『クリナメン（偏り）』によって自由や多様な世界の生成を説明した。宗教を人の心を縛る迷信として退け、快と平静を求めるエピクロス倫理を詩の形で伝えた。ルネサンス以降に再発見され、近代の唯物論と科学に影響した。"},{"t":"キーワード","ic":"⚑","v":"原子論　万物は分割できない原子と空虚から成るとする自然観。\nクリナメン　原子がわずかに逸れる偏り。自由や生成の源とされる。\n死の恐れの克服　死は無であり恐れる必要はないとする教え。"},{"t":"つながり","ic":"→","v":"エピクロス（継承）\nエピクロスの原子論と快による平静の倫理を、詩の形で忠実にうたい継いだ。"}],"ポルフュリオス":[{"t":"核心","ic":"◈","v":"プロティノスの弟子で、その教えを編集して世に広めた新プラトン主義の哲学者。論理学の入門書でも有名。"},{"t":"本人の言葉","ic":"❝","v":"魂を、身体から少しずつ引き離せ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"新プラトン主義の哲学者で、師プロティノスの著作を『エネアデス』として編集・刊行し、その伝記も記した。アリストテレスの論理学への入門書『エイサゴーゲー（範疇論入門）』を著し、それが中世に普遍論争を引き起こす発端となった。魂の浄化と、キリスト教への批判でも知られる。"},{"t":"築いた体系","ic":"✦","v":"プロティノスの一者からの流出の思想を受け継ぎつつ、実践的な魂の浄化を重んじた。論理学・哲学の教科書的な整理に長け、その入門書はボエティウスのラテン語訳を通じて中世に伝わった。反キリスト教の書を著したことでも知られる。"},{"t":"キーワード","ic":"⚑","v":"エイサゴーゲー　アリストテレス論理学への入門書。普遍論争の発端となった。\n新プラトン主義　一者からの流出として世界を捉える古代末期の哲学。\n魂の浄化　身体的な欲から魂を引き離し、高めていく実践。"},{"t":"つながり","ic":"→","v":"プロティノス（師事）\n師プロティノスの著作を『エネアデス』として編集・刊行し、その思想を後世へ伝えた。"}],"オリゲネス":[{"t":"核心","ic":"◈","v":"初期キリスト教最大の学者の一人。ギリシア哲学を用いて聖書と信仰を体系的に説明しようとした。"},{"t":"本人の言葉","ic":"❝","v":"聖書には、字義の奥に霊的な意味が隠れている。","by":""},{"t":"何を言ったか","ic":"⟲","v":"古代アレクサンドリアの神学者で、初期キリスト教を代表する学者。プラトン主義の哲学を用いて、キリスト教の教えを初めて体系的に論じた。聖書を字義どおりにだけでなく、その奥に隠れた霊的・寓意的な意味から読み解く解釈を確立した。魂の先在や万物の最終的な救済も論じた。"},{"t":"築いた体系","ic":"✦","v":"信仰と理性、聖書とギリシア哲学を結びつけ、後の神学の枠組みを準備した。『諸原理について』で神・世界・魂を体系的に論じ、聖書本文の校訂にも取り組んだ。その一部の思想（魂の先在など）は後に正統から外れたとされたが、教父神学に絶大な影響を残した。"},{"t":"キーワード","ic":"⚑","v":"寓意的解釈　聖書の字義の奥にある霊的な意味を読み取る方法。\n信仰と哲学の総合　キリスト教の教えをギリシア哲学で体系化すること。\n魂の先在　魂が身体に宿る前から存在していたとする説。"},{"t":"つながり","ic":"→","v":"プラトン（影響を受けた）\nプラトン主義の哲学を用いて、キリスト教の教えと聖書解釈を体系的に組み立てた。"}],"ラモン・リュイ":[{"t":"核心","ic":"◈","v":"中世スペインの神学者。真理を組み合わせで導く『考える機械』のような論理の技術を考案した。多宗教の対話も試みた。"},{"t":"本人の言葉","ic":"❝","v":"すべての真理は、一つの技術によって示しうる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"中世スペイン（カタルーニャ）の神学者・哲学者・宣教者。基本概念を図と回転する円盤で組み合わせ、あらゆる真理を体系的に導き出そうとする『大いなる術（アルス・マグナ）』を考案した。この結合の論理は、後のライプニッツの記号論理や計算の構想を先取りしたとされる。"},{"t":"築いた体系","ic":"✦","v":"神の善・偉大・永遠などの根本属性を組み合わせ、理性によって信仰の真理を証明し、異教徒をも説得しようとした。イスラーム教徒やユダヤ教徒との対話を試み、アラビア語も学んだ。膨大な著作を残し、その組合せ的な方法は近代の論理学・計算機の遠い先駆と評される。"},{"t":"キーワード","ic":"⚑","v":"大いなる術　概念を組み合わせて真理を導く体系的な論理の技術。\n結合の論理　基本概念の組み合わせによって命題を生み出す方法。\n諸宗教の対話　キリスト教・イスラーム・ユダヤ教が理性で語り合う試み。"},{"t":"つながり","ic":"→","v":"トマス・アクィナス（同時代）\n信仰の真理を理性によって基礎づけようとする中世スコラの営みを、独自の結合術によって推し進めた。"}],"グロティウス":[{"t":"核心","ic":"◈","v":"『国際法の父』と呼ばれるオランダの法学者・思想家。国どうしが従うべき法や、戦争のルールを理性から基礎づけた。"},{"t":"本人の言葉","ic":"❝","v":"たとえ神が存在しないとしても、自然法は成り立つ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"オランダの法学者・思想家で、近代自然法論と国際法の礎を築いた。人間の理性と社会的な本性に根ざす自然法は、たとえ神が存在しないと仮定しても成り立つほど普遍的だとした。『戦争と平和の法』で、戦争にも守るべき正義とルールがあることを論じ、諸国家間の法秩序を構想した。"},{"t":"築いた体系","ic":"✦","v":"人間には生まれつき社会を求める本性があり、そこから約束を守る・他者の物を尊重するといった自然法の諸規則が理性によって導かれるとした。この自然法を、神学から相対的に独立した合理的な体系として提示し、後のホッブズやロック、近代の国際秩序の理論に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"自然法　人間の理性と本性に根ざす、普遍的で不変の法。\n国際法　諸国家のあいだに成り立つべき法とルール。\n社会的本性　人間が生まれつき社会を求める性質。"},{"t":"つながり","ic":"→","v":"ホッブズ（影響を与えた）\n理性から法と秩序を基礎づける自然法論は、後のホッブズの社会契約の理論を準備した。"}],"ピエール・ベール":[{"t":"核心","ic":"◈","v":"あらゆる説を疑いの目で吟味したフランスの思想家。信仰の違いを理由に人を罰してはならないと、寛容を強く訴えた。"},{"t":"本人の言葉","ic":"❝","v":"良心の誤りにも、寛容が与えられねばならない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランスの哲学者・批評家で、啓蒙の先駆者。膨大な『歴史批評辞典』で、あらゆる学説や伝承を鋭い懐疑と批判の目で吟味した。信仰と理性は必ずしも一致しないとし、良心にもとづく誤りにも寛容を与えるべきだと説いて、宗教的寛容と思想の自由を強く擁護した。"},{"t":"築いた体系","ic":"✦","v":"新旧の学説の矛盾や誤りを容赦なく暴くその批判精神は、理性による伝統の吟味という啓蒙の姿勢を先取りした。信仰は理性では基礎づけられないとする信仰主義的な面と、徹底した懐疑とが同居する。無神論者でも道徳的でありうると論じ、寛容論とともに後の啓蒙思想に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"寛容　信仰や思想の違いを理由に人を罰しない態度。\n懐疑と批判　あらゆる説を疑い、その根拠を吟味する精神。\n信仰と理性の分離　信仰は理性では基礎づけられないとする見方。"},{"t":"つながり","ic":"→","v":"スピノザ（近い立場）\n信仰の自由と寛容を擁護する点でスピノザと問題意識を共有しつつ、独自の懐疑的批判を展開した。"}],"ハチスン":[{"t":"核心","ic":"◈","v":"人には善悪を感じ取る『道徳感覚』があると理論化したスコットランドの哲学者。『最大多数の最大幸福』の言葉でも知られる。"},{"t":"本人の言葉","ic":"❝","v":"最大多数の最大幸福をもたらす行為が、最善である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"スコットランド啓蒙を開いた道徳哲学者。シャフツベリを受け継ぎ、人間には善悪や美を直接に感じ取る『道徳感覚』が生まれつき備わっていると理論化した。道徳の善さを、他者への慈愛（博愛）に見いだし、最大多数の最大幸福をもたらす行為を最善とする功利主義的な原理も先取りした。"},{"t":"築いた体系","ic":"✦","v":"道徳を理性による計算ではなく、快・不快に似た感覚的な承認・否認から説明した。この道徳感覚説は、弟子のヒュームやアダム・スミスの道徳感情論へと受け継がれた。また幸福の量を計る発想は、後のベンサムの功利主義の源流の一つとなった。スコットランド啓蒙の礎を築いた。"},{"t":"キーワード","ic":"⚑","v":"道徳感覚　善悪を理屈以前に感じ取る、生まれつきの心の働き。\n博愛　他者の幸福を願う慈愛。道徳の善さの源とされる。\n最大多数の最大幸福　より多くの人に幸福をもたらす行為を善とする原理。"},{"t":"つながり","ic":"→","v":"シャフツベリ（継承）\nシャフツベリの道徳感覚の着想を受け継ぎ、それを一つの明確な理論へと発展させた。"}],"クリスティアン・ヴォルフ":[{"t":"核心","ic":"◈","v":"ライプニッツの思想を整理し、ドイツの大学哲学の体系を築いた啓蒙期の哲学者。カント以前のドイツ哲学の主流をなした。"},{"t":"本人の言葉","ic":"❝","v":"哲学とは、可能なるものについての学である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツ啓蒙を代表する哲学者。ライプニッツの思想を受け継ぎ、それを明晰な定義と論証によって整然とした体系にまとめ上げた。論理学・形而上学・倫理学・自然学などを厳密な順序で配列し、ドイツの大学における哲学教育の標準を築いた。理性による体系化を重んじる、カント以前のドイツ哲学の主流をなした。"},{"t":"築いた体系","ic":"✦","v":"すべての知を、明晰な概念と充足理由律にもとづいて演繹的に配列しようとした。ドイツ語で哲学用語を整備し、多くの近代的な概念語を定着させた。その合理主義的な体系は広く普及したが、理性を過信するとして敬虔主義者と対立し、また後にカントの批判哲学が乗り越えるべき対象ともなった。"},{"t":"キーワード","ic":"⚑","v":"体系化　知を明晰な定義と論証で整然と配列すること。\n合理主義　理性による演繹を知の基礎とする立場。\n充足理由律　すべてには、そうである十分な理由があるとする原理。"},{"t":"つながり","ic":"→","v":"ライプニッツ（継承・体系化）\nライプニッツの断片的な思想を受け継ぎ、明晰な定義と論証によって整然とした体系にまとめ上げた。"}],"ヤコービ":[{"t":"核心","ic":"◈","v":"『理屈だけで突き詰めると信仰も自由も消えてしまう』と警告したドイツの思想家。理性の限界を指摘し、直接の信によって支えようとした。"},{"t":"本人の言葉","ic":"❝","v":"理性を突き詰めれば、すべては必然となり神は消える。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツの哲学者・作家。理性による論証を徹底すると、世界はすべて必然の連鎖となり、自由も人格神も消えて虚無（ニヒリズム）に至ると警告した。これを避ける道を、論証によらず対象を直接につかむ『信（信仰）』に求めた。スピノザ論争や無神論論争を引き起こし、同時代の哲学に鋭く切り込んだ。"},{"t":"築いた体系","ic":"✦","v":"レッシングがひそかにスピノザ主義者だったと暴露して『スピノザ論争』を起こし、理性主義が行き着く決定論と無神論の危うさを突きつけた。カントの物自体や、フィヒテの自我の哲学をも批判し、論証を超えた直接の確信によって神・自由・実在を支えようとした。『ニヒリズム』という語を広めたことでも知られる。"},{"t":"キーワード","ic":"⚑","v":"信（信仰）　論証によらず、実在や神を直接につかむ確信。\nニヒリズム　理性を突き詰めた果てに、価値も神も消える虚無。\n理性主義批判　論証の徹底が決定論と無神論に至ると警告する立場。"},{"t":"つながり","ic":"→","v":"スピノザ（批判的に対峙）\n理性を突き詰めた哲学の帰結をスピノザの必然の体系に見て、それが招く決定論と無神論を批判した。"}],"ヴィルヘルム・フォン・フンボルト":[{"t":"核心","ic":"◈","v":"言語と人間の成長を深く考えたドイツの思想家・言語学者。近代的な大学の理念を築き、個人の自由な発展を重んじた。"},{"t":"本人の言葉","ic":"❝","v":"言語は、できあがった作品ではなく、たえず生み出す活動である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツの言語哲学者・思想家・教育改革者。言語を、できあがった物ではなく、話し手がたえず世界を捉え直す生きた活動とみなし、言語ごとに世界の見え方（世界観）が異なると論じた。個人の多面的な自己形成（教養）を最高の理想とし、研究と教育を統一する近代的な大学の理念を築いた。"},{"t":"築いた体系","ic":"✦","v":"各言語には固有の『内的言語形式』があり、それが民族の世界の捉え方を形づくるとした。この考えは後の言語相対論に連なる。政治的には、国家の役割を最小限にとどめ、個人がのびのびと諸能力を発展させる自由を重んじた。ベルリン大学の創設に関わり、教養と学問の自由を核とする大学像を打ち立てた。"},{"t":"キーワード","ic":"⚑","v":"言語＝活動　言語をできあがった物でなく、生きた創造の営みとみる見方。\n世界観と言語　言語ごとに世界の捉え方が異なるとする考え。\n教養（自己形成）　人が諸能力を多面的に発展させて自らを形づくること。"},{"t":"つながり","ic":"→","v":"ヘルダー（継承）\n言語が民族の世界の捉え方を形づくるというヘルダーの発想を受け継ぎ、精緻な言語哲学へと展開した。"}],"クローチェ":[{"t":"核心","ic":"◈","v":"20世紀前半のイタリアを代表する哲学者。芸術を『直観』として捉え、歴史や精神の営みを重んじた。反ファシズムの知識人としても名高い。"},{"t":"本人の言葉","ic":"❝","v":"すべての真の歴史は、現代の歴史である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"イタリアの哲学者・歴史家で、新ヘーゲル主義を代表する。芸術の本質を、概念以前の個別的なイメージの把握である『直観』に見いだした美学で知られる。歴史を、過去そのものではなく、現在の関心から生きて捉え直される精神の営みとした。ファシズムに抵抗した自由主義の知識人としても尊敬された。"},{"t":"築いた体系","ic":"✦","v":"ヘーゲルの精神の哲学を受け継ぎつつ、精神の活動を美（直観）・論理（概念）・経済（有用）・倫理（善）の四領域として捉え直した。ヴィーコを再評価し、歴史と精神を重んじる立場を貫いた。抽象的な体系より、生きた歴史のなかに真理を見た。ムッソリーニ政権下で反ファシズムの精神的支柱となった。"},{"t":"キーワード","ic":"⚑","v":"直観　概念以前の、個別的なイメージの把握。芸術の本質。\n歴史主義　真理を、生きた歴史のなかに見いだす立場。\n精神の哲学　精神の諸活動から世界を捉える、ヘーゲル的な立場。"},{"t":"つながり","ic":"→","v":"ヘーゲル（批判的に継承）\nヘーゲルの精神の哲学を受け継ぎつつ、その体系を美・論理・経済・倫理の四領域として組み替えた。"}],"オルテガ・イ・ガセット":[{"t":"核心","ic":"◈","v":"『大衆の時代』を鋭く分析したスペインの哲学者。人は自分と、自分を取り巻く状況とが一つになって生きている、と考えた。"},{"t":"本人の言葉","ic":"❝","v":"私は、私と私の環境である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀スペインを代表する哲学者・思想家。『私は、私と私の環境である』という言葉で、人間を、切り離された自我ではなく、つねに具体的な状況（環境）と結びついて生きる存在として捉えた。『大衆の反逆』では、みずから考えず平均に安住する『大衆』の台頭が現代の危機を招くと論じた。"},{"t":"築いた体系","ic":"✦","v":"生を、与えられた状況のなかで自らの計画を選び取っていく営みとして捉える『生の理性』の哲学を説いた。現象学や実存哲学と響き合いつつ、明晰で文学的な文章で広い読者に語りかけた。エリートの責任と、平均への埋没を戒めるその文明批評は、大衆社会論の古典となった。"},{"t":"キーワード","ic":"⚑","v":"私と環境　自我と、それを取り巻く状況とが一体で生きるとする見方。\n生の理性　生を、状況のなかで選び取る営みとして捉える立場。\n大衆　みずから考えず、平均に安住する現代の人間像。"},{"t":"つながり","ic":"→","v":"ニーチェ（影響を受けた）\n生と卓越を重んじ、平均への埋没を批判する点で、ニーチェの問題意識を受け継いだ。"}],"ソロヴィヨフ":[{"t":"核心","ic":"◈","v":"神と世界、人類がやがて一つに結ばれると説いたロシアの宗教哲学者。愛と『全一性』を重んじた。"},{"t":"本人の言葉","ic":"❝","v":"すべては、一なるものにおいて結ばれている。","by":""},{"t":"何を言ったか","ic":"⟲","v":"近代ロシアを代表する宗教哲学者・詩人。神・世界・人類が本来一つに結ばれているとする『全一性』の思想を軸に、分裂した世界がやがて愛によって神のうちに統一される道を説いた。西方と東方の教会の一致や、知と信仰の総合を求め、後のロシア宗教哲学の源流となった。"},{"t":"築いた体系","ic":"✦","v":"経験・理性・信仰を対立させず総合しようとし、また神の知恵を人格的に捉える『ソフィア（神智）』の思想を展開した。人類が神と一つになる過程としての歴史を、愛を原理として描いた。ドストエフスキーと親交し、ベルジャーエフら20世紀ロシア宗教哲学の思想家たちに深い影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"全一性　神・世界・人類が本来一つに結ばれているとする思想。\nソフィア（神智）　世界を貫く、神の人格的な知恵。\n神と人類の統一　歴史を、人類が神と一つになる過程とみる見方。"},{"t":"つながり","ic":"→","v":"ヘーゲル（批判的に継承）\n精神が歴史を通じて統一へ向かうというヘーゲル的な発想を、宗教的な全一性の思想へと組み替えた。"}],"ベルジャーエフ":[{"t":"核心","ic":"◈","v":"『自由』をなにより重んじたロシアの宗教哲学者。人間の創造する力と精神の自由を、神の似姿として讃えた。"},{"t":"本人の言葉","ic":"❝","v":"自由は、神よりもさらに深い根源から湧き出る。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ロシアの宗教哲学者で、自由と創造の思想家。人間の本質を、神の似姿としての精神の自由と、新しいものを生み出す創造の力に見た。自由は神の意志にも先立つ根源から湧くとし、既存の秩序に人間を従わせようとするあらゆる客体化・全体主義に抵抗した。革命後にロシアを追われ、パリで活動した。"},{"t":"築いた体系","ic":"✦","v":"精神と物質、自由と必然を対立させ、人格の自由を圧殺する社会や体制を『客体化』として批判した。マルクス主義から出発したが、やがてキリスト教的な人格主義・実存哲学へ転じた。人間の創造を神の創造の続きとみる大胆な思想を展開し、20世紀の実存思想やロシア亡命知識人に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"精神の自由　人間を神の似姿たらしめる、根源的な自由。\n創造　新しいものを生み出す、人間に固有の力。\n客体化　生きた精神を物のように扱い、自由を奪う働き。"},{"t":"つながり","ic":"→","v":"キルケゴール（影響を受けた）\n個の実存と自由を重んじるキルケゴールの思想を受け継ぎ、宗教的な自由の哲学へと展開した。"}],"カール・シュミット":[{"t":"核心","ic":"◈","v":"『政治とは、敵と味方を分けることだ』と論じたドイツの法学者。危機のときに誰が決めるのか、という主権の問題を鋭く突いた。ナチスに加担した過去でも問題視される。"},{"t":"本人の言葉","ic":"❝","v":"主権者とは、例外状態を決定する者である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀ドイツの法学者・政治思想家。政治の本質を、道徳や経済とは区別される『友と敵』の区別に見た。法が停止する『例外状態』において、それを決定する者こそが主権者だとして、法の背後にある決定の力を暴いた。自由主義や議会主義を鋭く批判したが、ナチス政権に加担した過去で強く問われる。"},{"t":"築いた体系","ic":"✦","v":"平時の法秩序ではなく、その秩序が破れる危機の瞬間にこそ、政治と主権の本質が現れるとした。神学的な概念が世俗化して法・国家の概念になったとする『政治神学』も論じた。その議論は毒を含みつつも鋭く、左右を問わず後の政治思想に影響を与え続けている。"},{"t":"キーワード","ic":"⚑","v":"友と敵　政治の本質を、味方と敵の区別に見る考え。\n例外状態　法が停止する危機の状態。主権の本質が現れる。\n主権　例外状態において、決定を下す最終の力。"},{"t":"つながり","ic":"→","v":"ホッブズ（継承）\n無秩序を避けるために強大な主権を立てるホッブズの思想を受け継ぎ、例外状態における主権として先鋭化させた。"}],"レオ・シュトラウス":[{"t":"核心","ic":"◈","v":"『古代の哲学に立ち返れ』と説いたユダヤ系の政治哲学者。近代が失った、善き生や自然的な正しさへの問いを取り戻そうとした。"},{"t":"本人の言葉","ic":"❝","v":"古典を、著者が理解したとおりに理解せよ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツ出身でアメリカに亡命したユダヤ系の政治哲学者。近代が、善き生や自然的な正しさという古典的な問いを見失い、価値相対主義と歴史主義に陥ったと診断した。ソクラテスやプラトンら古代の政治哲学に立ち返ることを説いた。迫害下の哲学者が本音を行間に隠す『秘教的な書き方』の読解でも知られる。"},{"t":"築いた体系","ic":"✦","v":"近代政治哲学（マキャヴェッリに始まる）が、高い理想を捨てて低い現実に基準を下げたことを『近代性の危機』として批判した。歴史や社会によって真理が相対化されるとする歴史主義を退け、古典的な自然権・自然的正の探究を復権させようとした。多くの弟子を育て、アメリカの政治思想に影響を残した。"},{"t":"キーワード","ic":"⚑","v":"古典への回帰　古代の政治哲学に立ち返り、その問いを取り戻すこと。\n近代性の危機　近代が善き生への問いを見失ったとする診断。\n自然的正（自然権）　慣習を超えて、本性に根ざす正しさの探究。"},{"t":"つながり","ic":"→","v":"プラトン（回帰）\n近代の危機に抗して、プラトンら古代の政治哲学に立ち返り、善き生と正義への問いを取り戻そうとした。"}],"ハンス・ヨナス":[{"t":"核心","ic":"◈","v":"科学技術の時代の新しい倫理を説いたユダヤ系の哲学者。未来の世代や自然に対する『責任』を、倫理の中心に据えた。"},{"t":"本人の言葉","ic":"❝","v":"人類が地上に存在し続けるように行為せよ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツ出身でアメリカに亡命したユダヤ系の哲学者。科学技術が自然と人類の未来そのものを脅かす時代には、いま目の前の相手だけでなく、まだ生まれていない未来の世代や自然に対する『責任』こそが倫理の中心になるべきだと説いた。近代の進歩主義に警鐘を鳴らす環境倫理・生命倫理の先駆者。"},{"t":"築いた体系","ic":"✦","v":"従来の倫理が同時代の人間関係だけを扱ってきたのに対し、巨大な力をもつ技術文明のもとでは、その行為が遠い未来にまで及ぼす帰結への責任が問われるとした。最悪の可能性を重く見る『恐れにもとづく発見術』を説き、人類が存在し続けることを命じる新しい定言命法を提示した。グノーシス主義の研究者でもあった。"},{"t":"キーワード","ic":"⚑","v":"責任原理　未来の世代や自然に対する責任を倫理の中心に据える原理。\n未来への責任　まだ存在しない将来の世代に対して負う責任。\n技術文明批判　巨大な力をもつ技術がはらむ危険への警告。"},{"t":"つながり","ic":"→","v":"ハイデガー（批判的に継承）\n師ハイデガーの存在の思索と技術への問いを受け継ぎつつ、それを未来への責任の倫理へと転じた。"}],"バシュラール":[{"t":"核心","ic":"◈","v":"科学の進歩と、詩的な想像力の両方を探ったフランスの哲学者。科学は過去の思い込みを乗り越えて進むと考えた。"},{"t":"本人の言葉","ic":"❝","v":"科学の精神は、自らの過去を否定して進む。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランスの科学哲学者・詩学者。科学の歴史を、常識や古い思い込み（認識論的障害）を乗り越えて非連続的に飛躍する過程として捉え、そのつどの断絶を『認識論的切断』と呼んだ。一方で、火・水・空気・大地といった元素をめぐる詩的な想像力の世界も深く探究し、理性と夢想の両面を生きた。"},{"t":"築いた体系","ic":"✦","v":"科学が連続的に積み重なるとする見方を退け、相対性理論や量子論のような飛躍によって、それまでの常識的な世界像が根本から組み替えられると論じた。同時に、科学が退けた想像力そのものを主題として、物質のイメージが呼び起こす夢想を現象学的に描いた。科学認識論と文学的想像力という二つの領域を往復した稀有な思想家である。"},{"t":"キーワード","ic":"⚑","v":"認識論的障害　科学の進歩を妨げる、常識や古い思い込み。\n認識論的切断　古い認識を乗り越えて飛躍する、科学史の断絶。\n科学の非連続性　科学が積み重ねでなく飛躍で進むとする見方。"},{"t":"つながり","ic":"→","v":"デカルト（批判的に継承）\n明晰な認識を求めるデカルト以来の伝統を受けつつ、認識を妨げる障害と断絶を強調してこれを組み替えた。"}],"バタイユ":[{"t":"核心","ic":"◈","v":"『役に立つこと』の枠をはみ出す、過剰や消尽に人間の本質を見たフランスの思想家。聖なるもの、エロス、死を大胆に論じた。"},{"t":"本人の言葉","ic":"❝","v":"人間は、役に立たない蕩尽のうちに自らを賭ける。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランスの思想家・作家。人間や社会を、有用性と蓄積の論理だけでは捉えきれないとし、余剰を惜しみなく蕩尽する『消尽』の側面に注目した。祝祭・供犠・エロス・笑い・死といった、日常の役立つ秩序を突き破る『侵犯』の経験のうちに、聖なるものと人間の真実を見た。"},{"t":"築いた体系","ic":"✦","v":"エネルギーは生産と蓄積だけでなく、過剰として費やされねばならないとする『普遍経済学』を構想した。禁止と、それを破る侵犯の緊張のうちに、聖なるものやエロスの本質を捉えた。ヘーゲル（コジェーヴ経由）やニーチェ、フロイトを独自に受けとめ、シュルレアリスムや後のポスト構造主義に影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"消尽（蕩尽）　有用性を超えて、余剰を惜しみなく費やすこと。\n侵犯　禁止された境界を破り、聖なるものに触れる経験。\n聖なるもの　日常の秩序を突き破る、めくるめく力の領域。"},{"t":"つながり","ic":"→","v":"ニーチェ（影響を受けた）\n善悪の彼岸で生の過剰を肯定するニーチェの思想を受けとめ、消尽と侵犯の思想へと展開した。"}],"ボードリヤール":[{"t":"核心","ic":"◈","v":"現代を『本物のないコピーの時代』と診断したフランスの思想家。テレビや広告のイメージが現実そのものを覆い尽くすと論じた。"},{"t":"本人の言葉","ic":"❝","v":"もはや現実は、記号の模像に取って代わられた。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランスの社会学者・思想家。現代の消費社会では、人はモノの実用性ではなく、それが帯びる記号としての意味を消費すると論じた。さらに、メディアと情報が生み出すイメージ（シミュラークル）が、もはや元の現実をもたない模像として自立し、現実そのものを覆い尽くす『ハイパーリアル』の時代を診断した。"},{"t":"築いた体系","ic":"✦","v":"マルクスの生産の分析を、記号と消費の分析へと組み替えた。オリジナルなき複製が現実に取って代わる過程を『シミュレーション』として描き、現実と虚構の区別が消えた現代文明を鋭く挑発的に論じた。その議論はメディア論・文化論に大きな影響を与え、しばしば論争を呼んだ。"},{"t":"キーワード","ic":"⚑","v":"シミュラークル　元の現実をもたない、自立した模像・イメージ。\nハイパーリアル　模像が現実を覆い、現実より現実らしくなる状態。\n記号消費　モノの実用でなく、その記号的な意味を消費すること。"},{"t":"つながり","ic":"→","v":"マルクス（批判的に継承）\n生産を軸とするマルクスの社会分析を受けつつ、それを記号と消費の分析へと大胆に組み替えた。"}],"P.F.ストローソン":[{"t":"核心","ic":"◈","v":"私たちの考え方の根っこにある、変わらない枠組みを描こうとしたイギリスの分析哲学者。人格や物体といった基本概念を探った。"},{"t":"本人の言葉","ic":"❝","v":"私たちの世界像には、変わらぬ骨組みがある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀後半のイギリス分析哲学を代表する哲学者。私たちの思考の根底にあり、時代を超えて変わらない概念の骨組みを描き出す『記述的形而上学』を提唱した。物体と人格を、世界を捉えるうえで欠かせない基本的な個物とした。ラッセルの記述理論への批判や、責任と感情をめぐる自由論でも知られる。"},{"t":"築いた体系","ic":"✦","v":"世界をどうあるべきかと造り替える『修正的形而上学』に対し、私たちが現に世界を捉える枠組みを明らかにする記述的形而上学を区別した。日常言語の分析を通じて、指示・同一性・人格といった基本概念の構造を探った。決定論と道徳的責任の両立を、非難や感謝といった『反応的態度』から論じた議論も影響力をもつ。"},{"t":"キーワード","ic":"⚑","v":"記述的形而上学　私たちの思考の根底にある概念の枠組みを描く探究。\n基本的個物　物体と人格という、世界を捉える基礎となる存在。\n人格　心と身体の述語をともに担う、基本的な存在者。"},{"t":"つながり","ic":"→","v":"カント（批判的に継承）\n経験を可能にする枠組みを問うカントの企てを、日常言語の分析による記述的形而上学として現代に受け継いだ。"}],"デイヴィッド・ルイス":[{"t":"核心","ic":"◈","v":"『ありえた別の世界』が実際に存在すると大胆に主張したアメリカの哲学者。可能性や因果を、無数の世界を使って説明した。"},{"t":"本人の言葉","ic":"❝","v":"あらゆる可能世界は、この世界と同じように実在する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀後半アメリカを代表する分析哲学者。『もし〜だったら』という可能性を、無数の『可能世界』が私たちの世界と同じくらい現実に存在すると考えることで説明する、様相実在論を唱えた。この大胆な理論を用いて、可能性・必然・因果・反事実といった概念を精緻に分析し、形而上学の広い問題を体系的に論じた。"},{"t":"築いた体系","ic":"✦","v":"可能世界を単なる比喩や道具ではなく、実在する具体的な宇宙とみなした（具体的様相実在論）。この枠組みで、反事実的条件文や因果、法則、性質などを統一的に扱った。突飛にみえる前提から驚くほど整合的で強力な体系を築き、現代形而上学の議論の水準を大きく引き上げた。"},{"t":"キーワード","ic":"⚑","v":"可能世界　ありえた別のあり方をした、無数の世界。\n様相実在論　可能世界が現実世界と同じく実在するとする立場。\n反事実的条件　『もし〜だったら…だろう』という仮定の分析。"},{"t":"つながり","ic":"→","v":"クリプキ（論争・同時代）\n可能世界を用いて必然と可能を論じる点で近いが、可能世界の実在をめぐってクリプキと立場を異にした。"}],"バーナード・ウィリアムズ":[{"t":"核心","ic":"◈","v":"『正しさ』だけで人生を割り切る倫理学に疑問を投げたイギリスの哲学者。生きた個人の複雑さや偶然を大切にした。"},{"t":"本人の言葉","ic":"❝","v":"道徳という制度は、人生の全体を語り尽くせない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"20世紀後半イギリスを代表する道徳哲学者。功利主義とカント倫理学がともに、人格の個別性や人生の意味を見落としていると批判した。道徳を、規則で人を裁く狭い『制度』に閉じ込めることを退け、その人にとって生きるに値する計画（根本計画）や、運がからむ現実を重んじた。倫理を、より広く豊かな人間の生の問いへと開こうとした。"},{"t":"築いた体系","ic":"✦","v":"公平な計算を求める功利主義は、各人の人格の統合性を損なうと論じ、また普遍的規則を説くカント倫理学は、生きた個人の具体的な事情や感情を切り捨てると批判した。行為の善悪が本人には制御できない運に左右される『道徳的運』の問題を提起し、古代ギリシアの倫理観をも手がかりに、近代道徳の枠組みそのものを問い直した。"},{"t":"キーワード","ic":"⚑","v":"道徳への懐疑　規則で裁く狭い道徳の枠組みへの根本的な疑い。\n人格の統合性　一人の人間が自分の計画に一貫して関わるまとまり。\n根本計画　その人が生きる意味を支える、根底的な関わり。"},{"t":"つながり","ic":"→","v":"カント（批判）\n普遍的規則を求めるカント倫理学が、生きた個人の具体的な事情や感情を切り捨てると批判した。"}],"程顥":[{"t":"核心","ic":"◈","v":"北宋の儒学者で、弟の程頤とともに宋学を築いた。人と天地万物は一つにつながっている、と一体感を重んじた。"},{"t":"本人の言葉","ic":"❝","v":"仁者は、天地万物を一体とみなす。","by":""},{"t":"何を言ったか","ic":"⟲","v":"北宋の儒学者。弟の程頤とともに『二程子』と称され、宋学（道学）を大成へ導いた。弟がより厳密に理と気を分けたのに対し、程顥は、人と天地万物が一つにつながっているという生き生きとした一体感を重んじた。仁とは、この万物一体を体で感じ取る境地だとし、後の陽明学の源流となった。"},{"t":"築いた体系","ic":"✦","v":"天理を、外の事物を分析して究めるよりも、心のうちに直接に自覚するものとして捉えた。万物を貫く生成の働き（生生）を天理と見て、それと一つになる心のあり方を仁とした。この心を重んじる一元的な傾向は、弟程頤の理気を分ける立場とは対照をなし、陸九淵や王陽明の心学へと受け継がれた。"},{"t":"キーワード","ic":"⚑","v":"万物一体　人と天地万物が一つにつながっているとする境地。\n仁　万物一体を体で感じ取る、生き生きとした心。\n天理　万物を貫く、生成の働きとしての普遍の理。"},{"t":"つながり","ic":"→","v":"程頤（同時代・対照）\n弟の程頤とともに二程子として宋学を築いたが、心の一体感を重んじる点で理を分析する弟と対照をなした。"}],"陸九淵":[{"t":"核心","ic":"◈","v":"南宋の儒学者で、朱熹のライバル。理は外の物ではなく、自分の心のうちにあると説いた。後の陽明学のもと。"},{"t":"本人の言葉","ic":"❝","v":"宇宙は即ち吾が心、吾が心は即ち宇宙なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"南宋の儒学者で、朱熹と並び立ち論争した思想家。朱熹が事物を究めて外に理を求めたのに対し、陸九淵は、理は自分の心そのもののうちにあるとする『心即理』を唱えた。学問とは、煩雑な知識の積み重ねではなく、まず自らの本心を確立することだとした。その心学は、後に王陽明によって受け継がれ大成される。"},{"t":"築いた体系","ic":"✦","v":"『宇宙すなわち吾が心』と述べ、心と宇宙の理を一つと見た。朱熹の、書物を広く読み事物の理を究める方法を、末節にとらわれるものとして批判し、まず大本である本心を立てることを重んじた。両者は名高い『鵝湖の会』で直接に論争した。陸王心学の祖として、東アジア思想に大きな流れを開いた。"},{"t":"キーワード","ic":"⚑","v":"心即理　理は外の事物でなく、自分の心そのもののうちにあるとする説。\n本心の確立　知識の前に、まず自らの本来の心を立てること。\n宇宙と心の一致　宇宙の理と自分の心が一つであるとする境地。"},{"t":"つながり","ic":"→","v":"朱熹（対立）\n事物を究めて外に理を求める朱熹に対し、理は心のうちにあるとする心即理を唱え、鵝湖の会で直接論争した。"}],"王夫之":[{"t":"核心","ic":"◈","v":"明末清初の儒学者。世界は『気』というエネルギーで満ちており、抽象的な理だけが独り立ちすることはない、と現実を重んじた。"},{"t":"本人の言葉","ic":"❝","v":"天下に、気を離れた理はない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"明末清初の儒学者・思想家。滅びゆく明を見つめながら、隠棲して膨大な著作を残した。張載の気の哲学を受け継ぎ、世界の根源を『気』とし、理は気を離れて独立には存在しないと説いた。抽象的な観念より、たえず変化する具体的な現実と歴史を重んじ、朱子学や仏教・老荘を批判的に乗り越えようとした。"},{"t":"築いた体系","ic":"✦","v":"理を気に先立つ独立した原理とみる朱子学を退け、理は気の運動に内在する筋道にすぎないとした（気の一元論）。世界は静止せず絶えず生成変化するとし、歴史も進展するものと捉えた。人間の欲望を一概に否定せず、現実の生を肯定する立場をとった。その思想は後の近代中国で再評価された。"},{"t":"キーワード","ic":"⚑","v":"気の一元論　世界の根源を気とし、理は気に内在するとする立場。\n理は気に即す　理は気を離れて独立には存在しないとする考え。\n生成変化　世界はたえず変化し生成し続けるとする見方。"},{"t":"つながり","ic":"→","v":"張載（継承）\n張載の気の一元論を受け継ぎ、理は気に内在するとしてそれをいっそう徹底させた。"}],"石田梅岩":[{"t":"核心","ic":"◈","v":"江戸時代、町人・商人のための道徳『石門心学』をひらいた人。正直と倹約を説き、商売で利益を得ることを堂々と肯定した。"},{"t":"本人の言葉","ic":"❝","v":"商人の売利は、士の禄に同じ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"江戸中期の思想家で、石門心学の祖。儒教・仏教・神道と、みずからの商家奉公の経験を融合し、町人・商人のための実践的な道徳を平易に説いた。商人が正当な商売で利益を得ることは、武士が俸禄を得るのと同じく正しいと論じ、当時低く見られていた商業の意義を堂々と肯定した。"},{"t":"築いた体系","ic":"✦","v":"人の心には本来、天地万物と通じる本性（本心）が備わっているとし、私欲を離れてこの本心に立ち返ることを説いた。その徳目は、正直と倹約という、商人の生活に即した実践的なものであった。難しい学問でなく、身近な言葉で庶民に道を説いたその心学は、講釈を通じて全国に広まり、日本の勤勉と商業倫理の形成に影響した。"},{"t":"キーワード","ic":"⚑","v":"石門心学　町人・商人のための実践的な道徳。梅岩がひらいた。\n正直　いつわりのない、まっすぐな心と商い。\n倹約　むだを省き、分に応じて慎ましく暮らすこと。"},{"t":"つながり","ic":"→","v":"孔子（影響を受けた）\n儒教の徳の教えを受け継ぎつつ、それを武士でなく町人・商人の生活に即した実践道徳へと組み替えた。"}],"アンベードカル":[{"t":"核心","ic":"◈","v":"インドで差別されてきた人々の解放に生涯を捧げた思想家・政治家。カースト制度を批判し、憲法を起草し、仏教に活路を求めた。"},{"t":"本人の言葉","ic":"❝","v":"私はヒンドゥーとして生まれたが、ヒンドゥーとしては死なない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"近代インドの思想家・法律家・政治家で、被差別民（不可触民）の出身。カースト制度による差別を、宗教と社会の根本にかかわる不正として鋭く批判した。独立インドの憲法起草の中心を担い、平等と人権を法にきざんだ。晩年、カーストを否定する道を仏教に見いだし、多くの仲間とともに改宗した。"},{"t":"築いた体系","ic":"✦","v":"差別の根をヒンドゥー教の教義そのものに見て、その聖典の権威をも批判した。ガンディーが差別の緩和を説いたのに対し、アンベードカルはカースト制度そのものの廃絶を求めて、より根底的に対立した。理性と平等、そして人間の尊厳を重んじ、これを実現する思想として、独自に読み直した仏教を選び取った。"},{"t":"キーワード","ic":"⚑","v":"カースト制度批判　生まれによる身分差別を、根本の不正として退ける立場。\n被差別民の解放　差別されてきた人々の尊厳と権利の回復。\n憲法と平等　法によって平等と人権を保障しようとする営み。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（回帰）\nカーストを否定し理性と平等を説く道として仏教を選び取り、それを被差別民の解放の思想として読み直した。"}],"グル・ナーナク":[{"t":"核心","ic":"◈","v":"シク教をひらいたインドの宗教改革者。ヒンドゥー教とイスラームの壁を越え、唯一の神への信愛と、人間の平等を説いた。"},{"t":"本人の言葉","ic":"❝","v":"ヒンドゥーもムスリムもない。ただ神の人があるのみ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"シク教の開祖である、北インドの宗教改革者・詩人。ヒンドゥー教とイスラームが対立するなかで、両者の枠を超えた唯一なる神への信愛を説いた。形式的な儀礼やカーストによる差別を退け、神の名を心にとなえること、正直な労働、そして分かち合いを重んじた。人間の平等と、日々の生活のなかの信仰を大切にした。"},{"t":"築いた体系","ic":"✦","v":"形なき唯一の神を立て、その神は特定の宗教に属さないとした。偶像崇拝や煩瑣な儀礼、身分差別を否定し、神への献身（バクティ）と、俗世を捨てない在家の実践を結びつけた。師（グル)から師へと受け継がれる導きを重んじ、その教えは共同体と聖典に結晶して、独立した宗教シク教となった。"},{"t":"キーワード","ic":"⚑","v":"唯一なる神　形をもたず、特定の宗教に属さない、ただ一つの神。\n神の名の唱念　神の名を心にとなえ、神を想い続ける実践。\n平等　カーストや宗教の別を超えた、すべての人の平等。"},{"t":"つながり","ic":"→","v":"ラーマーヌジャ（影響を受けた）\n人格をもつ神への熱烈な信愛によって救われるとするバクティの伝統を受け継ぎ、独自の一神信仰へと展開した。"}],"イブン・ガビロール":[{"t":"核心","ic":"◈","v":"中世スペインのユダヤ人詩人・哲学者。新プラトン主義をもとに、神から万物が流れ出る壮大な世界像を描いた。ラテン名アヴィケブロン。"},{"t":"本人の言葉","ic":"❝","v":"万物は、質料と形相から成る。","by":""},{"t":"何を言ったか","ic":"⟲","v":"中世スペイン（アンダルス）のユダヤ人詩人・哲学者。新プラトン主義にもとづき、唯一の神の意志から万物が段階的に流れ出るとする流出の哲学を説いた。天使や魂といった精神的な存在をも含め、神以外のすべては質料と形相の結合から成るとした。その主著はラテン語に訳され、アヴィケブロンの名でキリスト教スコラ哲学に影響した。"},{"t":"築いた体系","ic":"✦","v":"神の意志を、神と世界を媒介する根源的な働きとして重視した。存在の階層を、上位から下位へと流出する連続として描き、精神的存在にも質料があるとする『普遍的質料形相論』を唱えた。この立場はフランシスコ会系のスコラ学に受け継がれた。彼はユダヤ教の典礼詩の傑作を残した詩人としても名高い。"},{"t":"キーワード","ic":"⚑","v":"流出　唯一の神から万物が段階的に流れ出るとする世界像。\n神の意志　神と世界を媒介する、根源的な働き。\n普遍的質料形相論　精神的存在をも含め万物が質料と形相から成るとする説。"},{"t":"つながり","ic":"→","v":"プロティノス（影響を受けた）\nプロティノスに始まる新プラトン主義の流出の思想を受け継ぎ、それをユダヤ的な一神信仰と結びつけた。"}],"アナクシメネス":[{"t":"核心","ic":"◈","v":"万物のもとを「空気」と考えたミレトス学派の自然哲学者。濃くなったり薄くなったりして、すべてが生じると説いた。"},{"t":"本人の言葉","ic":"❝","v":"万物の根源は空気である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ミレトス学派の自然哲学者。師アナクシマンドロスを継ぎ、万物の根源(アルケー)を目に見える「空気(アエール)」に求めた。空気が濃くなれば水や土に、薄くなれば火になるとし、質の変化を量の濃淡で説明しようとした。"},{"t":"築いた体系","ic":"✦","v":"根源を無限定なものに置いた師と違い、具体的で観察可能な空気を選んだ点に特徴がある。濃厚化と希薄化という一つの原理で多様な物質の生成を説明し、後の自然科学的な思考の芽をなした。"},{"t":"キーワード","ic":"⚑","v":"アエール(空気)　万物の根源とされた空気。濃淡によって多様な物へ変化する。\n濃厚化と希薄化　一つの素材が濃くなり薄くなることで多様な物質が生じるという説明原理。"},{"t":"つながり","ic":"→","v":"タレス（継承）\n万物の根源を問うミレトス学派の探究を受け継ぎ、それを空気に求めた。"}],"エレアのゼノン":[{"t":"核心","ic":"◈","v":"「アキレスと亀」などの逆説(パラドックス)で有名な古代ギリシアの哲学者。運動や多は幻だと論証しようとした。"},{"t":"本人の言葉","ic":"❝","v":"アキレスは決して亀に追いつけない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"エレア学派の哲学者。師パルメニデスの「有は一で不動」という主張を守るため、運動や複数性を認めると矛盾が生じることを、巧妙な逆説の数々によって示そうとした。アキレスと亀、飛ぶ矢などが名高い。"},{"t":"築いた体系","ic":"✦","v":"帰謬法(相手の前提から矛盾を導く論法)を駆使し、常識的に見える「運動」や「多」がかえって不合理を含むと論じた。その論法は無限や連続をめぐる後の数学・論理の問題を先取りするものとなった。"},{"t":"キーワード","ic":"⚑","v":"アキレスと亀　速い者が先を行く遅い者に追いつけないとする、無限分割の逆説。\n帰謬法　相手の主張を仮に認め、そこから矛盾を導いて否定する論法。"},{"t":"つながり","ic":"→","v":"パルメニデス（師事）\n師の説く不動の一なる有を、逆説によって擁護しようとした。"}],"アンティステネス":[{"t":"核心","ic":"◈","v":"ソクラテスの弟子で、キュニコス派(犬儒派)の先駆とされる哲学者。徳と質素な生き方こそ幸福だと説いた。"},{"t":"本人の言葉","ic":"❝","v":"わたしは快楽を得るより、狂気を選ぶ。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ソクラテスの弟子。快楽や富ではなく、徳にもとづく自足した生こそが幸福だと主張した。欲望を減らし、社会の慣習にとらわれない質素な生き方を重んじ、後のディオゲネスらキュニコス派の源流となった。"},{"t":"築いた体系","ic":"✦","v":"徳は行いによって身につくもので、言葉の飾りや世間的な地位は不要だとした。自然に従い、必要を最小限にする自足(アウタルケイア)を理想とし、禁欲的な生き方を実践哲学として示した。"},{"t":"キーワード","ic":"⚑","v":"アウタルケイア(自足)　外的なものに頼らず、自分の内で満ち足りている状態。\n徳への実践　知識より行いによって徳を身につけるという生き方の重視。"},{"t":"つながり","ic":"→","v":"ソクラテス（師事）\nソクラテスに学び、徳にもとづく自足の生を継いだ。"}],"セクストス・エンペイリコス":[{"t":"核心","ic":"◈","v":"古代懐疑主義を体系的にまとめた哲学者・医師。判断を保留して心の平安に至る道を説いた。"},{"t":"本人の言葉","ic":"❝","v":"あらゆる主張には、等しい力の反対がある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ピュロン主義の懐疑論を、現存する著作によって体系的に伝えた哲学者。あらゆる主張には同じ重みの反対主張が立てられるとし、断定を差し控える判断保留(エポケー)によって、心の平静(アタラクシア)に至ると説いた。"},{"t":"築いた体系","ic":"✦","v":"独断論者が「真理を知った」と称するのに対し、判断を保留し続ける態度こそが動揺を鎮めると論じた。対立する議論を並べて釣り合わせる方法を整理し、近世のモンテーニュらの懐疑思想に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"エポケー(判断保留)　どちらとも決めず判断を差し控えること。懐疑主義の中心的態度。\nアタラクシア　判断保留の結果として訪れる、心の乱れのない平静。"},{"t":"つながり","ic":"→","v":"ピュロン（継承）\nピュロンの懐疑を体系的に整理し、後世へ伝えた。"}],"イアンブリコス":[{"t":"核心","ic":"◈","v":"新プラトン主義を宗教的・儀礼的に発展させた哲学者。哲学と神々への祈り(神働術)を結びつけた。"},{"t":"本人の言葉","ic":"❝","v":"魂は神へと上昇する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"新プラトン主義の哲学者。プロティノスの流れを受けつつ、単なる思索ではなく、儀礼を通じて魂が神的なものへ上昇する神働術(テウルギア)を重んじた。世界を段階的な神的秩序として精緻に体系化した。"},{"t":"築いた体系","ic":"✦","v":"一者から流出する存在の階層をいっそう細分化し、そのあいだを媒介する神々や霊的存在を位置づけた。理性だけでは超越に届かないとして、祈りと儀礼による実践を哲学に組み込み、後の思想や神学に影響した。"},{"t":"キーワード","ic":"⚑","v":"テウルギア(神働術)　儀礼や祈りを通じて魂を神的なものへ引き上げる実践。\n存在の階層　一者から下位へと段階的に広がる神的な秩序の体系。"},{"t":"つながり","ic":"→","v":"プロティノス（影響を受けた）\nプロティノスの流出論を受け継ぎ、儀礼的側面を加えた。"}],"エリウゲナ":[{"t":"核心","ic":"◈","v":"中世初期の神学者・哲学者。神と世界をひとつの大きな「自然」の展開として描いた、独創的な体系家。"},{"t":"本人の言葉","ic":"❝","v":"自然は、創るものと創られるものに分かれる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"カロリング朝期の神学者。ギリシア教父の思想をラテン世界に伝え、『自然の区分について』で、神から万物が生じ、また神へと還っていく壮大な体系を描いた。理性と信仰の調和を追求した中世初期の傑出した思想家。"},{"t":"築いた体系","ic":"✦","v":"存在するもの全体を「自然」と呼び、創るか創られるかで四つに区分した。神を万物の源にして帰り着く先とし、世界を神の自己展開と捉えるその思想は、後の汎神論的な神秘思想にも影響を残した。"},{"t":"キーワード","ic":"⚑","v":"自然の四区分　創り創られぬ神から、創らず創られぬ神への帰還までを四つに分けた枠組み。\n流出と帰還　万物が神から生じ、再び神へと還っていく運動。"},{"t":"つながり","ic":"→","v":"アウグスティヌス（影響を受けた）\nアウグスティヌスらの教父思想を受けつつ、独自の自然の体系を築いた。"}],"アルベルトゥス・マグヌス":[{"t":"核心","ic":"◈","v":"アリストテレスの著作を広く注釈し、自然を実際に観察した中世の大学者。トマス・アクィナスの師。"},{"t":"本人の言葉","ic":"❝","v":"経験こそ、自然を知る唯一の道である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドミニコ会の神学者・自然学者。アリストテレスの膨大な著作を注釈してラテン世界に紹介し、信仰と学問の橋渡しをした。植物や動物を自ら観察するなど経験的探究も重んじ、弟子トマス・アクィナスの大成を準備した。"},{"t":"築いた体系","ic":"✦","v":"アリストテレスの自然学・形而上学をキリスト教神学と統合しつつ、神学の領域と自然探究の領域を区別した。観察と経験を重視する姿勢は、後の自然科学的探究への道を開くものであった。"},{"t":"キーワード","ic":"⚑","v":"アリストテレス注釈　アリストテレスの全著作を解説し中世の学問に取り込んだ営み。\n経験的探究　自然を実際に観察して知ろうとする、経験重視の態度。"},{"t":"つながり","ic":"→","v":"アリストテレス（注釈）\nアリストテレスの全著作を注釈し、中世の学問に導入した。"}],"ボナヴェントゥラ":[{"t":"核心","ic":"◈","v":"フランシスコ会の神学者。愛と観想によって魂が神へ至る道を描いた、アウグスティヌス的な思想家。"},{"t":"本人の言葉","ic":"❝","v":"魂は段階を経て、神へと旅する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランシスコ会の神学者。アウグスティヌスの伝統を受け継ぎ、知性だけでなく愛と祈りによって魂が神へと上昇していく道を『神への魂の旅』に描いた。同時代のトマス・アクィナスとは対照的な神学の型を示した。"},{"t":"築いた体系","ic":"✦","v":"被造物のうちに神の痕跡を読み取り、外なる世界から内なる魂へ、さらに神へと段階的に高まる観想の道を説いた。理性を重んじつつも、その到達点を愛による神との合一に置いた点に特色がある。"},{"t":"キーワード","ic":"⚑","v":"神への魂の旅　被造物から内面へ、さらに神へと段階的に上昇する観想の道。\n神の痕跡　被造物のうちに映し出された、創り主である神のしるし。"},{"t":"つながり","ic":"→","v":"アウグスティヌス（継承）\nアウグスティヌスの愛と内面の伝統を受け継いだ。"}],"ロジャー・ベーコン":[{"t":"核心","ic":"◈","v":"中世に実験と数学の重要性を唱えた修道士・学者。近代科学の先駆けとされる。"},{"t":"本人の言葉","ic":"❝","v":"実験なしには、何ごとも十分に知りえない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランシスコ会の学者。当時の学問が権威や言葉に頼りすぎることを批判し、数学と実験による自然の探究を強く唱えた。光学や暦法などを研究し、経験にもとづく知の重要性を先駆的に主張した。"},{"t":"築いた体系","ic":"✦","v":"知識の源泉として、権威・理性に加え「経験」を重視し、実験による検証を学問の要と考えた。その主張は時代に先んじており、後の近代科学が実証を軸に据える方向を予感させるものであった。"},{"t":"キーワード","ic":"⚑","v":"実験の重視　言葉や権威ではなく、実際の試みによって知を確かめる方法。\n数学の応用　自然を数学的に捉え、諸学の基礎に据えようとする発想。"},{"t":"つながり","ic":"→","v":"アリストテレス（影響を受けた）\nアリストテレスの自然学を学びつつ、経験と実験を強く求めた。"}],"マンデヴィル":[{"t":"核心","ic":"◈","v":"個人の欲望や虚栄が、結果として社会全体を豊かにすると論じた思想家。『蜂の寓話』で知られる。"},{"t":"本人の言葉","ic":"❝","v":"私悪は公益なり。","by":""},{"t":"何を言ったか","ic":"⟲","v":"オランダ生まれでイギリスに移った思想家・医師。『蜂の寓話』で、贅沢や虚栄といった一見よくない欲望こそが商工業を刺激し、社会を繁栄させると論じた。道徳と経済の関係をめぐる後の論争を巻き起こした。"},{"t":"築いた体系","ic":"✦","v":"人間の利己的な情念を否定せず、それが意図せず公共の利益を生む仕組みに注目した。この逆説的な洞察は、アダム・スミスの見えざる手の議論など、後の経済思想へと引き継がれていった。"},{"t":"キーワード","ic":"⚑","v":"私悪は公益　個人の欲望や悪徳が結果として社会全体の繁栄を生むという逆説。\n意図せざる結果　個々人の思惑を超えて社会全体に生じる予期しない効果。"},{"t":"つながり","ic":"→","v":"アダム・スミス（影響を与えた）\n利己心が公益を生むという逆説は、見えざる手の議論を刺激した。"}],"コンディヤック":[{"t":"核心","ic":"◈","v":"人間の心の働きはすべて感覚に由来すると論じたフランス啓蒙の哲学者。ロックの経験論を徹底させた。"},{"t":"本人の言葉","ic":"❝","v":"すべての観念は、感覚から生まれる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランス啓蒙期の哲学者。ロックの経験論をさらに推し進め、思考も記憶も欲望も、もとをたどればすべて感覚から生じると論じた。何も知らない彫像に感覚を一つずつ与えていく思考実験で、心の成り立ちを描いた。"},{"t":"築いた体系","ic":"✦","v":"生得的な観念を認めず、心のあらゆる働きを感覚の変形として説明しようとした(感覚論)。人間の知の起源を経験に一元化するその立場は、フランス啓蒙の知識論に大きな影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"感覚論　心のあらゆる働きは感覚に由来するとする立場。\n彫像の思考実験　感覚を一つずつ与えられる彫像を通して、心の発生を描く仮想実験。"},{"t":"つながり","ic":"→","v":"ジョン・ロック（継承）\nロックの経験論を受け継ぎ、感覚論として徹底させた。"}],"マルサス":[{"t":"核心","ic":"◈","v":"人口は放っておくと食糧より速く増え、貧困や飢饉が避けられないと論じた経済学者・牧師。"},{"t":"本人の言葉","ic":"❝","v":"人口は、食糧よりも速く増える。","by":""},{"t":"何を言ったか","ic":"⟲","v":"イギリスの経済学者・牧師。『人口論』で、人口は掛け算的に、食糧は足し算的にしか増えないため、放置すれば貧困や飢饉が生じると論じた。楽観的な進歩観に警鐘を鳴らし、経済学と社会思想に強い影響を残した。"},{"t":"築いた体系","ic":"✦","v":"人口と資源の不均衡という視点から社会を分析し、貧困を個人の怠惰ではなく構造的な問題として捉える道を開いた。その議論は経済学の古典となり、後にダーウィンの生存競争の着想にも影響を与えた。"},{"t":"キーワード","ic":"⚑","v":"人口論　人口が食糧生産を上回って増える傾向から貧困を説明する理論。\n抑制　戦争や飢饉、道徳的自制など人口増加を抑える諸要因。"},{"t":"つながり","ic":"→","v":"アダム・スミス（継承）\n古典派経済学を受け継ぎつつ、楽観的な進歩観に警鐘を鳴らした。"}],"リカード":[{"t":"核心","ic":"◈","v":"古典派経済学を体系化した経済学者。貿易の利益を説く「比較優位」の理論で知られる。"},{"t":"本人の言葉","ic":"❝","v":"価値は、投じられた労働の量で決まる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"イギリスの経済学者。アダム・スミスを継いで古典派経済学を精緻に体系化した。商品の価値をそれに投じられた労働量で説明する労働価値説を展開し、各国が得意な分野に特化して交易すべきとする比較優位の理論を示した。"},{"t":"築いた体系","ic":"✦","v":"地代・利潤・賃金の分配を理論的に分析し、経済を抽象的なモデルとして扱う手法を確立した。その労働価値説はマルクスに、比較優位論は自由貿易論に受け継がれ、経済学の礎となった。"},{"t":"キーワード","ic":"⚑","v":"比較優位　各国が相対的に得意な財に特化して交易すると双方が利益を得るという理論。\n労働価値説　商品の価値を、それを生むのに要した労働量で説明する考え。"},{"t":"つながり","ic":"→","v":"アダム・スミス（継承）\nスミスの経済学を精緻化し、労働価値説と比較優位を示した。"}],"シュティルナー":[{"t":"核心","ic":"◈","v":"国家も道徳も神も「幻想」だとし、徹底して個人「わたし」を出発点に置いた思想家。"},{"t":"本人の言葉","ic":"❝","v":"わたしは、わたしの事柄を無の上に置いた。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツの思想家。『唯一者とその所有』で、神・国家・人類・道徳といった、個人に奉仕を強いる観念をすべて「亡霊」として退けた。何ものにも仕えない、かけがえのない「わたし(唯一者)」を思想の出発点に据えた。"},{"t":"築いた体系","ic":"✦","v":"ヘーゲル左派の議論を極限まで押し進め、あらゆる普遍的理念を個人を縛る幻想として批判した。その徹底した個人主義はマルクスとの論争を呼び、後の無政府主義や実存の思想にも刺激を与えた。"},{"t":"キーワード","ic":"⚑","v":"唯一者　いかなる理念にも還元されない、かけがえのない個としての自己。\n亡霊(固定観念)　神や国家など、個人を縛る抽象的な理念を批判的にこう呼んだ。"},{"t":"つながり","ic":"→","v":"ヘーゲル（批判した）\nヘーゲル的な普遍的理念を、個人を縛る幻想として退けた。"}],"プルードン":[{"t":"核心","ic":"◈","v":"「無政府主義」を自ら名乗った最初の思想家。権力による支配のない、相互扶助の社会を構想した。"},{"t":"本人の言葉","ic":"❝","v":"所有、それは盗みである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランスの社会思想家。『所有とは何か』で、他人の労働によらない大きな所有を批判し、みずから無政府主義(アナーキズム)を掲げた。国家の権力による支配を退け、人々が対等に契約し助け合う社会を構想した。"},{"t":"築いた体系","ic":"✦","v":"暴力革命ではなく、労働者どうしの相互扶助と自発的な連合によって社会を変えることを目指した(相互主義)。国家を必要としない秩序という構想は、後の無政府主義や協同組合運動に受け継がれた。"},{"t":"キーワード","ic":"⚑","v":"アナーキズム　国家の強制的な支配を否定し、自発的な秩序を目指す思想。\n相互主義　対等な個人どうしの契約と助け合いによって社会を組織する構想。"},{"t":"つながり","ic":"→","v":"マルクス（論争した）\n改良か革命かをめぐりマルクスと激しく対立した。"}],"ブレンターノ":[{"t":"核心","ic":"◈","v":"心の働きは必ず「何かについて」であるという志向性に注目した哲学者。現象学の源流。"},{"t":"本人の言葉","ic":"❝","v":"あらゆる心の働きは、何ものかへ向かっている。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ドイツの哲学者・心理学者。心の働きは常に何ものかを対象として向かっているという「志向性」を、心的なものの本質的な特徴として取り出した。経験にもとづく厳密な心理学を目指し、多くの後継者を育てた。"},{"t":"築いた体系","ic":"✦","v":"物理現象と区別される心的現象の指標を志向性に求め、意識の分析を厳密に進めた。この着想は弟子フッサールに受け継がれて現象学の中核概念となり、二十世紀哲学の出発点の一つとなった。"},{"t":"キーワード","ic":"⚑","v":"志向性　意識が常に何ものかへ向かっているという、心の働きの根本的性質。\n心的現象　物理現象と区別される、志向性をそなえた意識の働き。"},{"t":"つながり","ic":"→","v":"アリストテレス（影響を受けた）\nアリストテレスの心の理論を学び、志向性の着想を得た。"}],"ピーター・シンガー":[{"t":"核心","ic":"◈","v":"動物の苦しみや世界の貧困に、私たちがどう責任を負うかを鋭く問う現代の倫理学者。"},{"t":"本人の言葉","ic":"❝","v":"苦しむ能力こそ、配慮に値する境界である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"オーストラリアの倫理学者。功利主義の立場から、苦しむ能力をもつ存在の利益は等しく配慮されるべきだとし、動物の扱いや世界的な貧困への義務を論じた。実践に直結する議論で、動物解放や効果的な利他主義の運動を導いた。"},{"t":"築いた体系","ic":"✦","v":"ベンサム以来の功利主義を現代の具体的問題に適用し、種の違いを理由に配慮を差別する「種差別」を批判した。抽象的な理論にとどまらず、寄付や食のあり方といった日々の選択に倫理を落とし込む点に特徴がある。"},{"t":"キーワード","ic":"⚑","v":"種差別　人間以外という理由だけで配慮を軽んじることへの批判概念。\n効果的な利他主義　最も多くの苦しみを減らせる仕方で善を行おうとする運動。"},{"t":"つながり","ic":"→","v":"ベンサム（継承）\n苦しむ能力を配慮の基準とする功利主義をベンサムから継いだ。"}],"デレク・パーフィット":[{"t":"核心","ic":"◈","v":"「自分が同じ自分である」とはどういうことか、未来世代への責任とは何かを緻密に問うた哲学者。"},{"t":"本人の言葉","ic":"❝","v":"重要なのは同一性ではなく、心のつながりである。","by":""},{"t":"何を言ったか","ic":"⟲","v":"イギリスの哲学者。『理由と人格』で、人格の同一性を魂や連続する実体ではなく、記憶や意図の心理的つながりの問題として捉え直した。この分析をもとに、自己中心的な生き方や、未来世代への責任について再考を迫った。"},{"t":"築いた体系","ic":"✦","v":"思考実験を積み重ねて直観を吟味し、「同じ自分」という観念が思うほど確かでないことを示した。その帰結として、利己と利他の境界を問い直し、道徳理論の統合をめざす緻密な議論を展開した。"},{"t":"キーワード","ic":"⚑","v":"人格の同一性　自分が時を超えて同じ自分であることの根拠をめぐる問題。\n心理的連続性　記憶や意図のつながりによって人格の持続を説明する考え。"},{"t":"つながり","ic":"→","v":"カント（統合を試みた）\nカントらの道徳理論を統合しようと緻密に論じた。"}],"マーサ・ヌスバウム":[{"t":"核心","ic":"◈","v":"人が良く生きるために必要な力に注目し、正義や教育、感情の役割を論じる現代の哲学者。"},{"t":"本人の言葉","ic":"❝","v":"人が本当に何をなしうるかを問わねばならない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"アメリカの哲学者。アリストテレスの伝統を受け継ぎ、正義を単なる資源の分配ではなく、人が実際に何をなしうるか(潜在能力)から捉えるべきだと論じた。感情や物語、人文教育が良き生と民主主義に果たす役割を重視する。"},{"t":"築いた体系","ic":"✦","v":"人間の尊厳ある生に不可欠な諸能力のリストを示し、それを保障することを正義の課題とした(潜在能力アプローチ)。理性偏重を批判し、共感や文学がはぐくむ想像力を、公正な社会の基盤に据える点に特徴がある。"},{"t":"キーワード","ic":"⚑","v":"潜在能力アプローチ　人が実際になしうること・なれる状態から福祉や正義を測る枠組み。\n感情の知性　共感や物語がはぐくむ、倫理的判断に不可欠な想像力。"},{"t":"つながり","ic":"→","v":"アリストテレス（継承）\n人が力を開花させる良き生の思想をアリストテレスから受け継いだ。"}],"ガタリ":[{"t":"核心","ic":"◈","v":"精神分析と政治を横断し、ドゥルーズと組んで欲望や社会を新しく捉え直した思想家・活動家。"},{"t":"本人の言葉","ic":"❝","v":"欲望は、機械のように接続し生産する。","by":""},{"t":"何を言ったか","ic":"⟲","v":"フランスの精神分析家・思想家。ドゥルーズとの共著『アンチ・オイディプス』などで、欲望を抑圧されるものではなく、たえず接続し生産する力として捉え直した。精神医療の現場に関わりつつ、社会と心の関係を横断的に論じた。"},{"t":"築いた体系","ic":"✦","v":"個人の心を家族の枠に閉じ込める精神分析を批判し、欲望を社会や政治へと開いていく視点を示した。既成の秩序に回収されない多様な生のあり方を肯定し、生態や情報も含む幅広い思考(エコゾフィー)を展開した。"},{"t":"キーワード","ic":"⚑","v":"欲望する機械　欲望を、接続と生産をくり返す動的な働きとして捉える概念。\nエコゾフィー　環境・社会・心を結びつけて考える横断的な思考の枠組み。"},{"t":"つながり","ic":"→","v":"ドゥルーズ（共同）\nドゥルーズと共著を重ね、欲望の哲学を練り上げた。"}],"アガンベン":[{"t":"核心","ic":"◈","v":"権力が人の生をどう扱うかを、「剥き出しの生」という概念で鋭く分析する現代イタリアの哲学者。"},{"t":"本人の言葉","ic":"❝","v":"例外状態が、常態となりつつある。","by":""},{"t":"何を言ったか","ic":"⟲","v":"イタリアの哲学者。フーコーの権力論を継ぎ、法の保護を奪われて剥き出しにされた生(ホモ・サケル)に注目した。非常時を口実に通常の権利が停止される「例外状態」が現代の統治の常態になりつつあると警告した。"},{"t":"築いた体系","ic":"✦","v":"主権権力が、生を保護すると同時に排除しうる境界に人間を置くさまを歴史的に分析した。強制収容所を近代政治の隠れた範型と見なし、生をめぐる権力(生政治)の問題を先鋭に問い直した。"},{"t":"キーワード","ic":"⚑","v":"剥き出しの生　法や権利の保護を剥ぎ取られ、むき出しにされた生。\n例外状態　非常時を理由に通常の法秩序が停止される状態。"},{"t":"つながり","ic":"→","v":"フーコー（継承）\nフーコーの生政治の分析を受け継ぎ、剥き出しの生を論じた。"}],"G.H.ミード":[{"t":"核心","ic":"◈","v":"「自分」は他者とのやりとりを通じて形づくられると論じた社会心理学の祖。プラグマティズムの一人。"},{"t":"本人の言葉","ic":"❝","v":"自己は、他者との関わりの中で生まれる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"アメリカの哲学者・社会心理学者。自己とは生まれつきあるものではなく、言葉や身ぶりを介した他者とのやりとりの中で形づくられると論じた。他者の視点を自分の中に取り込むことで、人は自己を意識するようになるとした。"},{"t":"築いた体系","ic":"✦","v":"プラグマティズムの立場から、心や自己を社会的な相互作用の産物として捉えた。「一般化された他者」の視点を内面化することで社会規範が身につくとする分析は、社会学のシンボリック相互作用論の礎となった。"},{"t":"キーワード","ic":"⚑","v":"一般化された他者　社会全体の視点を内面化した、自己を映す他者の像。\n社会的自己　他者とのやりとりを通じて形成される自己のあり方。"},{"t":"つながり","ic":"→","v":"ウィリアム・ジェイムズ（影響を受けた）\nジェイムズらのプラグマティズムを社会心理学へと展開した。"}],"スタンリー・カヴェル":[{"t":"核心","ic":"◈","v":"日常の言葉や映画・文学を手がかりに、懐疑や自己を問い直したアメリカの哲学者。"},{"t":"本人の言葉","ic":"❝","v":"わたしたちは、言葉とともに世界に住まう。","by":""},{"t":"何を言ったか","ic":"⟲","v":"アメリカの哲学者。ウィトゲンシュタインの日常言語への注目を受け継ぎ、世界や他者を本当に知りうるかという懐疑の問題を、生活や表現の場面から捉え直した。ハリウッド映画やシェイクスピアをも哲学の主題として論じた。"},{"t":"築いた体系","ic":"✦","v":"懐疑を理論的に論破するのではなく、それとどう生きるかという実存的な問いとして受けとめた。哲学を専門的議論に閉じず、日常の言葉づかいや芸術に開いていく独自のスタイルを築いた。"},{"t":"キーワード","ic":"⚑","v":"日常言語　生活の中で実際に使われる言葉。哲学の出発点とされる。\n他者の承認　他人を知るより先に、その存在を認め受け入れるという課題。"},{"t":"つながり","ic":"→","v":"ウィトゲンシュタイン（影響を受けた）\nウィトゲンシュタインの日常言語論を実存的に読み直した。"}],"公孫龍":[{"t":"核心","ic":"◈","v":"「白馬は馬ではない」という有名な論で知られる、古代中国の名家(論理学派)の思想家。"},{"t":"本人の言葉","ic":"❝","v":"白馬は馬にあらず。","by":""},{"t":"何を言ったか","ic":"⟲","v":"戦国時代の名家(論理学派)を代表する思想家。「白馬は馬にあらず」など、名(言葉)と実(もの)の関係を鋭く分析する議論で知られる。言葉の指し示す範囲を厳密に問い、概念と対象のずれを浮き彫りにした。"},{"t":"築いた体系","ic":"✦","v":"名と実の対応を精密に論じ、言葉がものをどう区切るかを問う中国古代の論理的探究を推し進めた。その議論はしばしば詭弁と見なされたが、言語と実在をめぐる思索として独自の位置を占める。"},{"t":"キーワード","ic":"⚑","v":"白馬論　「白馬」は「馬」と別の名だとして名実の関係を問う議論。\n名実　言葉(名)と、それが指すもの(実)との対応をめぐる問題。"},{"t":"つながり","ic":"→","v":"荘子（同時代）\n言葉と実在をめぐり、荘子ら同時代の思想家と論を交わした。"}],"王充":[{"t":"核心","ic":"◈","v":"迷信や権威を批判し、事実にもとづく合理的な思考を説いた後漢の思想家。"},{"t":"本人の言葉","ic":"❝","v":"疑いをもって、虚妄をただす。","by":""},{"t":"何を言ったか","ic":"⟲","v":"後漢の思想家。主著『論衡』で、天が人の行いに応じて災いを下すといった当時の通念や、聖人を神格化する風潮を、道理と事実にもとづいて批判した。根拠のない言い伝えを疑う合理的・実証的な精神を貫いた。"},{"t":"築いた体系","ic":"✦","v":"天を意志をもたない自然的なものと捉え、吉凶を運命(自然のなりゆき)として説明した。権威や迷信を鵜呑みにせず検証を求める姿勢は、中国思想史における批判的合理主義の先駆となった。"},{"t":"キーワード","ic":"⚑","v":"疾虚妄　根拠のない虚偽や迷信を憎み、事実によってただそうとする態度。\n自然の天　意志をもたず、人の行いに応報しない自然としての天。"},{"t":"つながり","ic":"→","v":"董仲舒（批判した）\n天が人事に応報するという董仲舒的な説を事実によって批判した。"}],"黄宗羲":[{"t":"核心","ic":"◈","v":"君主の専制を鋭く批判し、民を本とする政治を説いた明末清初の思想家。"},{"t":"本人の言葉","ic":"❝","v":"天下は万民のものであり、君主一人のものではない。","by":""},{"t":"何を言ったか","ic":"⟲","v":"明末清初の思想家。王朝交代の激動を生き、『明夷待訪録』で君主が天下を私物化する専制を厳しく批判した。政治は万民のためにあるべきだとし、法制度や学校を通じた開かれた政治を構想した。陽明学の流れをくむ。"},{"t":"築いた体系","ic":"✦","v":"君主のための政治から民のための政治へと転換を説き、権力を制約する制度の必要を論じた。その先駆的な政治批判は、後の中国の改革思想にも影響を与えた。学問史の編纂にも大きな功績を残した。"},{"t":"キーワード","ic":"⚑","v":"民本　民衆を政治の根本に置き、支配は民のためにあるとする考え。\n君主批判　天下を私する専制的な君主権力への根本的な批判。"},{"t":"つながり","ic":"→","v":"王陽明（継承）\n陽明学の流れを受け継ぎ、実践と批判の精神を養った。"}],"達磨":[{"t":"核心","ic":"◈","v":"インドから中国へ渡り、禅宗を開いたと伝えられる僧。言葉より坐禅による直接の悟りを説いた。"},{"t":"本人の言葉","ic":"❝","v":"直に人の心を指し、性を見て仏となる。","by":""},{"t":"何を言ったか","ic":"⟲","v":"禅宗の初祖と伝えられる僧。インドから中国へ渡り、経典の解釈より、坐禅によって自らの心の本性を直接見つめることを重んじた。言葉や理屈を超えて、心から心へ真理を伝える禅の道を開いたとされる。"},{"t":"築いた体系","ic":"✦","v":"文字によらず(不立文字)、教えの外で心を直に指し示す(教外別伝)という禅の基本姿勢を体現した。壁に向かって坐り続けたという逸話に象徴されるその実践は、東アジアの禅の源流となった。"},{"t":"キーワード","ic":"⚑","v":"不立文字　真理は言葉や文字では伝えきれないとする禅の立場。\n面壁　壁に向かってひたすら坐禅する、達磨を象徴する修行。"},{"t":"つながり","ic":"→","v":"ブッダ(釈迦)（継承）\n仏の悟りを、坐禅による直接の体験として伝えようとした。"}],"貝原益軒":[{"t":"核心","ic":"◈","v":"健康の心得を説いた『養生訓』で知られる江戸時代の学者。庶民にも学びを広めた実学の人。"},{"t":"本人の言葉","ic":"❝","v":"みずから省みて、日々を慎む。","by":""},{"t":"何を言ったか","ic":"⟲","v":"江戸前期の儒学者・博物学者。朱子学を学びつつ、観察と経験を重んじる実学を志した。健康法をやさしく説いた『養生訓』や、動植物を調べた著作を残し、学問を庶民の暮らしに役立てようとした。"},{"t":"築いた体系","ic":"✦","v":"抽象的な理論より、日々の生活に生きる知を重んじ、教育や本草学(博物学)に力を注いだ。天地万物を貫く理を敬いながら、身近な自然を丹念に観察するその姿勢は、日本の実学の一つの型を示した。"},{"t":"キーワード","ic":"⚑","v":"養生　心身を慎み整えて健康に生きるための日々の心得。\n実学　暮らしや社会に役立つことを重んじる、実践的な学問。"},{"t":"つながり","ic":"→","v":"朱熹（継承）\n朱子学を学びつつ、暮らしに生きる実学へと向かった。"}],"ラーズィー":[{"t":"核心","ic":"◈","v":"医学と哲学に秀でたペルシアの学者。理性を何よりも重んじ、権威に頼らぬ独立の思考を説いた。"},{"t":"本人の言葉","ic":"❝","v":"理性は、神が人に与えた最良の贈り物である。","by":""},{"t":"何を言ったか","ic":"⟲","v":"ペルシアの医師・哲学者。臨床観察にもとづく優れた医学書を残す一方、哲学では理性を絶対的に重んじ、預言や権威に無批判に従うことを退けた。誰もが自分の理性で真理を探究できると説く、独立した合理主義者であった。"},{"t":"築いた体系","ic":"✦","v":"理性を人間に等しく与えられた導き手と見なし、盲目的な追従を批判した。医学では症例の観察と記録を重視し、経験にもとづく探究を実践した。その大胆な合理主義は、後世に議論を呼び起こした。"},{"t":"キーワード","ic":"⚑","v":"理性の重視　権威や伝統より、各人の理性を真理の導き手とする立場。\n臨床観察　患者を実際に観察・記録して知を積み上げる医学の方法。"},{"t":"つながり","ic":"→","v":"アル・キンディー（影響を受けた）\nアラビア哲学の先駆キンディーの合理的探究を受け継いだ。"}],"サアディア・ガオン":[{"t":"核心","ic":"◈","v":"ユダヤ教の教えを理性的に基礎づけた中世の学者。信仰と哲学の調和を先駆的に説いた。"},{"t":"本人の言葉","ic":"❝","v":"信仰と理性は、同じ真理へ導く。","by":""},{"t":"何を言ったか","ic":"⟲","v":"中世ユダヤ教の指導者・哲学者。イスラーム世界の合理神学(カラーム)に学びつつ、『信仰と意見の書』でユダヤ教の教義を理性によって基礎づけようとした。啓示と理性は矛盾せず、同じ真理へ至ると論じた先駆者である。"},{"t":"築いた体系","ic":"✦","v":"理性による探究と聖典の教えが調和することを示し、後のユダヤ哲学の道を切り開いた。聖書のアラビア語訳や言語研究にも取り組み、ユダヤの学問を体系的に整える大きな役割を果たした。"},{"t":"キーワード","ic":"⚑","v":"信仰と理性の調和　啓示された教えと理性的探究が同じ真理に至るとする立場。\n合理神学　教義を理性的な議論によって基礎づけようとする神学の営み。"},{"t":"つながり","ic":"→","v":"マイモニデス（影響を与えた）\n理性による教義の基礎づけは、後のマイモニデスを先取りした。"}]};
